WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[33656] = { title = "Talbuk Roundup", description = "My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped!\n\nThe little terrors could have slaughtered them in the cage, but they like to hunt their prey. I'm afraid that if I stay out here much longer, I'll be their next meal!\n\nWill you round up the talbuk and bring them here? I can't get them myself, and I can't let my dad find out about this!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue 4 Talbuk at Kuuros Farm." }
WordHunterWoW_QuestEN[33657] = { title = "Moving In", description = "Gorr'thog is now dead. It is time now to secure our hold on Bladespire Citadel. Meet me below and we can begin strengthening our presence.", objectives = "Meet Durotan at Bladespire Citadel.", completion = "You have accomplished great things. We could not have captured this citadel without you." }
WordHunterWoW_QuestEN[33658] = { title = "The Iron Missive", description = "<The missive outlines a plan to pollute Elekk Acres to ruin the Draenei food supply while their leader, Thokk, sends a force from a camp on the hill to the northwest to slaughter the remaining refugees.>\n\n<If you burn their supplies here and their forward camp with the torches they left here, you can buy precious time to organize a defense against the imminent attack!>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn the Iron Horde Supplies and the Iron Horde Camp." }
WordHunterWoW_QuestEN[33659] = { title = "Task: Put Down Poisoned Elekk", description = "", objectives = "" }
WordHunterWoW_QuestEN[33660] = { title = "The Sacking of the Saberon", description = "The stash mostly contains bits of old animal parts and other junk. Upon closer inspection there are remains of a bundle of herbs and plants.\n\nRakthoth might be more willing to help if some of these herb bundles were found and gathered for her...", objectives = "Find 8 Herb Bundles in saberon stashes at Steamscar Rise.", progress = "I need more reagents before I return to my brothers and sisters.", completion = "So they started storing their herbs in personal stashes instead of their storage dens, good to know.\n\nYou have helped me a great deal <name>." }
WordHunterWoW_QuestEN[33661] = { title = "Steamscar \"Reagents\"", description = "Now we get to the heart of the matter, heh. Saberon have strong hearts, our shaman find many uses for them.\n\nI will search for the ancient's magic if you get me those hearts. Do we have a deal?", objectives = "Collect 10 saberon hearts from living saberon at Steamscar Rise.", progress = "I will need those hearts <class>.", completion = "These are good strong hearts! You have done well <class> and I will hold my end of the bargain." }
WordHunterWoW_QuestEN[33662] = { title = "Beatface vs. Boulder", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a boulder, but it looks weak. A strong warrior, such as an ogre, could break it.\n\nI think you know an ogre gladiator...", objectives = "Break the boulder barrier using Beatface the gladiator.", completion = "Good work, but we need to move quickly before the plants realize the way is open..." }
WordHunterWoW_QuestEN[33663] = { title = "Shredder vs. Saberon", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a tangle of hard vines. I have heard you have a machine that could cut through that with ease.\n\nI would get on a shredder and take those vines down.", objectives = "Break the vine barrier using your shredder.", completion = "Good work, but we need to move quickly before the plants realize the way is open..." }
WordHunterWoW_QuestEN[33664] = { title = "Vignette: Gorum", description = "", objectives = "" }
WordHunterWoW_QuestEN[33684] = { title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", objectives = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.You will receive:" }
WordHunterWoW_QuestEN[33685] = { title = "Ambassador to the Ancient", description = "I have seen a tough looking \"tree\" in that growth. It cries and moans but does not act hostile.\n\nIt may know how to get rid of these plants. Go and see if it does.", objectives = "Talk to Birchus at Dionor's Demise in Gorgrond.", completion = "So that is why the saberon have barricaded themselves up there. They are good hunting <name>, and I want to get in there!\n\nI have an idea about that..." }
WordHunterWoW_QuestEN[33686] = { title = "That's No Podling", description = "<This leaf appears to have come from a plant hydra. The refugee sightings Beldos mentioned must have been true!>\n\n<If one got to the farm, the draenei refugees would stand no chance. Killing it now would buy valuable time for the refugees to reach safety.>\n\n<It must still be at the nearby podling den to the west.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Bloodthrasher." }
WordHunterWoW_QuestEN[33689] = { title = "Plant Pruning", description = "I have a hunting den not far from here where I gather my trophies as well as reagents for the Laughing Skull. Not long ago this giant plant monster charged in from the overgrowth and was killed by several of the giant rock monsters. Since it died smaller plant beasts have sprung up and made a mess of the place.\n\nThey have also cut me off from my best source of reagents. Kill them, I will attempt to reach my den and salvage what I can...", objectives = "Kill 12 defenders at Dionor's Demise.", progress = "Have you cleared a path yet?", completion = "They just keep coming back! I would hate to lose this hunting ground. We shall find a way to clear this growth, I swear it." }
WordHunterWoW_QuestEN[33693] = { title = "Tracking Quest: First Time at Capping Operation", description = "", objectives = "" }
WordHunterWoW_QuestEN[33694] = { title = "Reagents from Rakthoth", description = "The destruction of our village will not be easy to come back from. Our best hunter, Rakthoth, \"finds\" reagents for our shaman.\n\nShe has not been seen for some time and we need those more than ever. Go to her hunting grounds and see if she still lives.", objectives = "Find Rakthoth at Dionor's Demise in Gorgrond.", completion = "Marrow sent you? Our village destroyed? I would have been back already if it wasn't for these cursed plant beasts!" }
WordHunterWoW_QuestEN[33695] = { title = "Taking the Death Bloom", description = "You have helped me and now I will help you, {name}. The bloom you seek is within the nearby cave, being pawed over by the new leader of these saberon.\n\nKill him and take the bloom back to the ancient below. I hope this will clear out those plants and I can get back to my hunting...", objectives = "Take the Death Bloom from Smokemaster Snarl in Steamscar Rise.", progress = "Do you have something for me, little beast?", completion = "You have... you have brought me the bloom. At last my purpose can be fulfilled!" }
WordHunterWoW_QuestEN[33705] = { title = "Sacking the Saberon Stronghold", description = "[TEMP]Destroy the barricade and take back stuff!You will receive:", objectives = "Breach the last saberon wall and deal with what's on the other side.[TEMP]Destroy the barricade and take back stuff!You will receive:" }
WordHunterWoW_QuestEN[33706] = { title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", objectives = "Watch Birchus's ritual.", completion = "At last it is done.  Dionor has left and his spawn shall follow him in due time.\n\nI grow weary of this conflict and the desire to return to the Overgrowth has left me.\n\nPerhaps I will travel beyond these lands and see what other surprises you little beasts have to share..." }
WordHunterWoW_QuestEN[33707] = { title = "Demons Among Us - Horde", description = "If you are reading this, it means I have fallen in battle. As my last request, please deliver this letter to Thalia at Teluuna Observatory.\n\n\nDearest Thalia,\n\n\nYou have always been my best friend, ever since we were children growing up in Tuurem.\n\nI have always been too afraid to tell you my feelings, but I cannot leave this world without finally speaking the truth.\n\nThalia, I love you with all my heart.\n\nI shall wait for you in the next world. I will for eternity for you.\n\nLove,\n\n\nThamuunYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver Thamuun's Letter to Thalia at Teluuna Observatory.If you are reading this, it means I have fallen in battle. As my last request, please deliver this letter to Thalia at Teluuna Observatory.\n\n\nDearest Thalia,\n\n\nYou have always been my best friend, ever since we were children growing up in Tuurem.\n\nI have always been too afraid to tell you my feelings, but I cannot leave this world without finally speaking the truth.\n\nThalia, I love you with all my heart.\n\nI shall wait for you in the next world. I will for eternity for you.\n\nLove,\n\n\nThamuunYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33713] = { title = "TASK: Kill Ogre Slavers", description = "", objectives = "Kill 12 Stonemaul ogres." }
WordHunterWoW_QuestEN[33720] = { title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it in the cave on Talador beach until you've worked out the kinks.\n\nI will send Engineer Draxen to work on it in the meantime.\n\n- Orgrim Doomhammer", objectives = "Find the Decommissioned Iron Shredder in the nearby cave and take it from Engineer Draxen.", completion = "A prototype Iron Shredder, huh?! I bet we can get this thing working... they didn't have ME to fix it!" }
WordHunterWoW_QuestEN[33721] = { title = "Gazlowe's Solution", description = "I've identified some high value targets down in the forest below.\n\nWhen you get near one, you can deploy my solution.\n\nDeploy it and the objectives will be neutralized with great ceremony.", objectives = "Destroy the Thunderlord Cache, Blackrock Forge, and Munitions Landing.", completion = "I always love a good explosion." }
WordHunterWoW_QuestEN[33722] = { title = "Too Many Irons in the Fire", description = "We must not head into battle prematurely. Before we go after Orgrim, we must first deal with his troops.\n\nIf we are to succeed in our mission of wiping out the Iron Horde from Talador, we need to start on these shores.", objectives = "Kill 15 Iron Horde on Orunai Coast.", completion = "We will have fewer enemies to deal with at our backs. Lok'tar." }
WordHunterWoW_QuestEN[33724] = { title = "Vol. X Pages ?", description = "The manual for the shredder was wedged in there, but it's missing lots of pages. We need to find as many pages of that manual as possible and I might--MIGHT--be able to get this shredder operational.\n\nBased on the direction of the wind, I bet the pages flew toward Archenon Siegeyard.", objectives = "Find 20 Manual Pages at Archenon Siegeyard.", progress = "I don't know why those idiots don't just collect all the pages in one place.", completion = "Lots of detail... almost as if a goblin wrote it!" }
WordHunterWoW_QuestEN[33726] = { title = "Tuurem Task TBD", description = "", objectives = "" }
WordHunterWoW_QuestEN[33727] = { title = "Heal Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[33728] = { title = "An Eye for a Spy", description = "Excellent, excellent! I'll make sense of these manual pages and will get the Iron Shredder operational immediately!\n\nWhile I do that, take a look through my Eye 'n' Ear. That's where you'll be headed soon!", objectives = "Look through Gazlowe's Eye 'n' Ear.", progress = "Lots of orcs ready to be shredded!", completion = "Orgrim seems to be up to no good." }
WordHunterWoW_QuestEN[33729] = { title = "Born to Shred", description = "The Iron Shredder is operational! It should be primed and ready for you to shred our enemies in Tuurem!\n\nHead inside and see what damage you can do. Can't say I'm not jealous.", objectives = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", progress = "What's up, boss?", completion = "-- ENEMIES ELIMINATED --" }
WordHunterWoW_QuestEN[33730] = { title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", objectives = "Defeat Ketya Shrediron at Tuurem.", completion = "Gazlowe has been invaluable in securing Talador. Now, it is up to us." }
WordHunterWoW_QuestEN[33731] = { title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", objectives = "Repel the Iron Horde from Shattrath.", completion = "I cannot believe Orgrim is truly dead. Blackhand has carved a hole in my heart, and I intend to destroy him when the opportunity presents itself." }
WordHunterWoW_QuestEN[33732] = { title = "Sabotage Siege Weapons", description = "", objectives = "" }
WordHunterWoW_QuestEN[33733] = { title = "Karmaan", description = "You saw iron horde fighting the podlings!? That must be why the podlings are attacking here; they've been displaced!\n\nUnfortunately, they likely followed me and the other refugees from Tuurem to here. Light help me, I've doomed us all.\n\nWe should go tell Karmaan about this. If the iron horde is nearby, podlings might be the least of our problems.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Karmaan.You saw iron horde fighting the podlings!? That must be why the podlings are attacking here; they've been displaced!\n\nUnfortunately, they likely followed me and the other refugees from Tuurem to here. Light help me, I've doomed us all.\n\nWe should go tell Karmaan about this. If the iron horde is nearby, podlings might be the least of our problems.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33734] = { title = "Pieces of Us", description = "When the fires broke out, I took only my daughter's hand before we fled. It was the right decision, of course, but I do long for some of the things we left behind.\n\nI am an artificer, a shaper of crystals and gems. Without my tools I am just another refugee.\n\nOur town records are kept in a memory crystal in the main hall. With it, I can carry forward the knowledge and legacy of Aruuna.\n\nAlso, my daughter is terrified - it would be a great comfort for her to hold her favorite doll again.", objectives = "Retrieve the Crystal-Shaper's Tools, Melani's Doll, and the Annals of Aruuna.", progress = "These are more than mere objects. They are our livelihood, our past and future, our comfort.\n\nThey are pieces of us.", completion = "Thank you." }
WordHunterWoW_QuestEN[33735] = { title = "In Short Supply", description = "The enemy has explosive devices stored on the beach below. We must recover them so they are not used against us.\n\nReports indicate that crates of explosives are scattered along the shoreline.\n\nWhile you search, Durotan and I will carve deeper into Iron Horde territory.", objectives = "Collect 6 Iron Horde Explosives.", progress = "Have you found the Iron Horde Explosives yet?", completion = "I believe we can use these at Archenon Siegeyard." }
WordHunterWoW_QuestEN[33736] = { title = "Iron Them Out", description = "The orcs themselves are not the only threat. We may have weakened them considerably, but they still have siege weapons of significant power.\n\nSabotage siege weapons you find with the explosives you collected from the beach.", objectives = "Destroy 6 Iron Horde Siege Engines.", completion = "It is a relief to know that their weapons of war cannot be used against us." }
WordHunterWoW_QuestEN[33737] = { title = "Strike While the Iron Is Hot", description = "", objectives = "" }
WordHunterWoW_QuestEN[33740] = { title = "Burning Sky", description = "It happened so fast. A white-hot flash of light ignited the nearby woods, followed by terrible winds that swept the flames across Aruuna.\n\nMoments later, arakkoa began descending through the smoke.\n\nI need to get Melani to the Pilgrim's Road. From there we can head for Anchorite's Sojourn and the protection of the vindicators. With the arakkoa roaming the area freely, I fear we'll be run down or worse: taken by the spreading wildfires.", objectives = "Slay 12 Adherent Invaders in Aruuna and the Aruuna Crystal Mine.", completion = "Their deaths will not bring back Aruuna, but it does give me comfort to know that some among us can stand against them." }
WordHunterWoW_QuestEN[33746] = { title = "'kish Joins the Party", description = "The little guy sure does look happy. It's pretty clear he wants you to pet him. There is a spot right on the top of his head that isn't totally covered in rotten meat.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Invite Rooter to join your party." }
WordHunterWoW_QuestEN[33748] = { title = "Tracking Quest - Saberon Servent Snip Scene", description = "", objectives = "" }
WordHunterWoW_QuestEN[33749] = { title = "Quest Reward Summary: Train Depot", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[33750] = { title = "Quest Reward Summary: Pipeworks", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[33754] = { title = "Through the Looking Glass", description = "Your allies sent along a goblin, Gazlowe, to advise us against the Iron Horde. Thus far, he has proven a valuable asset.\n\nHe has a looking glass set up that can see a great distance and, he claims, even hear.\n\nUse this looking glass and report back what you've seen. I will stick to my standard spyglass.", objectives = "Look through Gazlowe's Eye 'n' Ear.", progress = "Take a look through Gazlowe's Eye 'n' Ear.", completion = "Orgrim leads these orcs? Why has he pledged himself to the Iron Horde?" }
WordHunterWoW_QuestEN[33755] = { title = "First Test Race: 2 Laps", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nThen do it all again. That's right - 2 laps!\n\nGood luck!You will receive:", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33756] = { title = "Let's Keep Racing!", description = "Want to keep racing, huh? That's the spirit!\n\nSee if you can beat your best time! Get to the blue post, then green, then red, then back here. \n\nYour time matters, so do it fast!", objectives = "Run through the Start Banner, hit the Blue Post, then the Green Post, then the Red Post, then return to the Start Banner.", progress = "You haven't hit all the markers. Hurry!", completion = "Good job, and nice time!" }
WordHunterWoW_QuestEN[33761] = { title = "Barum's Notes", description = "<This hefty tome contains notes on the refining and shaping of Draenor's natural gems and crystals, including several full-page technical diagrams depicting complex cut patterns.\n\nThe most recent pages detail a series of cuts intended to aid the draenei vindicators in battle.>\n\n\"...honed to a fine edge, the material can expose weaknesses...\"\n\n\"when rounded and polished to such a degree, it wards off harmful...\"\n\n\"...this incredible discovery that a crystal can be attuned to the bearer's vitality!\"", objectives = "Test the effects of a Honed Crystal, a Polished Crystal and a Harmonic Crystal in Aruuna.", progress = "Hm, what is that book you have there?", completion = "My notes! In the chaos, I completely forgot about them!\n\nThis is my life's work, <name>. I cannot thank you enough." }
WordHunterWoW_QuestEN[33765] = { title = "Dark Enemies", description = "Your arrival should be cause for celebration, hero, but I fear our troubles are just beginning.\n\nWarlord Ner'zhul and his Shadowmoon clan have launched a surprise attack on a draenei settlement to the north.\n\nProphet Velen has gone to aid the wounded at Teluuna Observatory, but we need more defenders.\n\nI must go to assist the others. If you wish to help us, go to Arbor Glen and kill any Shadowmoon enemies that you see.", objectives = "Kill 8 Shadowmoon Voidmancers.", completion = "The forests are clear of Shadowmoon enemies? Good. I knew that you would not fail." }
WordHunterWoW_QuestEN[33766] = { title = "The Thing in the Cave", description = "The note reads as follows:\n\n\"It cannot be defeated. No matter how many troops we send at it, it seemingly cannot be destroyed.\n\n\"We have lost too many lives as it is. I refuse to send another orc after that thing. Instead, we will establish a guard station outside the cave's mouth to keep it from getting out.\"You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay the Thing in the Cave, then loot its Dreadful Heart." }
WordHunterWoW_QuestEN[33767] = { title = "The Thing in the Cave", description = "The note reads as follows:\n\n\"It cannot be defeated. No matter how many troops we send at it, it seemingly cannot be destroyed.\n\n\"We have lost too many lives as it is. I refuse to send another orc after that thing. Instead, we will establish a guard station outside the cave's mouth to keep it from getting out.\"You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay the Thing in the Cave, then loot its Dreadful Heart." }
WordHunterWoW_QuestEN[33772] = { title = "6.0 Invasion Opt-Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[33781] = { title = "The Survivalist's Way", description = "I was tracking the Iron Horde's movements through the Iron March when I was spotted by one of their chimera riders.\n\nI was able to fight off their kill squad, but I'm too injured to keep going. Stranger, I must obtain as much recon as possible to aid in Karabor's defense.\n\nIf you can bring me silk from the worms and a handful of teeth from the rays at the lake nearby, I can operate on my wounds and fashion a bandage that ought to hold long enough for me to finish my mission.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Glowworm Silk and 12 Razorfang Teeth in The Arbitum in Shadowmoon Valley." }
WordHunterWoW_QuestEN[33782] = { title = "Keeping the Balance", description = "Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin.\n\nIt is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life.\n\nTrack down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.", objectives = "Kill Snapgrip in The Arbitum." }
WordHunterWoW_QuestEN[33783] = { title = "Kuuros Farm", description = "Many refugees from Tuurem have made their way to Kuuros Farm east of here.\n\nIf you are able, please venture there and find Beldos. He led the refugees there from Tuurem and will be the best point of contact.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Beldos at Kuuros Farm.Many refugees from Tuurem have made their way to Kuuros Farm east of here.\n\nIf you are able, please venture there and find Beldos. He led the refugees there from Tuurem and will be the best point of contact.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33784] = { title = "Gormaul Tower", description = "It is time for us to strike out against those who would enslave us!\n\nWe travel to Gormaul Tower to wrest it from the Bladespire ogres. I would welcome your company.\n\nMount up, and together we will ride to battle!", objectives = "Take Gormaul Tower from the Bladespire ogres.", progress = "You may ride with us and fight with our pack.", completion = "I now understand how you were able to rescue my clan from the clutches of slavery. Such power!" }
WordHunterWoW_QuestEN[33785] = { title = "Karg Unchained", description = "They took my brothers and sisters.\n\nThey took my wolf.\n\n<Karg lifts his axe and fixes his gaze upon its edge.>\n\nNow we take their heads.", objectives = "Slay 25 Thunderlord orcs in Grom'gar.", progress = "By killing them - we take their heads by killing them.\n\nWe don't actually need to pick up the heads.", completion = "<Karg scoops up a handful of snow and cleans the gore from his axe.>\n\nYou fight well." }
WordHunterWoW_QuestEN[33786] = { title = "Crippled Caravan", description = "I'm getting reports that the botani have started leaving their bloom and attacking wandering travelers. This is most unusual.\n\nWe already dispatched a number of rangari to try and resolve this issue.\n\nA caravan from Azeroth passed through here recently, you should probably check on your people to ensure their safety.", objectives = "Find Fiona's Caravan in Shadowmoon Valley.", completion = "Commander! Am I glad to see you.\n\nWe have a situation here." }
WordHunterWoW_QuestEN[33787] = { title = "Fiona's Solution", description = "Gidwin was attacked by one of those plant creatures.\n\nFrom the looks of it, he is suffering from some kind of paralysis.\n\nI can make a cure, but I'll need some local ingredients.", objectives = "Collect 1 Riverbeast Heart, 2 Swamplighter Venom, 4 Riotvine, and 3 Moonlit Herbs.", progress = "Do you have the ingredients?", completion = "Bang-up job, <name>! The base is just about ready." }
WordHunterWoW_QuestEN[33788] = { title = "Cooking With Unstable Herbs", description = "The base is boiling and ready for those ingredients.\n\nAdd each of the ingredients, one at a time, and I will handle the mixing and frothing. Speak to me when you are ready.", objectives = "Help Fiona brew a curative elixir.", progress = "Are you ready to begin?", completion = "Gidwin is looking much better. Thank you, <name>.\n\nWe have just enough elixir here to help the others." }
WordHunterWoW_QuestEN[33793] = { title = "Harbingers of the Void", description = "Our scouts have made a horrifying discovery, {name}.\n\nThe souls of the prisoners are being used to summon creatures from the void.\n\nInside, three beings of darkness already await - the Essence of Shadow, the Essence of Darkness, and the Essence of Anguish.\n\nThey must be destroyed immediately, before their power can be unleashed.", objectives = "Destroy the Essence of Shadow, Essence of Darkness, and Essence of Anguish.", progress = "The souls of innocents were used to birth the foul creatures. All that is depraved, and sick, and twisted in this world, are embodied within them.", completion = "I knew I could trust this task to you, <name>." }
WordHunterWoW_QuestEN[33794] = { title = "The Great Salvation", description = "We've located the prisoners. They are being held in captivity here, inside the Shadowmoon fortress.\n\nPlease rescue as many of them as you can. And hurry. We can hear their screams out here.", objectives = "Free 8 Draenei Prisoners from their cages.", completion = "We are taking care of the survivors now. We owe their lives to you. Thank you, <name>." }
WordHunterWoW_QuestEN[33795] = { title = "Across the Stars", description = "A key source of the Shadowmoon clan's power comes from their understanding of the stars and their omens.\n\nFor centuries, they have recorded the patterns of the stars and their interpretations.\n\nWhile you are in the fortress, collect some of these documents for me.\n\nWe will take their own knowledge and use it against them.", objectives = "Collect 5 Star Readings.", progress = "Your aid is appreciated, <class>.", completion = "Thank you. My acolytes will study these in great detail. With any luck, we will be able to use this knowledge to defeat the Shadowmoon." }
WordHunterWoW_QuestEN[33800] = { title = "Darren's Bombing Run of Awesomeness", description = "", objectives = "" }
WordHunterWoW_QuestEN[33807] = { title = "Free Our Brothers and Sisters", description = "These Thunderlord curs use coward's weapons like nets and chains.\n\nMany of our villagers and wolf-brothers and sisters have been trapped.\n\nIf you free them, they will fight at your side with honor.\n\nWe must quell this attack with haste so I may return to Bladespire Citadel and continue my preparations.", objectives = "Free 6 Frost Wolves or Wor'gol Villagers.", completion = "The Frostwolf clan cannot be held like beasts.\n\nYou fight with honor, <name>." }
WordHunterWoW_QuestEN[33808] = { title = "Swamplighter Queen", description = "It looks like those plant creatures used some kind of poison when they attacked Gidwin.\n\nIt's a powerful concoction to say the least.\n\nIf we are going to cure Gidwin we need one more special ingredient. This one might be a bit harder to obtain than the others.\n\nYou up to the challenge, {name}?", objectives = "Obtain The Swamplighter Queen's Tail for Fiona in Shadowmoon Valley.", progress = "I just wanted to pick some herbs and relax with my boys... I should have stayed in Azeroth.", completion = "Wow, that was fast! Ok, let's get to it!" }
WordHunterWoW_QuestEN[33813] = { title = "In Need of a Hero", description = "I...<sob>... I can't leave...<gulp>... without... Squiggy...!\n\nHe... he's... trapped!\n\nYou need... to put out... the fire!\n\n<Ariaana points across the room and bursts into tears.>", objectives = "Save Squiggy by dousing fires with buckets of water.", progress = "Squiggy... is... my... best... friend!", completion = "You did it! Squiggy is okay!" }
WordHunterWoW_QuestEN[33814] = { title = "Fast Expansion", description = "Greetings, Commander.\n\nI am here on behalf of architect Baros Alexston.\n\nWe have gathered enough resources for the next phase of expansion.\n\nHe wishes to speak to you at your earliest convenience.", objectives = "Report to Baros Alexston at your garrison in Shadowmoon Valley.", completion = "Ah, welcome, commander! Just the person I wished to see." }
WordHunterWoW_QuestEN[33815] = { title = "A Song of Frost and Fire", description = "You have rescued many of my clan from the slave pens of Tanaan. Their liberation and the destruction of the Dark Portal are more than enough for me to consider you one of us.\n\nHowever, you are still a stranger to our leader, Durotan. I would like to introduce you to him.", objectives = "Meet Durotan.", progress = "What a strange creature you are.", completion = "I thank you for returning with my people, and I welcome you as an honored guest." }
WordHunterWoW_QuestEN[33816] = { title = "Honor Has Its Rewards", description = "You have honored my people. Now, we wish to honor you.\n\nWe have a rite of initiation in my clan. When one comes of age, they cover themselves in the blood of their first hunt, and rest their hands upon a shamanstone to honor the ancestors who came before them.\n\nIn our brief time together you have already slain many foes more fierce than our hunters have ever had to face. Go, touch the shamanstone here in Wor'gol, and join our pack as an equal.", objectives = "Go to the Shamanstone in Wor'gol and receive a blessing.", progress = "Thank you for saving my clan.", completion = "If you choose to continue to help our clan, the other Shamanstones will sense your closeness to the Frostwolves and might bless you with more gifts." }
WordHunterWoW_QuestEN[33817] = { title = "Signs of a Struggle", description = "Judging by the markings, it appears to be a journal kept by a Shadowmoon orc.\n\n<Hagra disappeared last night. She is the fifth in as many nights. Why do they only vanish at night?>\n\n<I will find out. Tonight I wait for whatever manner of beast stalks our village.>\n\n<I will bring the beast's head to Rulkan, and return my kin to their homes.>\n\nPerhaps the beast's head is in one of the bags in the debris up ahead?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Ruffle through the backpack near the bloody journal." }
WordHunterWoW_QuestEN[33820] = { title = "Tracking Quest: Seen Escape Cinematic", description = "", objectives = "" }
WordHunterWoW_QuestEN[33822] = { title = "Laabru's Rebellion", description = "Laabru wouldn't listen. He killed one of the guards and they dragged him off to one of their tents.\n\nThey are going to kill him for sure!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Laabru at the Gar'mak Quarry in Shadowmoon Valley.Laabru wouldn't listen. He killed one of the guards and they dragged him off to one of their tents.\n\nThey are going to kill him for sure!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33823] = { title = "Tracking Quest - Archaeology - Frostfire - Dig Map #1", description = "", objectives = "" }
WordHunterWoW_QuestEN[33824] = { title = "Tracking Quest - Archaeology - Frostfire - Dig Map #2", description = "", objectives = "" }
WordHunterWoW_QuestEN[33825] = { title = "Tracking Quest - Archaeology - Frostfire - Dig Map #3", description = "", objectives = "" }
WordHunterWoW_QuestEN[33826] = { title = "Where's My Wolf?!", description = "My frost wolf, Nerok, was captured with me and the others. I do not know where they are keeping him, but I'll bet the so-called \"beastmaster\" who dragged us here does.\n\nHe is at the beast pens nearby, boasting about his catch to the younger hunters.\n\nWe'll see how he boasts with my axe in his skull.", objectives = "Slay Beastmaster Torash and free Nerok in Grom'gar.", progress = "I will not leave my frost wolf behind. Dead or alive, Nerok leaves this place with me.", completion = "Nerok and I are the only surviving prisoners, but we cannot leave just yet." }
WordHunterWoW_QuestEN[33828] = { title = "The Master Siegesmith", description = "Not long ago, the most advanced weapon a Thunderlord could make was a really, really big spear. The Blackrock orcs must have shipped in a fearsome master to have them producing cannons so rapidly.\n\nWe need to find that master.", objectives = "Slay Master Siegesmith Uratok in Grom'gar.", progress = "Karg is right - this is our best opportunity to cripple Grom'gar's defenses. We do this, then we return to the clan, heads high with pride.", completion = "The Iron Horde combines the strengths of every clan. We must continue looking for ways to sever those connections if we hope to defeat them." }
WordHunterWoW_QuestEN[33829] = { title = "zzOLD Honor Has its Rewards", description = "[PH] You have saved not only me, but our whole clan from the clutches of the Iron Horde.\n\nYou will find Shamanstones like the one beside me throughout our lands. They will now respond to your touch and you may receive a blessing from them while within Frostfire Ridge.", objectives = "[PH] Receive a blessing from the Frostwolf Shamanstone." }
WordHunterWoW_QuestEN[33833] = { title = "WANTED: Kuu'rat's Tusks", description = "Posted by: Eremor\n\nA ferocious elekk of unprecedented size has been seen near Gloomshade Grove.\n\nKnown to some as the ivory death, she is abnormally aggressive and has already taken the lives of several unwary travelers.\n\nThe rangari have as yet been unable to corner this creature. Anyone capable of taking down this beast should exchange proof of her demise to Eremor for a hefty bounty.", objectives = "Slay Kuu'rat and bring her tusks to Eremor at Embaari Village.", progress = "Are you here for the bounty on Kuu'rat?", completion = "The ivory death is slain? Impressive, traveler.\n\nThanks to you, we are all safer with Kuu'rat gone. I will share news of this deed with the other villagers." }
WordHunterWoW_QuestEN[33834] = { title = "WANTED: Kliaa's Stinger", description = "Posted by: Dyuna\n\nA vicious queen swamplighter has made the northern forests of Shadowmoon its home.\n\nUnfortunately, this poisonous pest terrorizes the forest between Embaari Village and Shattrath. As local traders put their lives at risk, prices of goods will continue to rise.\n\nAnyone who can put an end to the beast should detach its stinger as proof and bring it to Dyuna in Embaari Village. The merchant traders will reward generously.", objectives = "Kill Kliaa and bring its stinger to Dyuna at Embaari Village.", progress = "Word around town is you've been hunting Kliaa. Any luck?", completion = "By the elders of Karabor... that thing is huge!\n\nOur trade routes will be safe once again. Well... as safe as you can be running through the northern forests.\n\nWell done, <class>!" }
WordHunterWoW_QuestEN[33836] = { title = "WANTED: Maa'run's Hoof", description = "Posted by: Orrin\n\nA wild talbuk called \"Maa'run\" wanders the hills southeast of Embaari Village and west of The Draakorium.\n\nMy brother was injured by this foul beast, and now lays in recovery.\n\nFor the safety of all the nearby villages, we must put an end to this vicious, rampaging creature!\n\nA handsome reward will be given to anyone who can bring me his hoof as proof of his demise.", objectives = "Collect Maa'run's Hoof.", progress = "My brother, Anduur, gathers wild berries from the hills above our village.\n\nIt was during one of his excursions that he met up with Maa'run.\n\nI demand retribution for his injuries.", completion = "Thank you, adventurer! We can rest more easily knowing that this beast has been put to its end." }
WordHunterWoW_QuestEN[33837] = { title = "Darkness Falls", description = "It is already beginning, over the hills to the southeast.\n\nNer'zhul has everything he needs to summon the Dark Star. The Iron Horde attack on Karabor is imminent. This is where everything ends.\n\nChampion, I must ask you to ride ahead and delay Ner'zhul. I will join you as quickly as I can.", objectives = "Find Ner'zhul.", progress = "Today is the day that everything ends. But something new rises from the ashes.", completion = "Prophet Velen is gone, and yet there is no time to mourn.\n\nWe will honor Velen's passing once the Iron Horde have fled from these hills.\n\nNow, champion, is the time to fight!" }
WordHunterWoW_QuestEN[33838] = { title = "Smeltcraft", description = "Stranger! Thank the spirits for them sending you to me now. I am forging a blade and cannot leave it at this delicate state.\n\nBut I need more ore to complete this task.\n\nHere, take my mining pick. It is crafted from the teeth and acid of the local goren and will cut through the ore of this area as if it were air.\n\nBring me the ore and I will lend this blade to your cause.", objectives = "Use Na'Shra's Mining Pick to collect 20 Fomic Ore.", progress = "The power of a weapon comes both from the test of its metal and the skill of the hands that wield it.", completion = "Perfect timing. The steel of the blade is still malleable. A few more strikes and my work shall be complete." }
WordHunterWoW_QuestEN[33839] = { title = "Tracking Quest: Saw Naaru Purified", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33840] = { title = "The Plight of the Worgen", description = "King Greymane, my father, has fallen ill! Every day he's worse, losing control over his mind, becoming... feral. He's bedridden in Stormwind as we speak, and he isn't the only one.\n\nKrennan Aranas found what he thought might be the cure in Outland, but it was corrupted beyond recognition. I need to find the cure before he loses every bit of his humanity!\n\nHemma, one of my guards, is sick as well. I need you to collect some soothpetal flowers and frog eyes. We have to try something.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 6 Soothpetal Flowers and 8 Frog Eyes and bring them to Tess Greymane in Twilight Glade." }
WordHunterWoW_QuestEN[33843] = { title = "Vignette: Broodmother Reeg'ak", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy $1oa Goren Egg Clusters, $2oa Iceforge Ironchewers, and Broodmother Reeg'ak.Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33844] = { title = "The Pale Hunter", description = "Spiders!\n\nWhere is my father!\n\nI feel so... so... good? Bad? Don't judge me! Leave me alone! I'm sleeping... in my brain.\n\nAHH!! More bunnies!\n\n<The dwarves eyes are extremely dilated. She appears to be hallucinating. >You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Help Helga reclaim her sanity.Spiders!\n\nWhere is my father!\n\nI feel so... so... good? Bad? Don't judge me! Leave me alone! I'm sleeping... in my brain.\n\nAHH!! More bunnies!\n\n<The dwarves eyes are extremely dilated. She appears to be hallucinating. >You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33846] = { title = "Flag: Seen Thrall Cyclone", description = "", objectives = "" }
WordHunterWoW_QuestEN[33847] = { title = "Flag: Seen Ga'nar Rolling Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[33866] = { title = "Treasure: Veema's Herb Bag", description = "", objectives = "" }
WordHunterWoW_QuestEN[33867] = { title = "Treasure: Star-Reader's Box", description = "", objectives = "" }
WordHunterWoW_QuestEN[33868] = { title = "The Home of the Frostwolves", description = "You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.", objectives = "Speak with Drek'Thar at the crash site in Frostfire Ridge.", completion = "<The shaman grins at the harsh, windblown shore.>\n\nWelcome to the home of my people, <name>." }
WordHunterWoW_QuestEN[33869] = { title = "Treasure: Elekk Horn", description = "", objectives = "" }
WordHunterWoW_QuestEN[33871] = { title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far south of here, and fulfill your destiny.", objectives = "Speak to Seer Malune on Duskfall Island in Talador.", completion = "I am Seer Malune, the great keeper of memories. It is an honor to finally meet you." }
WordHunterWoW_QuestEN[33872] = { title = "Dust of the Dead", description = "I thought if I could just bring him here that I might be able to correct his transgression against the Light. That perhaps I could save my son! Now my beloved Arumel is a twisted phantasm.\n\nI'm left with no choice but to right my wrongs and I need your help.\n\nBring me duskwing dust from the moths on Duskfall Island. With your aid I can craft an elixir that will let us travel to the realm of the dead and lay Arumel to rest.", objectives = "Collect 7 Handfuls of Duskwing Dust from the Duskwing Moths on Duskfall Island.", progress = "Do you have enough dust?", completion = "Thank you, <name>. With this dust and Aruunem berries I will craft the draught of the dead." }
WordHunterWoW_QuestEN[33873] = { title = "Cure of Aruunem", description = "I need your help in creating an elixir that will allow us passage into the realm of the dead.\n\nIn order to create it I require a sampling of the local vegetation. You will find Aruunem berries scattered about on the island. Bring me as many as you can carry.\n\nBe warned, {name}: do not eat them raw! The poison in the berries would kill you within minutes!", objectives = "Collect 60 Aruunem Berries from around Duskfall Island.", progress = "Have you collected enough Aruunem berries?", completion = "I'm glad you did not eat any berries. I'm not sure what I would do if you were to die." }
WordHunterWoW_QuestEN[33874] = { title = "Aruumel's Rest", description = "It is my job to see what others cannot. I keep the memories and read them for others, but I can no longer do so because of my son.\n\nMy son turned his back on the light. When he perished I could not stand the thought that his spirit might not be welcomed into Auchindoun.\n\nI interfered and trapped him here. Now he twists and tortures the memories until they cannot be read.\n\nYou must do what I cannot bear to do myself. Use this elixir to enter the spirit realm...\n\n...and destroy my son's spirit.", objectives = "Enter the Spirit Realm and destroy the Memory of Arumel.", progress = "Is it done?", completion = "Some memories are better left forgotten. Thank you, <name>.\n\nI will return you to our world." }
WordHunterWoW_QuestEN[33875] = { title = "Goren, Goren, Gone!", description = "It's uncommon to see goren in Talador. We need to get a handle on this situation before it spreads and we lose all of our precious gems.\n\nThe only answer is to dispose of the creatures, and quickly!\n\nIt is imperative that you kill the leader too! If you don't they will just continue to come back.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 15 Goren Stonechewers and their leader, Pastrok within the Jorune Quarry." }
WordHunterWoW_QuestEN[33877] = { title = "Destroy Diggers [PH]", description = "This goren attack was horrible, but maybe we can learn from them. Maybe we can use this tragedy to our benefit.\n\nThe goren's primary weapon is a metal melting spit. You'll need to be careful in there, lest you loose that shiny armor!\n\nIt would be too dangerous to collect it when it's fresh, but maybe once it's solidified...\n\nSee if you can bring me a few samples.\n\nIf my hypothesis is correct we may be able to weaponize it against the Iron Horde.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Solidified Goren Spit Samples from the Jorune Quarry." }
WordHunterWoW_QuestEN[33878] = { title = "No Miner Left Behind", description = "In all of my years working the quarry I have never seen goren in this number. They came on so quickly, we had no time to react.\n\nNow the quarry has been weakened from their tunneling and eating. it's only a matter of time before the whole thing collapses.\n\nI refuse to leave anyone to die in there with those things! Please help me, <race>. Save as many of my miners as you can.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue 8 Jorune Miners from within the Jorune Quarry." }
WordHunterWoW_QuestEN[33879] = { title = "Goren, Goren, Gone!", description = "I was all set to take a little trip to the nearby quarry when all of the sudden a bunch of goren bust out of the ground and started wreaking havoc!\n\nIt would be a shame for all of those beautiful gems to be destroyed by those filthy creatures. All they do is eat them! Can you believe that?!\n\nBe a dear and dispose of them. Make sure you get rid of the leader or they will only come back.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy 15 Goren Stonechewers and their leader, Pastrok within the Jorune Quarry." }
WordHunterWoW_QuestEN[33880] = { title = "Collect Crystals [PH]", description = "The gems and crystals here are amazing! They're unlike anything I have ever seen. I've heard the Draenei can even trap memories within them.\n\nI have an idea that's crazy, but it just might work!\n\nI need crystal dust from the Jorune Quarry. I'm going to try and make mood gems with it. If the Draenei can trap a memory, how hard could it be to trap a mood?\n\nThey'll be beautiful and effective!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 10 Handfuls of Jorune Crystal Dust from within the Jorune Quarry" }
WordHunterWoW_QuestEN[33881] = { title = "Can't Live With 'Em, Can't Learn Without 'Em", description = "The Draenei here are so in touch with the light. It's imperative that we learn as much as we can from them.\n\nWe must find a way to overcome their distrust in us...\n\nThe Jorune Quarry was attacked by goren leaving many helpless miners trapped within. The miners aren't fighters and would probably appreciate help from anywhere at this point.\n\nMaybe if you lend a hand in rescuing them, we may earn ourselves some goodwill.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue 8 Jorune Miners from within the Jorune Quarry." }
WordHunterWoW_QuestEN[33882] = { title = "Just Peachicky", description = "That mean old Sher'khaan! He's always been a bully to these poor peachicks, but this is crossing the line!\n\nI was trying to move this poor clutch out of the way of the demons when he attacked! Now the peachicks are spread out all over and they're scared!\n\nPlease help me bring them all back!", objectives = "Rescue 7 Frightened Peachicks and return them to Caleb.", completion = "Oh thank you! Now these little peachicks can be moved to safety." }
WordHunterWoW_QuestEN[33883] = { title = "Treasure: Shadowmoon Treasure #2", description = "", objectives = "" }
WordHunterWoW_QuestEN[33884] = { title = "Sher'KHAAAAAAANNNN!", description = "The tigers here have gotten out of control! They're everywhere and meaner than ever!\n\nSher'khaan is the worst of them! He's huge and mean! Maybe a brave adventurer like you could take care of Sher'khaan and the other tigers once and for all.", objectives = "Kill 8 Sharpfang Stalkers and Destroy Sher'khaan.", completion = "You're so brave! I could never have taken Sher'khaan out on my own!\n\nNow I only have to worry about the scary orcs, giant birds, hippos, big bird men, spiders, everything being on fire...\n\nYa'know maybe I shouldn't be out here all by myself..." }
WordHunterWoW_QuestEN[33885] = { title = "Treasure: Harbor Treasure", description = "", objectives = "" }
WordHunterWoW_QuestEN[33886] = { title = "Treasure: Ronokk's Belongings", description = "", objectives = "" }
WordHunterWoW_QuestEN[33887] = { title = "Treasure: Mini-War Machine A", description = "", objectives = "" }
WordHunterWoW_QuestEN[33888] = { title = "Treasure: Mini-War Machine B", description = "", objectives = "" }
WordHunterWoW_QuestEN[33889] = { title = "Treasure: Mini-War Machine C", description = "", objectives = "" }
WordHunterWoW_QuestEN[33890] = { title = "Treasure: Mini-War Machine D", description = "", objectives = "" }
WordHunterWoW_QuestEN[33891] = { title = "Treasure: Moonwillow Seed", description = "", objectives = "" }
WordHunterWoW_QuestEN[33898] = { title = "Slaying Slavers", description = "These ogres keep takin' my clan and turnin' them into slaves!\n\nSlay some ogres and I'll hold 'em off if they try to run.", objectives = "Slay 12 Sootstained Ogres.", completion = "You got the fire in you alright." }
WordHunterWoW_QuestEN[33899] = { title = "Tracking Quest: Turn on the Holograms", description = "", objectives = "" }
WordHunterWoW_QuestEN[33900] = { title = "Tracking Quest: Activated Arkonite 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[33901] = { title = "Tracking Quest: Activated Arkonite 4", description = "", objectives = "" }
WordHunterWoW_QuestEN[33903] = { title = "Tracking Quest: Romuul & Yrel Leave for Teluuna", description = "", objectives = "" }
WordHunterWoW_QuestEN[33904] = { title = "Balance of Power", description = "The Prophet needs to locate the arkonite crystals, but in order to do that, I'll need to fix the projection discs on that platform.\n\nSpeak to my assistants around the observatory and bring me an Optical Disc, a Conducting Crystal, and my wrench.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Romuul's assistants to collect an Optical Disc, Conducting Crystal, and Romuul's Wrench." }
WordHunterWoW_QuestEN[33905] = { title = "Closing the Door", description = "The Shadowmoon orcs are using portals to bring in reinforcements and smuggle away draenei captives.\n\nIf we are to have any hope of retaking the village, we must destroy the portals at once.\n\nThe only way to do this is to kill the portalmasters who keep the rifts open.", objectives = "Close 3 Void Portals by killing Shadowmoon Portalmasters.", progress = "Breaking the fabric of space is extremely costly magic. It must rend their very souls.", completion = "Wonderful. That should slow down the attack.\n\nOur forces should be able to retake the forest quickly." }
WordHunterWoW_QuestEN[33906] = { title = "War Kangaroo!", description = "test", objectives = "test" }
WordHunterWoW_QuestEN[33907] = { title = "The Power Shards", description = "I know what the Bonechewer are after.\n\nAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.\n\nThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.\n\nGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Shard of Souls in the Tomb of Souls." }
WordHunterWoW_QuestEN[33908] = { title = "The Power Shards", description = "I know what the Bonechewer are after.\n\nAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.\n\nThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.\n\nGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Shard of Souls in the Tomb of Souls." }
WordHunterWoW_QuestEN[33909] = { title = "Flag: Seen Ga'nar Rolling Out to Bladespire", description = "", objectives = "" }
WordHunterWoW_QuestEN[33910] = { title = "Aklana Rescue", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33911] = { title = "No Draenei Left Behind", description = "Yuuri, head caretaker of the outer terraces of Auchindoun, hasn't been accounted for yet.\n\nThe last time anyone saw him, he was heading into the Tomb of Souls to protect the key shard. Will you make sure he finds his way here safely?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Yuuri near the Tomb of Souls in the Court of Souls.Yuuri, head caretaker of the outer terraces of Auchindoun, hasn't been accounted for yet.\n\nThe last time anyone saw him, he was heading into the Tomb of Souls to protect the key shard. Will you make sure he finds his way here safely?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33913] = { title = "Desperate Times", description = "This alliance between the Bonechewer and Teron'gore does not bode well.\n\nWe cannot allow the remaining two key fragments to fall into their hands. The Auchenai cannot stop the onslaught, so the duty falls on us.\n\nLet us waste no time. We ride for the Tomb of Lights at once.", objectives = "Ride to the Tomb of Lights with Lady Liadrin." }
WordHunterWoW_QuestEN[33914] = { title = "Gut Guttra", description = "Guttra Wolfchew's hunger can be blamed for this massacre. He will pay with his life for the blood spilled today. \n\nYou can find Guttra up on Grimfrost Hill to the north. Slay him and return to me.\n\nWhen you get back we shall drink to our victory.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Guttra Wolfchew." }
WordHunterWoW_QuestEN[33915] = { title = "Young Hearts", description = "My nephew never pays attention to his surroundings. In his eagerness to prove himself, he has strayed from the pack -- again.\n\nHe reminds me of myself when I was a youngling.\n\nIf you see Orac, tell him to return home. We need to finish preparing for tomorrow's hunt.", objectives = "Find Orac and tell him to return home to his uncle.", completion = "Thank you, <name>. I'm sure Orac will think twice before he strays from the pack again." }
WordHunterWoW_QuestEN[33916] = { title = "Treasure: Arena Master's Warhorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[33917] = { title = "Disrupting the Flow", description = "You there, we need to stop the flow of demon reinforcements!\n\nDo you see the floating fel crystals spread throughout the front? Those resonators are powering the portals unleashing hell on our forces. I need you to take them out!", objectives = "Destroy 4 Burning Resonators in the Burning Front.", progress = "We can't hold out forever!", completion = "We can take it from here. Light's blessings to you, <class>." }
WordHunterWoW_QuestEN[33918] = { title = "WANTED: Grondo's Bounty", description = "Grondo, a mad gronn, has been seen roaming the Crackling Plains.\n\nThis beast has been killing entire herds of clefthoof and devouring innocent frost wolves. We must destroy this threat before it reaches the Garrison.", objectives = "Kill Grondo in the Crackling Plains.", completion = "Very good. We don't be needin' a gronn bearin' down on us before we get our defenses all established." }
WordHunterWoW_QuestEN[33919] = { title = "WANTED: Gutsmash the Destroyer", description = "Gutsmash has proven to be more than a worthy adversary. Gather a small group together and end his reign of terror once and for all.", objectives = "Kill Gutsmash the Destroyer in Frostfire Ridge.", completion = "Gutsmash is dead? I'll drink to that. You're alright, <name>." }
WordHunterWoW_QuestEN[33920] = { title = "The Heart of Auchindoun", description = "A band of Shadow Council orcs stole the Heart of Auchindoun!\n\nThe Heart powers all of Auchindoun's defenses. Thankfully we were able to save its core and one of its four pieces.\n\nThe warlock O'mogg Blackheart is using Karab'uun, one of the stolen pieces, to power the largest portal in the Burning Front. Return Karab'uun to me.", objectives = "Defeat O'mogg Blackheart and retrieve Karab'uun in the Burning Front.", progress = "I trust you have Karab'uun. I am not known for my patience when the countless souls inside Auchindoun are in danger.", completion = "<Soulbinder Nyami's lips curl into a smile.>\n\nWell done. Only two pieces remain. I've already dispatched my soulbinders to track them down." }
WordHunterWoW_QuestEN[33921] = { title = "Stolen Axes", description = "The saberon usually keep to themselves, but sometimes they range out of their dens and attack.\n\nA pride of them live in the Windswept Lowland and have been coming too close for comfort, especially at night.\n\nThey even attacked a shipment of axes and took them back to their den!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover 8 Stolen Frostwolf Axes." }
WordHunterWoW_QuestEN[33923] = { title = "Demons? In Auchindoun?", description = "Demons! I feared as much.\n\nWe cannot let them leave that tomb. They musn't be allowed near Auchindoun!\n\nQuickly, go in and shut down the portal letting them in while I help rally the Auchenai's defenses. There must be a powerful warlock keeping it open. Kill him and the portal will fall apart!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill O'mogg Blackheart in the Tomb of Lights to shut down the demon portal." }
WordHunterWoW_QuestEN[33924] = { title = "Saberon Matriarch", description = "The current matriarch of the Windswept Lowland saberon pride is bold.\n\nShe leads her pride in ambushes and attacks that some consider organized raids on our supply lines.\n\nThe intelligence she displays  is becoming a legitimate threat.\n\nTake her out and perhaps she'll be replaced with a less dangerous leader.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay the Saberon Pridematron." }
WordHunterWoW_QuestEN[33925] = { title = "Treasure: Frostwolf Cache 01", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33926] = { title = "Treasure: Lagoon Pool", description = "", objectives = "" }
WordHunterWoW_QuestEN[33927] = { title = "Draenei Camp Explosion Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33928] = { title = "A Wrong of Earth and Fire", description = "The molten core appears to be the mutated remains of an elemental that consisted of both earth and fire.\n\nSlag elementals should not exist upon the plateau where the elements live in purity.\n\nYou decide that the core should be taken to Incineratus at the Throne of Elements for examination.\n\nPerhaps the great fury of fire will know what to make of this core and your battle with Magmire.", objectives = "Deliver the Molten Core to Incineratus.", completion = "<Incineratus examines the core as you explain the circumstances behind its acquisition>\n\nIndeed, slag elementals should not exist upon the plateau. The plateau has grown unstable, causing the elemental spirits there to devolve and mutate.\n\nSo long as an earthen fury is absent from the throne, the imbalance in the elements will worsen.\n\nGordawg must return to the Throne of Elements if balance is to be maintained." }
WordHunterWoW_QuestEN[33929] = { title = "Shivertail's Den", description = "The Frostwolf pup looks at you with his big eyes. He howls and stares into the cave.\n\nIt's unusual for a wolf this young to be wandering around by itself. Shivertail's parents must be nearby.", objectives = "Search for Shivertail's parents in Frostfire Ridge.", progress = "Shivertail smells your boots.", completion = "Shivertail snuggles up to his mother. He is clearly happy to be reunited with most of his pack." }
WordHunterWoW_QuestEN[33930] = { title = "Treasure: Saberon Stash", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33931] = { title = "This Is Not a Quest", description = "We need help! But not from you...", objectives = "Help Deceptia", completion = "Haha!" }
WordHunterWoW_QuestEN[33933] = { title = "Treasure: Deceptia's Smoldering Boots", description = "", objectives = "" }
WordHunterWoW_QuestEN[33938] = { title = "Vignette: Ogre Primalist", description = "", objectives = "" }
WordHunterWoW_QuestEN[33940] = { title = "Treasure: Crag-Leaper's Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[33942] = { title = "Treasure: Frostwolf Cache 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[33943] = { title = "Outrider Urukag", description = "I can't believe I'm stuck here cooking while Urukag is out there hunting with the others.\n\nIf you hurry you might still be able to catch him, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Join Urukag on his hunt.I can't believe I'm stuck here cooking while Urukag is out there hunting with the others.\n\nIf you hurry you might still be able to catch him, <name>.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33944] = { title = "And the Elekk Too?!", description = "The little stuffed elekk has seen better days. It's torn and the stuffing is poking out.\n\nThe name Caleb is sewn onto the bottom of the left back foot. Sher'khaan must have snatched it from the cart. The little draenei might appreciate its return.", objectives = "Return Ricky to Caleb at the overturned cart.", progress = "Where did you find Ricky?!", completion = "Oh thank you, mister! I can't believe Sher'khaan got Ricky!\n\nYou're my hero!" }
WordHunterWoW_QuestEN[33945] = { title = "Treasure: Frostwolf Cache 03", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33946] = { title = "Treasure: Frostwolf Cache 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[33947] = { title = "Treasure: Grimfrost Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[33948] = { title = "Treasure: Goren Leftovers", description = "", objectives = "" }
WordHunterWoW_QuestEN[33949] = { title = "Treasure: Frostwolf Cache 07", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33952] = { title = "The Hunting Party", description = "Korga and her brothers have been out hunting for days and have not returned.\n\nThis is a common problem amongst our clan.\n\nCall them in so they can get some proper rest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find the Frostwolf Hunters in the Windswept Lowland.Korga and her brothers have been out hunting for days and have not returned.\n\nThis is a common problem amongst our clan.\n\nCall them in so they can get some proper rest.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33954] = { title = "The Bloodmaul Scheme", description = "<This parchment contains crudely written notes detailing the Bloodmaul Clan's future plans.\n\nRogash will know what to do with this information.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver the Ogre Plans to Rogash." }
WordHunterWoW_QuestEN[33955] = { title = "Missing Pack", description = "Strange, I wonder where little Shivertail and his pack are? They normally show up for a feeding about now.\n\nI hope everything is alright.", objectives = "Find Shivertail near Wor'gol in Frostfire Ridge.", completion = "You startle the small pup." }
WordHunterWoW_QuestEN[33956] = { title = "Missing Frostwolves", description = "<name>, I'm glad you're here.\n\nSeveral Frostwolf patrols have gone missing recently around the Bloodmaul Compound. Search the area around Bloodmaul and report back to me when you're done.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search Bloodmaul for the missing Frostwolves.<name>, I'm glad you're here.\n\nSeveral Frostwolf patrols have gone missing recently around the Bloodmaul Compound. Search the area around Bloodmaul and report back to me when you're done.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33957] = { title = "A Gift for Raa'la", description = "I need to pack up this kill.  I promised my daughter Raa'la I would bring her home a gift from the hunt.\n\nThere are a couple baby Rylaks in the cave nearby. Maybe Raa'la would like one as a pet?\n\nWould you mind catching one while I finish up here?", objectives = "Collect a Baby Rylak for Raa'la in the Windswept Lowlands." }
WordHunterWoW_QuestEN[33958] = { title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", objectives = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari.", progress = "Did the demon have Sha'tari as we thought?", completion = "Just as I suspected. Thank you, <name>. With Sha'tari back in our possession there is only one piece of the Heart left to retrieve." }
WordHunterWoW_QuestEN[33959] = { title = "You Sunk My Battleship!", description = "They sunk my battleship, <name>!\n\nI drove her in with a cargo of underwater explosives to place on the Iron Horde ships, but they spotted me and opened fire! Luckily I was able to salvage most of the explosives before she sank. Ain't nobody sinks my ship and gets away with it...nobody!\n\nTake the rest of the underwater charges and plant all of 'em on the western Battleship. You'll have to swim your way into the harbor to avoid detection.\n\nWhen you're done, swim into shore. I'll be waiting on the path!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Plant the Underwater Explosives on the Iron Horde boats." }
WordHunterWoW_QuestEN[33960] = { title = "Talador Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33961] = { title = "Frostfire Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33962] = { title = "Shadowmoon Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33963] = { title = "Nagrand Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33964] = { title = "Arak Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33965] = { title = "Tanaan Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33966] = { title = "Gorgrond Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[33967] = { title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", objectives = "Collect 9 Deathweb Fangs in Deathweb Hollow.", progress = "Do you have the fangs? We don't have much time!", completion = "Bless you, <name>. There have been enough innocent lives taken today." }
WordHunterWoW_QuestEN[33968] = { title = "Goren Boss Kill and Collect", description = "<Light bounces from within the gem creating rainbows on the nearby walls.>\n\nThis curious looking gem seems to have fallen from Pastrok's back. Perhaps a skilled gem-shaper or jewelcrafter would have a use for it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[33969] = { title = "Vile Defilers", description = "The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information.\n\nOur scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions!\n\nWe must destroy the defiling crystals so this madness does not spread.", objectives = "Destroy 5 Defiling Crystals in Deathweb Hollow.", completion = "We were wise to not underestimate the threat of a land turned against us." }
WordHunterWoW_QuestEN[33970] = { title = "Into the Hollow", description = "I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front.\n\nOne of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari, one of the remaining pieces of the Heart of Auchindoun.\n\nI need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.", objectives = "Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari.", progress = "Did the foul demon have Sha'tari as we thought?", completion = "Just as I suspected. Thank you, <name>. With Sha'tari back in our possession there is only one piece of the Heart left to retrieve." }
WordHunterWoW_QuestEN[33971] = { title = "Antivenin", description = "I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else.\n\nI'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention!\n\nPlease, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.", objectives = "Collect 9 Deathweb Fangs in Deathweb Hollow.", progress = "Do you have the fangs? We don't have much time!", completion = "Bless you, <name>. There have been enough innocent lives taken today." }
WordHunterWoW_QuestEN[33972] = { title = "Vile Defilers", description = "The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims.\n\nWe are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions!\n\nWe must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!", objectives = "Destroy 5 Defiling Crystals in Deathweb Hollow.", progress = "The last thing we need is the monstrous creatures of this land joining the Legion's fold.", completion = "<Mehlar smiles.>\n\nIt would seem that the tide of this war is shifting in our favor." }
WordHunterWoW_QuestEN[33973] = { title = "Dying Wish", description = "I am too far gone to rescue, but thank you for speaking with me.\n\nBlademaster Bralok had his men starve and beat me, and he stole an heirloom that has been in my family since before we arrived on Draenor.\n\nShould you find it, please let me see it once more so I may die in peace.", objectives = "Recover Ahm's Heirloom from Blademaster Bralok.", progress = "The Blademaster must pay...", completion = "Thank you. Now that I know it is out of the hands of the Iron Horde, I can die peacefully." }
WordHunterWoW_QuestEN[33974] = { title = "Dying Wish", description = "This appears to be an ancient Draenei heirloom. Blood stains on it would indicate that it was taken from its owner by force.\n\nAn inscription on the back says \"Ahm,\" which is likely its rightful owner.", objectives = "Speak to Ahm at Archenon Siegeyard." }
WordHunterWoW_QuestEN[33975] = { title = "Treasure: Blasting Charges - Rubble A", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33976] = { title = "The Final Piece", description = "I am too injured to fight, {class}. I have failed my city and its people. This battle is yours.\n\nVorpil waits just ahead. He's trying to use Auch'naaru's powers for some sort of dark ritual.\n\nYou must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!", objectives = "Take Auch'naaru from Vorpil Ribcleaver in Telmor.", progress = "We need the final piece of the Heart!", completion = "Well done! I will take Auch'naaru to Auchindoun. The Shadow Council has no place in our lands." }
WordHunterWoW_QuestEN[33977] = { title = "Blessing of the Wolf", description = "", objectives = "" }
WordHunterWoW_QuestEN[33978] = { title = "Spirit of the Wolf", description = "", objectives = "" }
WordHunterWoW_QuestEN[33979] = { title = "Buffeting Galefury", description = "", objectives = "" }
