WordHunterWoW_QuestEN[34004] = { title = "Hansel, Report", description = "I have Hansel directing our counter-fire against the Iron Horde's war machines.\n\nI need to know what's going on and why some of the orcs slipped through. He's down the hill to the north.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Hansel Heavyhands at Bastion Rise in Gorgrond.I have Hansel directing our counter-fire against the Iron Horde's war machines.\n\nI need to know what's going on and why some of the orcs slipped through. He's down the hill to the north.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34006] = { title = "Build Us A Backdoor", description = "According to the prisoner here, the Stonemaul ogres are providing slaves and supplies to the Iron Horde. No creature should live a life in chains! And to add insult to injury, Orgrim Doomhammer is here to discuss terms with them!\n\nI sent my wolf Nightstalker ahead to find a weakness. If there is another way in, he will find it.\n\nGo, find my wolf near walls of the Stonemaul camp south of here. Test their defenses.\n\nIf you cannot find us a way in, then make one.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Help Nightstalker find a weak spot in the Stonemaul Slave Camp walls.According to the prisoner here, the Stonemaul ogres are providing slaves and supplies to the Iron Horde. No creature should live a life in chains! And to add insult to injury, Orgrim Doomhammer is here to discuss terms with them!\n\nI sent my wolf Nightstalker ahead to find a weakness. If there is another way in, he will find it.\n\nGo, find my wolf near walls of the Stonemaul camp south of here. Test their defenses.\n\nIf you cannot find us a way in, then make one.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34008] = { title = "We Are Leaving!", description = "We have who we came for. Find the others. Tell them to get back to the caravan as soon as possible.\n\nIt will not be long before the ogres figure out how few of us there actually are. We will wait for you at the front gates.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "We have who we came for. Find the others. Tell them to get back to the caravan as soon as possible.\n\nIt will not be long before the ogres figure out how few of us there actually are. We will wait for you at the front gates.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34012] = { title = "Need More Teeth", description = "<Prowler Sasha silently holds out his hand to reveal a necklace crafted of stained leather and putrid brown ogre teeth. All have a matching tone of rot to them.>\n\n<It has several knots that appear to be missing additional teeth.>", objectives = "Collect 30 Putrid Brown Ogre Teeth.", progress = "<Prowler Sasha stares at you with cold, merciless eyes.>", completion = "<Prowler Sasha nods and assembles two necklaces.>" }
WordHunterWoW_QuestEN[34013] = { title = "Never Forget", description = "We had to escape Telmor with what few we could save.\n\nSomeone disabled Leafshadow's cloaking field; I know not who, but I suspect it had to have been one of our own.\n\nWe will retrieve our livelihoods in time, but we cannot risk losing our sacred artifacts.\n\nIf you are able, bring Leafshadow, our town registry, and our prayerbook to safety.", objectives = "Recover the Telmor Registry, the Auchenai Prayerbook, and Leafshadow in Telmor.", progress = "Some things are worth fighting for, <race>. These are such things.", completion = "With these, we can account for our fallen and rebuild. We will persevere." }
WordHunterWoW_QuestEN[34019] = { title = "Shadows Awaken", description = "We've managed to pin Ner'zhul inside the Observatory, but he's taken many down with him.\n\nHe has taken Yrel's sister, Samaara.\n\nI am needed to hold the line here. Please, do whatever you can to save her, hero.", objectives = "Confront Ner'zhul.", progress = "The Shadowmoon clan's aggression began when the Iron Horde arrived on Draenor.", completion = "Your aid in retaking Teluuna Observatory has not gone unnoticed, hero. I grow increasingly impressed at your prowess in battle.\n\nPerhaps you could share some of your knowledge with my disciples. They could learn much from a seasoned adventurer such as yourself.\n\nI have something for you, as a thanks for what you've done even in the short time you've been here. Perhaps it will help you get this garrison of yours on its feet." }
WordHunterWoW_QuestEN[34024] = { title = "Fungal Heart", description = "The second ingredient I will need for the elixir is harder to obtain.\n\nAlong the river roam Marsh Giants - fungal monstrosities whose hunger is never sated. I will need three of their hearts.\n\nThe stronger the heart, the more potent the mixture, and the clearer my vision.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 3 Fungal Hearts." }
WordHunterWoW_QuestEN[34025] = { title = "Nuke Bastion Rise Tracking Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[34026] = { title = "Garrison Campaign: Seismic Matters", description = "One of our junior surveyors has been harassing me about unusual seismic activity. I find it hard to believe that we accidentally built on some kind of fault line - we triple checked!\n\nCan you have a word with him?", objectives = "Speak with Jr. Surveyor Dorn at your garrison.", completion = "Ach! Sir <name>, ye've arrived just in time!" }
WordHunterWoW_QuestEN[34027] = { title = "Groundbreaking Data", description = "Aye, we triple-checked the site before we set up here. Nary a peep from the ol' earthly deep.\n\nBut there's been rumblin's today, and they're gettin' closer! I tell ya somethin' ain't right!\n\nYe don't have to take my word for it - the Tremor-Tracker is just about finished collecting data. Check it out an' see fer yerself!", objectives = "Use the Tremor-Tracker in your garrison.", progress = "Go on, check out the Tremor-Tracker! It ain't gonna bite ye.", completion = "I KNEW somethin' was wrong! IN YER FACE, Alexston!\n\nAh, excuse me.\n\nNow, where have I seen machines like this before?\n\nOh yeah! The Dark Iron!" }
WordHunterWoW_QuestEN[34028] = { title = "These Look Familiar...", description = "So what is the Iron Horde doing with Dark Iron technology? I know who ta ask!\n\nThaelin Darkanvil is a genius engineer from the Dark Iron clan who's been helping us here on Draenor. You may have already met him in yer travels, eh?\n\nWord is he set up a bunker somewhere in Gorgrond, a secret workshop so-to-speak. If ye can find him, he may know somethin' about this.\n\nEr, and be cautious, eh? The Dark Iron may be our allies now, but I trust 'em about as far as I can throw 'em.", objectives = "Find Thaelin's Workshop in Gorgrond.", completion = "Mmf! Mm- mff!!\n\n<You remove his gag.>\n\nTHEY GOT THAELIN!!" }
WordHunterWoW_QuestEN[34029] = { title = "The Prototype", description = "A few days ago a bunch of Iron Horde orcs showed up and kidnapped Thaelin. They've been keeping me alive as collateral to make sure he cooperates.\n\nI don't know where they took him, but I know how to get us there.\n\nThaelin keeps a tracking device on him at all times - don't ask where he hides it. Anything he makes that can move has a \"Come to Papa\" button that sends it straight to him.\n\nIn retrospect, not a great feature for the walking bombs... but perfect for the mole machine! Jump in and let's go!", objectives = "Use the Prototype Mole Machine to look for Thaelin Darkanvil.", completion = "Close enough!" }
WordHunterWoW_QuestEN[34030] = { title = "The Captive Engineer", description = "Argh... I'm sorry, {name}, but I'm too weak to fight. They kept me alive, but just barely.\n\nI'll keep an eye on the mole machine while you look for Thaelin. He should be somewhere close!", objectives = "Find Thaelin Darkanvil in the Iron Siegeworks.", completion = "<name>! Oh, yer a sight for sore eyes!\n\nThe prototype mole machine was able to track me here all the way from the shop? I even impress myself sometimes.\n\nNow that I know Hansel is safe, I can enact the brilliant escape plan I've been working on. Glad to have ye here for this!" }
WordHunterWoW_QuestEN[34031] = { title = "Something to Remember Me By", description = "The Iron Horde want my inventions so bad? Then we'll leave some behind.\n\nThese little beauties will blow the treads clear off a tank AND melt her chassis into the dirt. Let's see them try and drive their shoddy cannons out of this place!", objectives = "Place 4 Dark Iron Mines in the Iron Siegeworks.", progress = "Don't be shy with those mines, I got plenty.", completion = "For the record, the mines don't have any voice commands.\n\nI learned that lesson awhile back..." }
WordHunterWoW_QuestEN[34032] = { title = "Privileged Information", description = "I'm not the only prize the Iron Horde brought back after raiding my workshop.\n\nOverlord Blackhammer, the maniac in charge of this operation, took my notebook as his own personal treasure.\n\nManufacturing techniques; schematics for new inventions; embarrassing doodles.\n\nIt's got all my secrets!\n\nCan I count on you to help me get it back?", objectives = "Loot Thaelin's Notebook from Overlord Blackhammer in the Iron Siegeworks.", progress = "That book has my working notes from the last five years. It's too dangerous to leave behind!", completion = "Aye, there she is.\n\nThank you, <name>. Let's get out of here, shall we?" }
WordHunterWoW_QuestEN[34033] = { title = "And The Mole You Rode In On", description = "I think we've kept Hansel waiting long enough. Can you take me to him? Then we can all hitch a ride out of here on the mole machine.", objectives = "Bring Thaelin Darkanvil to Hansel Heavyhands in the Iron Siegeworks.", completion = "So I guess it's safe to say my old workshop is compromised. We'll have to find a new place to set up shop..." }
WordHunterWoW_QuestEN[34034] = { title = "Garrison Campaign: Grinding Gears", description = "Commanda! Da Frostwolf orcs at Thunder Pass have reported a horrible grinding noise boomin' tru da canyon. We suspect it's some kind of Iron Horde war machine.\n\nGazlowe has agreed ta investigate, but he be wantin' a cash bonus. Goblins! Meet wit him at Thunder Pass and deliver dis payment.", objectives = "Deliver Gazlowe's Payment to Gazlowe near Thunder Pass.", progress = "Yo! You got the dough?", completion = "<Gazlowe's face brightens as you hand over the bulging bag of coins.>\n\nHeyyy! Now we're talking!\n\nI usually prefer not to get my hands dirty, but for that kind of cash you could get me to field-strip a kor'kron outhouse.\n\nGlad to have some muscle here to back me up - and since I'm such a nice guy, here's a little somethin' for your troubles." }
WordHunterWoW_QuestEN[34035] = { title = "I Know The Drill!", description = "It's a machine alright. A drill - a BIG one! Fortunately, we don't have to take apart the whole thing.\n\nThey're relying on forced induction, using twin superchargers to pipe extra boost into the engine. Without that boost, the drill is useless.\n\nGet in there and open the clutch on the back of the drill. That'll draw some attention away from the turbines.\n\nI'll take care of the turbines - you just worry about the hordes of bloodthirsty orcs.", objectives = "Help Gazlowe sabotage the Iron Stonegrinder.", progress = "You ready to roll?", completion = "Ya know... this thing is actually pretty impressive.\n\nThe drive system seems... familiar..." }
WordHunterWoW_QuestEN[34039] = { title = "WANTED: Overlord Blackhammer", description = "So, we COULD just leave now. We got what we came for, and I even did a little charity work to help Thaelin escape.\n\nBut there's also this.\n\n<Gazlowe holds up a scrap of paper showing a hand-drawn depiction of an especially mean looking orc.>\n\nIt's an SI:7 bounty for one Overlord Blackhammer, who just happens to operate out of this very facility. You help me take him out, I pay you. Then I take his head to the Alliance and collect on the bounty. Everyone wins!\n\nWell, everyone except for Blackhammer.", objectives = "Slay Overlord Blackhammer in the Iron Siegeworks.", progress = "You aren't getting cold feet on me now, are ya?", completion = "<Gazlowe fishes around in his pouch before producing a single gold piece.>\n\nErr... looks like I'm a little short. Personal bodyguard fees really add up!\n\nI'll give you a proper cut when we get back to your garrison. Come on, you know I'm good for it!" }
WordHunterWoW_QuestEN[34040] = { title = "Maker's Mark", description = "I don't get it - most of the Iron Horde junk is about as advanced as strapping cannons to a gronn. Even the drill itself is nothing special. But that induction system was a work of art...\n\nThis don't add up at all!\n\nDespite my better judgment, I gotta find out who made this. I wanna look at more of what they got in the Iron Siegeworks, see if anything's been signed.\n\n<Gazlowe pats the sack of coins on his belt.>\n\nWhaddaya say? Wanna be my bodyguard?", objectives = "Inspect 5 Siege Parts in the Iron Siegeworks.", progress = "You get paid when we get out of this place alive.", completion = "That's Darkanvil's signature! I knew I'd seen that work somewhere before.\n\nThaelin Darkanvil is a Dark Iron dwarf who came to Draenor with the Alliance forces, and a damn brilliant engineer. We have what you might call a friendly rivalry.\n\nBut why's Thaelin making weapons for the Iron Horde?" }
WordHunterWoW_QuestEN[34041] = { title = "Four Finger Discount", description = "I gotta admit, establishing a supply chain to a primal world on the wrong side of time is tough, even for me. Gotta make due with, uh... \"locally sourced\" goods.\n\nSay what you want about the Iron Horde, but when it comes to raw materials, they got connections!\n\nKeep an eye out for some of the more valuable goods in the Iron Siegeworks. I packed a few rocket chickens we can use to send the good stuff back to your garrison.", objectives = "Steal a Blackrock Cog, Condensed Geyser Gas, and a Carbonfrost Flamecore from the Iron Siegeworks.", completion = "Not a bad haul. Here's yer cut!" }
WordHunterWoW_QuestEN[34042] = { title = "A Fellow Gearhead", description = "There's no way Thaelin sold out. NO way! They gotta be holdin' him here somewhere.\n\nCome on, {name}. I know he's with the Alliance, and I know they aren't your favorite people, but we do NOT want the Iron Horde having access to his work - trust me!", objectives = "Find Thaelin Darkanvil in the Iron Siegeworks.", progress = "You gotta respect your fellow gearheads!\n\nPlus, I made a TON of money copying those walking bombs he designed.\n\nEr... you didn't hear that last part.", completion = "Don't worry, Thaelin can handle himself. That was my good deed for the year - don't tell nobody!\n\nHey... you think I can write off that fuel as a business expense?" }
WordHunterWoW_QuestEN[34043] = { title = "Darkest Night", description = "This keystone will grant its bearer entry into Anguish Fortress.\n\nTake it and meet Prophet Velen outside the Shadowmoon fortress.\n\nHe intends to face Ner'zhul head-on.", objectives = "Speak to Prophet Velen at Anguish Fortress.\n\nProvided item:", completion = "Good, you've arrived. Rulkan's message said that you would not be long." }
WordHunterWoW_QuestEN[34047] = { title = "Tuurem Explosion Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[34048] = { title = "\"Mole Machine, Go Home\"", description = "My patented \"Come to Papa\" voice command was only the first step.\n\nI also programmed all of my mole machines with a \"Go Home\" command that'll send 'em auto-diggin' to a pre-determined location - my workshop in Gorgrond!\n\nLet's send the mole machines home before the orcs stink 'em all up with their stupid breath and their sweaty... leather... thongs.\n\n<You hear Thaelin gagging a little from inside The Suit.>\n\nBlech!", objectives = "Send 5 Mole Machines home from the Iron Siegeworks.", progress = "If the voice command fails, you can always try the manual override.\n\nYe simply hold down the control pedal, shift into reverse, and pull the escape lever at the same time.", completion = "There, my beauties are safely out of the hands of the Iron Horde. No more orcs poppin' out of the ground!\n\nThere's just one more thing I need to do before I can leave with a clear conscience." }
WordHunterWoW_QuestEN[34053] = { title = "SoL Conversation Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[34054] = { title = "The Dark Side of the Moon", description = "<Prophet Velen's voice continues.>\n\nYrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", objectives = "Find Ner'zhul.", progress = "Ner'zhul will pay for what he has done.", completion = "We saved everyone we could, <name>. We were too late for the others... including my sister.\n\nProphet Velen is right. When it is asked of us, we ALL must fight. I promise this: I will never again let my loved ones suffer.\n\nNer'zhul is close to calling down the Dark Star. We are the only ones who can stop him." }
WordHunterWoW_QuestEN[34055] = { title = "Origin Unknown", description = "For my first field assignment, I would say I'm doing quite well!\n\nI've discovered a strange portal in this cave that has unleashed a number of equally strange void creatures, and there's no clear reason why! Fascinating, isn't it?\n\nScientific inquiry aside, these things may be benign right now, but at the rate they're pulling energy in that won't last long.\n\nI need you to take them out, send their essences back to... wherever it is they came from, and shut down that portal!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 4 Voidborne Errants in Waning Crescent. Afterwards, shut down the portal in Waning Crescent." }
WordHunterWoW_QuestEN[34059] = { title = "Keeping Calm", description = "My husband, one of our shaman, went to the ritual cave just below the village to seek the advice of our ancestors.\n\nJust before you arrived I heard sounds of fighting coming up from there. I fear that one of Ner'zhul's agents has attacked him!\n\nPlease, will you go find him and return him home safely?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Kaduz in the Cave of Spirits below Palemoon Village and rescue him from Ner'zhul's agent." }
WordHunterWoW_QuestEN[34060] = { title = "Krasarang RRP - Daily Vignette - Rogue Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[34061] = { title = "Krasarang RRP - Daily Vignette - Priest Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[34062] = { title = "Krasarang RRP - Daily Vignette - Warrior Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[34063] = { title = "Enemies Above", description = "We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf {name}, but we can not rest yet.\n\nThe Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us.\n\nI sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. \n\n Lok'tar {name}!", objectives = "Speak with Scout Ruk'gan near the Bones of Agurak.We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf <name>, but we can not rest yet.\n\nThe Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us.\n\nI sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. \n\n Lok'tar <name>!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34064] = { title = "The Search For Drogguk", description = "Drogguk has taken it upon himself to watch the Iron Horde's movement to ensure they do not find our village.\n\nIt has been two days and he has not yet returned. If you are willing, I would ask that you seek him out and bring him home. His family worries.\n\nHe tends to make his post roughly southeast of here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Drogguk in the Iron March." }
WordHunterWoW_QuestEN[34066] = { title = "Savage Vengeance", description = "The Thunderlord are a blight {name}.\n\n<Ruk'gan spits in disgust.>\n\nMy daughter, Grishna, was killed by those monsters. Only their blood will bring me peace now.\n\nIf you would help me then I need you to cause a distraction so I can sneak to a position closer to their camp.\n\nKilling a few of their so called \"Iron Thunderguard\" would be perfect.", objectives = "Kill 10 Iron Thunderguards within the Bones of Agurak in Frostfire Ridge.", completion = "You have done well, <class>.\n\nNow before we can continue our assault we need to look for any supplies in the area that could help our fight." }
WordHunterWoW_QuestEN[34067] = { title = "A Collection of Coils", description = "This coil of rope has been woven thick, the better for the Thunderlord Wranglers to handle the dangerous beasts they tame.\n\nScout Ruk'gan might have a use for this and a few more like it.", objectives = "Gather 5 Coils of Sturdy Rope from Thunderlord Wranglers in the Bones of Agurak.", progress = "I'm growing tired of waiting, do you have anything to help our assault or not?", completion = "Rope? Do you expect me to tie a noose and ask the Thunderlords to go hang themselves?\n\nWait... that gives me an idea. Yea, I think I can make this work with the right materials.\n\nGood Job." }
WordHunterWoW_QuestEN[34068] = { title = "Vignette: Rockhoof", description = "", objectives = "" }
WordHunterWoW_QuestEN[34069] = { title = "Getting the Points", description = "The Thunderlord Spear is extremely light and strong.\n\nScout Ruk'gan might be able to use this and a few more like it.", objectives = "Gather 5 Thunderlord Spears within the Bones of Agurak.", progress = "What is it <class>? Have you got something for me?", completion = "Hrm, yes these spears look pretty good.\n\nNot bad! I know just what to use these for!" }
WordHunterWoW_QuestEN[34070] = { title = "At the End of Your Rope", description = "With the spears and rope you gathered the Thunderlord Sky Riders will no longer be out of our reach. Even they will feel our wrath!\n\nI've tied the rope to the spears you brought me to fashion a harpoon. Hunt the Sky Riders that are flying all over the valley. Take the Harpoon and throw it at them as they circle by. If your aim is true the barbs should allow the spear a firm hold allowing you to yank the rider right towards you!\n\nIf your aim is bad... well... try not to miss.", objectives = "Use the Barbed Harpoon to unseat and kill 5 Thunderlord Sky Riders.", completion = "Well done <name>! The removal of the Sky Riders takes the heat off us for a bit. Keep your weapon in hand though, we're not done with them yet." }
WordHunterWoW_QuestEN[34072] = { title = "Tar Get of Opportunity", description = "General Vul'gath leads this band of Thunderlord. He is a coward and hides in his hut, yelling orders at his warriors through the walls.\n\nWe will need to show him that his flimsy defenses can not stand against the Frostwolves!\n\nI'll need some tar to carry this out. There are a couple of tar pits to the south, go gather a few globs from the oozes that reside there and bring them to me.", objectives = "Gather 5 Globs of Sticky Tar from the Black Tar's in the Bones of Agurak.", progress = "We need that tar soon <name>! Get to it!", completion = "Ugh, those smell awful! No, I don't need to see them. I'll take you at your word that you have them all.\n\nLet's get a move on before another Thunderlord patrol stumbles upon me." }
WordHunterWoW_QuestEN[34073] = { title = "Burn Them Down", description = "Now, we begin our assault, {name}!\n\nGet down to Agurak's Fall and use these tarbombs to destroy their rylak egg incubators.\n\nWhile you are busy I will sneak down into their camp and prepare for the next phase of our attack. Meet me there once you have burned everything.", objectives = "Burn down the Thunderlord Rylak Incubators within Agurak's Fall.", completion = "Good job <name>, I was able to use the commotion from your work to sneak into the camp.\n\nNow we have only one thing left to do." }
WordHunterWoW_QuestEN[34074] = { title = "The Iron March", description = "", objectives = "" }
WordHunterWoW_QuestEN[34075] = { title = "Vul'gath's End", description = "Vul'gath's time has come to an end, {name}. My daughter's blood is upon his hands, now his blood will be on ours!\n\nShow no mercy and strike him down!", objectives = "Kill General Vul'gath within Agurak's Fall.", completion = "Thank you,<name>.\n\nI wish we could bring him back just to kill him again but I guess this will suffice.\n\nI hope the spirit of my little one will now know peace." }
WordHunterWoW_QuestEN[34076] = { title = "The Burial Fields", description = "", objectives = "" }
WordHunterWoW_QuestEN[34077] = { title = "Trouble to the South", description = "A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower.\n\nTo be frank, I'm concerned for their safety. This area is still crawling with Iron Horde.\n\nThey could surely use your help if you're able. Follow the road south and you should find their position.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Captain Renault south of Pilgrim's Sojourn in Shadowmoon Valley.A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower.\n\nTo be frank, I'm concerned for their safety. This area is still crawling with Iron Horde.\n\nThey could surely use your help if you're able. Follow the road south and you should find their position.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34078] = { title = "Payment Due for Services Rendered", description = "I'm ready to get outta here, and I ain't hoofin' it back through all those orcs.\n\nFortunately, I kept a few extra rocket chickens to get us back to your garrison in style! Let's get up to the roof and find a decent place to take off.", objectives = "Bring Gazlowe to the roof of Overlord Blackhammer's fortress in the Iron Siegeworks.", completion = "Told you I was good for it!" }
WordHunterWoW_QuestEN[34079] = { title = "Mission Successful", description = "The Thunderlords are finished {name} and our job is complete. I'll stay here and watch over the area.\n\nYou should head back to Sergeant Gil'nath. I'm certain he will have another task for you.", objectives = "Speak to Sergeant Gil'nath in Frostfire Ridge.The Thunderlords are finished <name> and our job is complete. I'll stay here and watch over the area.\n\nYou should head back to Sergeant Gil'nath. I'm certain he will have another task for you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34080] = { title = "Return To Sender", description = "This tiny tracking device is used to collect biological data. It appears to have been fastened to a dart and fired from long range.\n\nAfter closely examining the device, you are able to trace the signal to a receiver nearby. The information contained within could be important; it's probably a good idea to find the owner and return it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return the Subdermal Tracking Device." }
WordHunterWoW_QuestEN[34083] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[34084] = { title = "Keeping Calm", description = "<These beads must belong to Kaduz, the shaman you rescued. They are engraved with the name \"Dulga\".>\n\n<He said to meet him in nearby Palemoon Village. You will surely find both Kaduz and Dulga there.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Dulga in Palemoon Village.<These beads must belong to Kaduz, the shaman you rescued. They are engraved with the name \"Dulga\".>\n\n<He said to meet him in nearby Palemoon Village. You will surely find both Kaduz and Dulga there.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34087] = { title = "Through the Looking Glass", description = "An ally of yours, Thaelin, is helping us counter the Iron Horde.\n\nHe claims this device can be used to spy on the enemy, even so far as hearing what they are saying at great distance.\n\nI do not trust such devices. Use it and let me know what you see.", objectives = "Look through Thaelin's Observicopter.", progress = "Take a look through Thaelin's Observicopter. I don't trust that machine.", completion = "Orgrim leads the Iron Horde in Talador... Now we know the face of our enemy." }
WordHunterWoW_QuestEN[34088] = { title = "Too Many Irons in the Fire", description = "We must slay the Iron Horde troops who infest our lands.\n\nFind those who would sully our great forest and show them the hand of justice.", objectives = "Kill 15 Iron Horde at Mor'gran Logworks.", completion = "The Iron Horde has no consideration for the wonders of the forest. In death, they will know respect." }
WordHunterWoW_QuestEN[34089] = { title = "In Short Supply", description = "The Iron Horde has explosive devices stored throughout the heart of their logging camp.\n\nWe must recover them so they are not used against us.\n\nI will keep an eye on Maraad... I worry for him in his anger.", objectives = "Collect 6 Iron Horde Explosives.", progress = "Have you found the Iron Horde Explosives yet?", completion = "I believe we can use these explosives against the Iron Horde." }
WordHunterWoW_QuestEN[34090] = { title = "Thaelin's Quick Fix", description = "Those orcs sure like to pile things up in one place. That gave me an idea...\n\nI've built this ingenious device for ya! When you get near a target, it'll let you know, and you can deploy it for a big, satisfying, kerBOOM!", objectives = "Destroy the Thunderlord Cache, Blackrock Forge, and Log Storage.", progress = "BOOM! Ahahahahaaa!", completion = "Nothing like a good explosion to warm the heart." }
WordHunterWoW_QuestEN[34091] = { title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it out of the way until you've worked out the kinks.\n\nI will send Engineer Trak to work on it in the meantime.\n\n- Orgrim Doomhammer", objectives = "Kill Engineer Trak and recover the Decommissioned Iron Shredder.", completion = "A prototype Iron Shredder, huh?! I bet we can get this thing working... they didn't have Thaelin Darkanvil to fix it!" }
WordHunterWoW_QuestEN[34092] = { title = "Desperate Measures", description = "We've identified the location of Teron'gor's compound, but his forces are already far stronger than anything we've ever faced. We need to gain an edge, and quickly.\n\nThe cursed spirits of the Ango'rosh ogres, our ancient enemies, linger in nearby ruins. Go there and gather the Ango'rosh Spellbook and the Grimoire of Binding.\n\nPerform the ritual described within at their altar to lift their curse and seek their aid.\n\nIt's a long shot, but we don't have any other options.", objectives = "Gather the Ango'rosh Spellbook and the Grimoire of Binding, then perform the ritual at the Altar of Ango'rosh in the Ango'rosh Ruins.", progress = "Were you able to acquire the aid of the Ango'rosh?", completion = "You radiate the power of the Ango'rosh!\n\n<Restalaan smiles.>\n\nIt is time to take this battle to Teron'gor's doorstep." }
WordHunterWoW_QuestEN[34093] = { title = "Getting the Points", description = "Those Thunderlords circling above us are a problem {name}.\n\nThey fly their pathetic Rylaks leisurely across the valley, thinking they are safe to rain spears down on our heads. We need to show them they are not safe from Frostwolf Vengeance!\n\nI have a plan but we will need to gather some material. Go hunt across the valley for any of their spears that survived intact. I think five should be enough.", objectives = "Gather 5 Barbed Thunderlord Spears within the Bones of Agurak.", progress = "What is it <name>? Have you got something for me?", completion = "Hrm, yes these spears look pretty good. Outstanding <name>! I know just what to use these for!" }
WordHunterWoW_QuestEN[34094] = { title = "Vol. X Pages ?", description = "That shredder had a manual jammed in the cockpit, but it's missing a lot o' pages. If we can find those manual pages, I'd bet my third toe I can get the prototype shredder working again.\n\nI coulda swore I saw a few of those pages floatin' about in  Archenon Siegeyard. Maybe the orcs there carry them.", objectives = "Find 20 Manual Pages on orcs at Archenon Siegeyard.", progress = "Have you found those pages? These manuals are ridiculous.", completion = "I wondered why the manual was so big... they write with really big letters!" }
WordHunterWoW_QuestEN[34095] = { title = "Iron Them Out", description = "The orcs themselves are not the only threat. They still have siege weapons of significant power.\n\nThey've already been used against Tuurem, and we must not allow for their continued operation.\n\nSabotage siege weapons using the explosives you collected from the logging camp.", objectives = "Destroy 6 Iron Horde Siege Engines.", completion = "They will be unable to use those weapons against us when we attack Tuurem." }
WordHunterWoW_QuestEN[34096] = { title = "An Eye for a Spy", description = "I'll get the prototype shredder working right now!\n\nTake a look through my Observicopter. You'll see what you're about to head into...", objectives = "Look through Thaelin's Observicopter.", progress = "Take a look!", completion = "That's a lot of orcs, eh? Glad I'm here tinkerin' away instead of in the thick of it." }
WordHunterWoW_QuestEN[34097] = { title = "Born to Shred", description = "I've got this prototype shredder operating on most cylinders.\n\nBoy, will they be surprised when you stomp them with their own machine!\n\nCan't wait to watch you from the safety of the Observicopter.", objectives = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", completion = "-- ENEMIES ELIMINATED --" }
WordHunterWoW_QuestEN[34098] = { title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", objectives = "Defeat Ketya Shrediron.", completion = "The screams of our enemies washed over me. The people of Tuurem are avenged." }
WordHunterWoW_QuestEN[34099] = { title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", objectives = "Repel the Iron Horde from Shattrath.", completion = "Maraad is dead... but we must carry on. I will not let his sacrifice be for nothing." }
WordHunterWoW_QuestEN[34101] = { title = "Vignette: Aruumel's Worn Mace", description = "", objectives = "" }
WordHunterWoW_QuestEN[34102] = { title = "The Mark of Defiance", description = "As you look upon the Frostwolf banner you remember struggles that have led you and the Frostwolves to this point.\n\nRuk'gan has suffered in his battles with the Thunderlord and would appreciate an extra show of defiance. \n\nAs the banner rustles in the wind you're inspired to mark the foes of the Frostwolf with its standard.", objectives = "Use the Battle-Worn Frostwolf Banner on the corpses of 6 Thunderlord Orcs in Agurak's Fall.", progress = "Anything to report, <name>?", completion = "Good work,<name>!\n\nSeeing Frostwolf banners standing proudly over our crushed foes fills me with pride!\n\nLet them forever fear the wrath of the Frostwolves!" }
WordHunterWoW_QuestEN[34103] = { title = "WANTED: Kil'uun", description = "I have a bounty set on a bird, commander. Yes, a bird.\n\nThe issue is this thing is massive, and it was last sighted a stone's throw away from the Horde base to the south in the forest. The locals call it Kil'uun.\n\nIf you'd like to track the creature down and bring back its beak I wager it would fetch a sack or two of gold for your coffers!", objectives = "Hunt Kil'uun and bring its beak to Patrick Messer.", progress = "Any luck tracking down that bird, commander?", completion = "I have no idea how you managed to track down the creature so close to the Horde base, but well done sir." }
WordHunterWoW_QuestEN[34104] = { title = "WANTED: Hilaani", description = "O'riley wants to thank our peasants for their hard work with a riverbeast dinner.\nI don't want to waste your time asking you to slaughter the things all day, commander. We've gotten reports of a huge riverbeast called Hilaani that would feed the whole fort twice over living in the lake to the south.\n\nIf you have a chance to bring cuts of her meat back, the men would be grateful.", objectives = "Kill Hilaani and bring the Pile of Riverbeast Meat to Patrick Messer.", progress = "Have you had time to kill Hilaani?", completion = "Thank you, commander! The peasants will be singing songs about your generosity tomorrow." }
WordHunterWoW_QuestEN[34105] = { title = "WANTED: Ra'tok the Hammer", description = "I've got an issue that could use your assistance, commander.\n\nA few of our men spotted an Iron Horde lieutenant wandering in the cliffs near here. We suspect she's directing their forces to strategic ground as they land on the Orunai Coast.\n\nI would feel much better about the safety of this fort if you could take her out.", objectives = "Dispatch Ra'tok the Hammer in the Orunai Coast.", completion = "All hail your glory, commander." }
WordHunterWoW_QuestEN[34106] = { title = "WANTED: Ra'tok the Hammer", description = "The Iron Horde have no honor. They disgust me.\n\nWe spotted one of their lieutenants wandering the cliffs not far from our base. I believe that she is tracking our movements to prepare for some sort of assault from the Orunai Coast.\n\nI understand you have much to do, commander. If you have the time, I believe it would be beneficial to our position's integrity.", objectives = "Kill Ra'tok the Hammer in the Orunai Coast.", completion = "I knew you'd kill her. No Iron Horde is safe from your wrath." }
WordHunterWoW_QuestEN[34107] = { title = "WANTED: Hilaani", description = "We need more meat, commander.\n\nI know what you're thinking. What about all of that meat right behind me?\n\nThat's the problem. It'll be gone in a day if we're lucky.\n\nThere's a riverbeast that lives in the lake to the south. Locals call her Hilaani. Massive, lots of meat.\n\nIf you would take down the beast and bring me her meat, your wolves will be better off for it.", objectives = "Slay Hilaani and bring a Pile of Riverbeast Meat to Beastmaster Tagh.", progress = "Good to see you, commander.", completion = "Is that what I think it is? You are too kind, commander!" }
WordHunterWoW_QuestEN[34108] = { title = "WANTED: Kil'uun", description = "It's that damned bird!\n\nEvery few hours, this blasted thing flies right past here, and none of these idiots will stop it.\n\n\"It's got the crazy in its eyes,\" they tell me. Pah!\n\nCommander, this bird will be the end of me. If you see it, could you cut off its stupid head and give it to me?\n\nIt'd make me feel better.", objectives = "Bring Kil'uun's Beak to Beastmaster Tagh.", progress = "If you decide to kill that creature, I will name my first-born in your honor.", completion = "Praise to <name>! For the Horde!" }
