WordHunterWoW_QuestEN[34122] = { title = "Ogre Diplomacy", description = "They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that.\n\nBy killing them.\n\nYou should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.", objectives = "Kill 10 Ango'rosh in the Ango'rosh Ruins.", progress = "How goes your diplomatic mission?", completion = "<Liadrin smiles.>\n\nI knew they'd see it our way." }
WordHunterWoW_QuestEN[34123] = { title = "To Thunder Pass", description = "There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass.\n\nI advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves.\n\nIt is time to show this Iron Horde what a united Frostwolf clan can do.", objectives = "Speak with Lokra at Wolf's Stand.", completion = "I am glad to see you. Our clan has faced many challenges, but the sheer size of the army coming toward us is beyond anything we have attempted to face.\n\nWe need your experience." }
WordHunterWoW_QuestEN[34124] = { title = "The Battle of Thunder Pass", description = "The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak.\n\nDurotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of.\n\nHe will need your expertise.\n\nPlease, go to him.", objectives = "Defend Frostfire Ridge from the Iron Horde.", completion = "This was a costly victory, and a very painful lesson. We chose to refuse the Iron Horde and live as we always have, but I see now they will never respect such neutrality.\n\nI am not about to wait for the Iron Horde to marshal their forces. We will fight with you, and bring the Iron Horde to its knees.\n\nCommander, the Frostwolves stand ready!" }
