WordHunterWoW_QuestEN[34144] = { title = "Retribution for the Light", description = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.\n\nYou have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", objectives = "Kill 15 demons in Gul'rok.", completion = "Already I can feel the Light triumphing over darkness. We've done it!" }
