WordHunterWoW_QuestEN[34157] = { title = "Into the Heart of Madness", description = "{name}, Nyami ran off to 'take down Teron'gor herself.'\n\nYou need to find her. She has no chance against him on her own.\n\nI must remain here and organize our ranks should another attack fall upon us. I'm counting on you.", objectives = "Speak to Soulbinder Nyami at the Seat of Depravity in Gul'rok.", completion = "You have to hurry... Teron'gor just left!" }
