WordHunterWoW_QuestEN[34163] = { title = "Hiding in the Shadows", description = "<The voice of Teron'gor enters your mind.>\n\nOur final move must remain concealed from the Auchenai, my minions. Use the shadow orbs Gul'dan provided for us to veil Gul'rok in darkness.\n\nPrepare our forces, we march on Auchindoun on my order. We will feast on the souls of the draenei and usher our demonic allies into this world!\n\n<Destroying these shadow orbs would help the defenders at Auchindoun greatly.>", objectives = "Destroy the three Shadow Orbs in Gul'rok." }
WordHunterWoW_QuestEN[34164] = { title = "Book Burning", description = "Please, {name}... I don't have much time.\n\nThe Shadow Council have allowed themselves to be turned into demons by Teron'gor and his warlocks!\n\nI have reason to believe that the shadowborne dementors are using spells given to them by Gul'dan to empower the demonic orcs. Take their spellbooks and cast them into the fire by me... it will be a pleasant sight to die to.", objectives = "Obtain 3 Shadow Council Spellbooks and burn them in the fire by Kor'thos Dawnfury in Gul'rok.", progress = "Yes?", completion = "Thank you... kill a couple more for me on your way out, if you can..." }
