WordHunterWoW_QuestEN[34192] = { title = "Things Are Not Goren Our Way", description = "The abandoned mine shaft has been overrun with goren!  They seem to be responding to commands from a big one farther down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those goren cleared out, we can get that mine up and working!", objectives = "Kill Stonetooth in the Garrison Mine.", progress = "Were you able to take out the leader?", completion = "Nice job, <name>! Let's get this mining operation started!" }
WordHunterWoW_QuestEN[34193] = { title = "Clearing the Garden", description = "This cave is the perfect climate to grow herbs for our Garrison, there is just one little problem.  All these damn nibblers!\n\nI need you to clear them out and we can get this garden growing.", objectives = "Kill 8 Frostwall Nibblers.", progress = "Did you get em?", completion = "Great work, <name>! We will get started planting the garden right away." }
WordHunterWoW_QuestEN[34194] = { title = "Looking For Help", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Head northwest and see if you can find anyone on the shoreline.", objectives = "Find a local fisherman to help our cause.", progress = "Find anyone?", completion = "Time to see what you can do." }
