WordHunterWoW_QuestEN[34209] = { title = "Vouchsafe Our Arrival", description = "A matter of great importance has arisen. While you were away, Archmage Khadgar contacted me.\n\nHe is investigating demonic influences to the north.\n\nBeing a human, the Frostwolves will not accept Khadgar without you there to vouch for him, nor will they accept a night elf such as myself.\n\nI will wait for you outside Throm'var in the Frostwind Crag.", objectives = "Meet Cordana Felsong outside of Thom'var in the Frostwind Crag.", completion = "Thank you for coming, <name>. The archmage and I are in need of your assistance." }
WordHunterWoW_QuestEN[34210] = { title = "Treasure: Gorgrond Treasure 19", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
