WordHunterWoW_QuestEN[34213] = { title = "They Have My Son", description = "Please, {name}! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde.\n\nHe has my son!\n\nHe made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process.\n\nCan you go to Gron'mar for me and rescue my son?\n\nHis name is Corki.", objectives = "Find the Key to Corki's Cage and set him free." }
WordHunterWoW_QuestEN[34214] = { title = "Treasure: Gorgrond Treasure 21", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34215] = { title = "Treasure: Gorgrond Treasure 22", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34216] = { title = "Safe Passage", description = "Being a human and a night elf, the archmage and I aren't likely to be well-received by the orcs of the Frostwolf clan.\n\nWe need you to make an introduction for us with the Throm'var farseer.\n\nThere is much to discuss. Shall I bring you up to speed on the way to the village?", objectives = "Hear Cordana Felsong's tale.", progress = "You honor us with your presence.", completion = "Wolf-brother, already word has traveled to us of your actions at Wor'gol. You have the eternal respect of the Frostwolf.\n\nNow, who are these strangers that you have brought to us and what is this urgent matter?" }
WordHunterWoW_QuestEN[34217] = { title = "Smash Blon'sky!", description = "Grulk not choose to be mutated. Grulk not monster like Blon'sky! Blon'sky evil... chose mutation for power!\n\nYou go to Grommar? Smash Blon'sky before he hurt innocents, make Grulk happy!", objectives = "Defeat Blon'sky." }
