WordHunterWoW_QuestEN[34239] = { title = "Treasure: Treasure of Tuurem", description = "", objectives = "" }
WordHunterWoW_QuestEN[34240] = { title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. As you know, there may be Shadow Council forces anywhere around Auchindoun, including near Telmor.\n\nTuulani's powers as a soulpriest have not yet fully manifested; she isn't capable of protecting the shard alone. I need you to join her at Telmor to make sure the crystal makes it to Auchindoun safely.", objectives = "Speak to Soulbinder Tuulani outside Telmor.", completion = "It's not safe here. The Shadow Council has already taken the city!" }
WordHunterWoW_QuestEN[34241] = { title = "Treasure: Gorgrond Treasure 12", description = "", objectives = "" }
WordHunterWoW_QuestEN[34242] = { title = "Scheduled Pickup", description = "You've proven yourself more than capable in battle, {name}. There may be Shadow Council forces all around Auchindoun, including near Telmor.\n\nI want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.", objectives = "Speak to Soulbinder Tuulani outside Telmor.", completion = "It's not safe here. The Shadow Council has already taken the city!" }
WordHunterWoW_QuestEN[34243] = { title = "Vignette: Rak'nar Muzzlebash", description = "", objectives = "" }
WordHunterWoW_QuestEN[34244] = { title = "They Took My Father", description = "$p! I have a lead on what happened to my father. There have been reports that he was seen in the presence of Shadow Council orcs in ____.\n\nMy father was a powerful Anchorite with a vast amount of ancient knowledge. I dread to think what those within the Shadow Council would do to him to get that knowledge. \n\nCan you go to ___? Hunt down their officers and see what they know?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect Anchorite Dolruu's three notes." }
WordHunterWoW_QuestEN[34245] = { title = "Demonic Barrier", description = "If I am reading this correctly, there might be a way to use the power of Draenor to effectively purge a demon.\n\nAccording to my father's notes, a place of snow and earth is required for the ritual. He will also need an untapped ley line to power the ritual.\n\nThere is a cave in northern Frostfire Ridge  whose power might suffice. I will mark it on your map. Head north as soon as you can and I will join you there.", objectives = "" }
WordHunterWoW_QuestEN[34246] = { title = "Break The Seals", description = "Curses! I cannot cross these wards. They specifically are designed to keep my bloodline out.\n\nHowever, I could give you a blessing so that you may pass through the outer layer of these wards. You could enter this cave and destroy the runes within that these barriers are drawing their power from.\n\nProceed with caution, for I suspect these barriers are not the only dangers we will face.", objectives = "" }
WordHunterWoW_QuestEN[34247] = { title = "To Cleanse an Eredar", description = "It... it is my mother! She is an eredar? How? When? To join the ranks of the Legion is the greatest evil our people can commit.\n\nMy father's ritual is breaking. He isn't strong enough to defeat her by himself. We need to act now!", objectives = "" }
