WordHunterWoW_QuestEN[34558] = { title = "At Your Command", description = "I'm glad you're here!\n\nFort Wrynn is nearly complete. We only need to fill this last plot.\n\nBaros provided us with blueprints for two different structures that would fit this space - an Artillery Tower or an Arcane Sanctum.\n\nIt's your call, commander. The plans are on the drafting table for your perusal.", objectives = "Choose which outpost structure to construct.", progress = "At your command.", completion = "Excellent. This will do nicely." }
WordHunterWoW_QuestEN[34559] = { title = "Vignette: Yaga the Scarred", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy $1oa Goren Egg Clusters, $2oa Iceforge Ironchewers, and Broodmother Reeg'ak.Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34560] = { title = "Armory", description = "", objectives = "" }
WordHunterWoW_QuestEN[34561] = { title = "Mage Tower", description = "", objectives = "" }
WordHunterWoW_QuestEN[34562] = { title = "Trigger Teron'gor Defense Spawns", description = "", objectives = "" }
WordHunterWoW_QuestEN[34563] = { title = "The Quarry Quandary", description = "Now that we have the artillery tower built, we're going to need some skilled hands to run it.\n\nI've heard that Ared, one of the best smiths in Shattrath, managed to escape the city's fall. He should be just outside the north wall with the rest of the refugees.\n\nSee if you can convince him to work for us.", objectives = "Speak to Apprentice Miall just outside of Fort Wrynn in Talador.", progress = "We need to find someone to run this place or we're not going to be producing much of anything.", completion = "You are the commander of this fort, yes?\n\nMy master wanted to join your fight to reclaim our home but he grew ill and... I'm sorry, he was a great draenei and I will carry on his memory.\n\nYour new building would give me the means to see out my master's vision and honor his passing.\n\nIf you would allow me to do this then I would serve you." }
WordHunterWoW_QuestEN[34564] = { title = "Destination: Unknown", description = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them.\n\nI'll hold open the portal as long as I can. It will be up to you to strike the killing blow.\n\nOur fate is in your hands, {name}.", objectives = "Destroy Mongrethod in the Remains of Xandros.", completion = "Teron'gor and Gul'dan... they slaughtered everyone...\n\n...and then they just... disappeared... into the shadows...\n\nHow did they know where to go?" }
WordHunterWoW_QuestEN[34565] = { title = "Tearing Up Talador", description = "Commander, we have a bit of a problem.\n\nWe found a location in Talador to set up an outpost but the team that was sent to begin construction have been arguing with each other on what to build. This situation could really put a setback in our plans unless it's dealt with swiftly.\n\nTake a gryphon to Talador and speak with Foreman Eksos before this gets any worse.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Commander, we have a bit of a problem.\n\nWe found a location in Talador to set up an outpost but the team that was sent to begin construction have been arguing with each other on what to build. This situation could really put a setback in our plans unless it's dealt with swiftly.\n\nTake a gryphon to Talador and speak with Foreman Eksos before this gets any worse.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34566] = { title = "At Your Command", description = "Commander, the outpost is nearly fully operational.\n\nGazlowe provided us with two different blueprints to fill this final plot - an Arsenal or an Arcane Sanctum.\n\nEither one would provide us with the additional firepower we need to stop the Iron Horde's advance.\n\nThe plans are on the drafting table. It's your call.", objectives = "Inspect the Drafting Table and choose which outpost structure to construct.", progress = "What is your will, commander?", completion = "Your will be done.\n\nFor the Horde!" }
WordHunterWoW_QuestEN[34567] = { title = "Mage Tower", description = "", objectives = "" }
WordHunterWoW_QuestEN[34568] = { title = "Armory", description = "", objectives = "" }
WordHunterWoW_QuestEN[34569] = { title = "The Quarry Quandary", description = "Now that our arsenal is built we need a skilled smith to operate it.\n\nWe recently caught an Iron Horde deserter who claims he used to be one of the Blackrock's best iron workers.\n\nNormally I'd ignore the ravings of a captive, but the weapons we took out of his pack had the finest workmanship I've ever seen.\n\nCommander, I think we should see if he's as good as he claims.", objectives = "Obtain Morketh Bladehowl's assistance.", completion = "You're the one in charge around here, right? I've heard the guards talk about your exploits and if I wasn't looking at you now I'd swear they were lying.\n\nI've only ever wanted to make the finest blades and put them in the hands of the strongest of fighters. I can tell already that you're exactly the type I want to carry my weapons.\n\nIf you can give me a chance I swear you will not be disappointed." }
WordHunterWoW_QuestEN[34570] = { title = "REUSE", description = "Teron'gor and his master Gul'dan were here! I tried to stop them... they escaped through the demonic gateway behind me before I could finish them!\n\nI think I can activate the portal open just long enough for you to enter. We have no way of knowing where it leads, but I fear it may end inside Auchindoun!\n\nYou have to stop him once and for all!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Hurkan Skullsplinter in the Seat of Depravity." }
WordHunterWoW_QuestEN[34571] = { title = "Out of Jovite", description = "Ared and I came this way because we needed a good supply of metal to build his designs and some of the best metal is the jovite that comes from the mine in Kuuro's Claim. In order to supply the artillery tower I'm going to need this metal.\n\nUnfortunately that place was recently overwhelmed by a pack of goren, so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you.", objectives = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim.", progress = "We need to get that ore before those goren eat it all.", completion = "These look pretty good. Ared would have loved to get his hands on these.\n\n<Miall wipes away a tear.>\n\n I'm sorry, this is making me too emotional, these will do just fine." }
WordHunterWoW_QuestEN[34572] = { title = "Obliterating Ogres", description = "With actual ogre mages present, the Highmaul have been increasing patrols and aggression.\n\nThinning their ranks will go a long way to deterring the Highmaul from making a comeback in Nagrand.\n\nHead up to my sister Mirana afterwards, she should have more news.", objectives = "Kill 15 ogres at Mar'gok's Overwatch.", completion = "Perfect, they will have to concentrate more on base defense now.  Hopefully things will get back to normal out there." }
WordHunterWoW_QuestEN[34573] = { title = "Iridium Recovery", description = "Ared used to always teach me that the purity of the metal is key. If the metal isn't pure it will crack under stress and be of no use to anyone.\n\nFor the artillery tower to function I'll need to make metal as pure as my master would, and for that I need a strong flux.\n\nThe dust from crushed iridium geodes would work in a pinch, but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", objectives = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim.", progress = "I'm going to need a lot of iridium dust to purify the metal to anywhere near my masters standards.", completion = "This won't be as good as some of the stuff we had back at the forge in Shattrath, but it will do." }
WordHunterWoW_QuestEN[34575] = { title = "Step Three: Prophet!", description = "You have arrived in Shadowmoon Valley. It is time to speak with the prophet.", objectives = "Speak with Prophet Velen near the crashed Iron Horde Ship in Shadowmoon Valley.", completion = "<The prophet welcomes you with a curious look, then a warm nod.>\n\nSo it begins." }
WordHunterWoW_QuestEN[34576] = { title = "Iridium Recovery", description = "My goods used to be for the very best, now the Iron Horde make copies out of poor metal and give them to everyone.\n\nI'm going to show them what a real smith can do in your arsenal, but first I'm going to need a powerful flux to make the metal as pure as it can get.\n\nThe dust from crushed iridium geodes would work in a pinch but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", objectives = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim.", progress = "I'm going to need a lot of iridium dust to purify the metal to anywhere near my standards.", completion = "This won't be as good as some of the mixes we had back in the Blackrock foundries, but it will do." }
WordHunterWoW_QuestEN[34577] = { title = "Out of Jovite", description = "Crafting good equipment requires the best metal and some of the best metal is the jovite that comes from the mine in Kuuro's Claim, just east of here. In order to supply the arsenal I'm going to need this metal.\n\nUnfortunately the place was recently overwhelmed by a pack of goren so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you, sir.", objectives = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim.", progress = "We need to get that ore before those damned goren eat it all.", completion = "Good size chunks and without a lot of the matrix material on them.\n\nThese will do just fine." }
WordHunterWoW_QuestEN[34578] = { title = "Going to the Gordunni", description = "We have a good supply of jovite now but there just isn't enough of the material in the mine to keep the artillery tower in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", objectives = "Travel to Gordal Fortress and meet up with Miall.", completion = "I crafted a few things before we left that we may need: some smoke grenades, a grappling hook, even was able to get Thaelin to throw together a rocket pack.\n\nI'm sure we'll find a use for everything." }
WordHunterWoW_QuestEN[34579] = { title = "Gas Guzzlers", description = "Sir, to make the best equipment for your arsenal I need not only the best materials, but to use the best techniques.\n\nOver the years I've developed a method to greatly strengthen my metal, but it does require an exotic resource: goren gut gas!\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for the arsenal supplies? Just kill a few goren and give their bodies a good prod with this gas extractor.", objectives = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", completion = "Thank you boss, this is just what I needed.\n\nBy the way, Goren gas is rather difficult to come by. We should probably hold off on clearing those guys out till we can stockpile enough.\n\nJust a thought." }
WordHunterWoW_QuestEN[34580] = { title = "Draenor Flowerpicker", description = "", objectives = "" }
WordHunterWoW_QuestEN[34581] = { title = "Draenor Flowerpicker Note Found", description = "", objectives = "" }
WordHunterWoW_QuestEN[34582] = { title = "Finding a Foothold", description = "So, you are the one that has led my children home? I have been waiting for you.\n\nThe Iron Horde grows stronger every day.\n\nI have foreseen a great battle, but my visions are clouded. It's as if time is sitting on top of itself. \n\nOne thing is certain, your presence here is of great importance.", objectives = "Follow Prophet Velen.", completion = "This will have to do." }
WordHunterWoW_QuestEN[34583] = { title = "For the Alliance!", description = "We wouldn't have survived Tanaan without your strength, {name}. Many draenei and Alliance alike owe you a great debt.\n\nBefore we departed for the Dark Portal, King Wrynn personally recommended that I place you in charge of our operations here in Draenor. After seeing you in action, I'm inclined to agree.\n\nThis is your garrison to found. Plant the banner and we'll begin construction immediately, commander.", objectives = "Plant the Alliance banner.", completion = "So this is Draenor? A bit darker than expected. Still, after building Stormwind, this project should be a walk in the park.\n\nWell then, are you ready to begin, commander?" }
WordHunterWoW_QuestEN[34584] = { title = "Looking for Lumber", description = "Some of the trees around here look small enough that the workers should be able to down them in no time.\n\nWe can leave the hard labor to Shelly's men, but if you'd be willing to mark the trees for them to start with, we should be able to get this operation rolling much faster.", objectives = "Mark 8 trees.", progress = "How goes the lumber hunt?", completion = "Perfect.\n\nNot only will this lumber do the job, it will look fantastic!" }
WordHunterWoW_QuestEN[34585] = { title = "Quakefist", description = "I'm getting reports of a giant in the forest.\n\nA few of the Karabor peacekeepers have followed it to a cave. In all honesty I don't think any of our troops are willing to engage the beast.\n\nMaybe you could investigate? I'm sure the peacekeepers would appreciate the help.", objectives = "Kill Quakefist.", progress = "Did you kill the giant in the cave?", completion = "The base is significantly more secure with that giant dead.\n\nYou have made quite an impression on the peacekeepers." }
WordHunterWoW_QuestEN[34586] = { title = "Establish Your Garrison", description = "I'm impressed with how quickly you have pulled this group together, commander.\n\nI think it's time we start putting up some walls and establishing a firm perimeter around our base.", objectives = "Build your garrison.", completion = "The garrison is really starting to take shape." }
WordHunterWoW_QuestEN[34587] = { title = "Build Your Barracks", description = "I must say, commander, this garrison has really come along.\n\nWe have enough materials, all we need now are the blueprints I drafted up and I can begin construction on your barracks.\n\nHmm... now where did I put those blueprints?", objectives = "Find the blueprints, learn the blueprints, and use the Architect Table to build your barracks.", progress = "The troops will sleep a lot better tonight.", completion = "How is the construction of the barracks coming along?" }
WordHunterWoW_QuestEN[34588] = { title = "The Bounty of Bladespire", description = "The sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty.\n\nI will have resources set aside as we find them. All you need do is report to your garrison and have them dispatch peons to collect these materials.You will receive:", objectives = "Speak with Gazlowe at your Garrison in Frostfire RidgeThe sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty.\n\nI will have resources set aside as we find them. All you need do is report to your garrison and have them dispatch peons to collect these materials.You will receive:" }
WordHunterWoW_QuestEN[34589] = { title = "TEST - Quest Objective Completion Effect Not Firing", description = "Testing Instructions\n\ncgo 230284\n\nLoot items until objective is complete\n\nYou should see an explosion visual", objectives = "" }
WordHunterWoW_QuestEN[34592] = { title = "A Gronnling Problem", description = "It's gonna be quite a task to build you a fortress if there's gronnlings rampaging around.\n\nI don't think anyone else here can handle taking those big beasts out, so you might need to take care of it yourself.", objectives = "Kill 8 Frostfire Gronnlings.", progress = "If you can't find gronnlings, you ain't lookin' hard enough.", completion = "Nasty beasts they got here on Draenor." }
WordHunterWoW_QuestEN[34593] = { title = "Obtaining Ogre Offensive Orders", description = "My sister, Mirana, is scouting the upper bluff while I've checked out the lower area. There are two particular ogre mages that do a lot of bossing around in the lower area.\n\nThey seem to have some orders or scrolls on them that would help us figure out what's really going on.\n\nCollect that information and meet with my sister on the long stairway up there.", objectives = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch.", progress = "Those orders would be really useful in piecing this whole thing together.", completion = "Glad you are here. I almost got killed up there at the top. Oh what are these papers? This is much worse than I imagined!" }
WordHunterWoW_QuestEN[34596] = { title = "Reglakk's Research", description = "These ogres have been using ancient Titan artifacts to empower a small cadre of specialized units called the Breakers. This Magister Reglakk is here studying ways to improve the process.\n\nLet's put a stop to whatever rituals he has going up on the bluff.", objectives = "Stop Grand Magister Reglakk.", completion = "That Felbreaker sounded tough! Good thing there's only a small number of them.\n\nNice job stopping Reglakk, but I'm sure he's safely back in Highmaul. The ogre capital will have to be dealt with sooner rather than later." }
WordHunterWoW_QuestEN[34597] = { title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.\n\nIt would be best to ruin these efforts by destroying any research found.", objectives = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch.", completion = "Excellent job thinking on your feet.  The less research these ogres do, the better!" }
WordHunterWoW_QuestEN[34598] = { title = "The Missing Caravan", description = "I've got a problem and you look like you're just the {race} for the job!\n\nA trade shipment was supposed to arrive yesterday, but it's nowhere to be found. I'm running low on merchandise here and I need somebody to go find out what happened!\n\nIf I were to guess, I'd say the saberon are probably involved. Those brutes have been a pain in our side ever since we got here!\n\nSearch for the wagon on the road near Sabermaw and hurry! Time is money!", objectives = "Find the missing trade shipment.", completion = "<Greezlex lifts his head to look up at you from the ground.>\n\n...No! Don't take me... I... wait...\n\nYou aren't a saberon... did Pyxni send you?" }
WordHunterWoW_QuestEN[34599] = { title = "Tracking Quest: Saw Yrel Leave Twilight Glade", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34600] = { title = "Tracking Quest: Saw Vorka, Rangari Leave", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34602] = { title = "Kill Goren", description = "xxxxxx", objectives = "xxxxxx" }
WordHunterWoW_QuestEN[34609] = { title = "Creating the Ink", description = "We need a way to create an artificial nexus at your tower.\n\nI know where we can get the conduit to do that, but it's well-guarded. We need to keep our cool and do this the right way.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and shamblers down below are covered with pustules full of an oily substance. We can use the oil to craft a makeshift ink substitute for the scroll.", objectives = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra.", progress = "The giants are harder to take down, but they will yield more pustules!", completion = "This isn't quite what they taught me in Dalaran, but it'll have to do!" }
WordHunterWoW_QuestEN[34612] = { title = "Forming the Scroll", description = "We'll need arcane parchment to make the scroll.\n\nThe arcane energy everywhere at this nexus froze the ancients in place and settled in their bark.\n\nIf we take pieces from the few that haven't been destroyed by the fungal creatures, I can mold them into parchment.", objectives = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", completion = "Yes, these will work great! I can freeze the pulp into a fine parchment." }
WordHunterWoW_QuestEN[34616] = { title = "Ravenous Ravens", description = "Do you see that? There is a gigantic raven just past the tree line.\n\nI'm not getting anywhere near that. In fact, I'm not sure any of the men are sufficiently equipped to deal with a threat like that. \n\nDo you want to handle this one yourself, commander?\n\nOnce those ravens are gone we can start sending more troops into the woods. So we will be killing two birds with one stone... or should I say kill five birds with...\n\n<Confused by his own analogy, Baros scratches his head.>\n\nYou get the point.", objectives = "Kill 6 Lunarfall Ravens.", progress = "Did you kill those ravens?", completion = "This place is just full of surprises... terrifying surprises." }
WordHunterWoW_QuestEN[34617] = { title = "QA Test Quest 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[34619] = { title = "Gathering the Spark", description = "We need arcane energy to complete our scroll. It needs that to coalesce the scroll together.\n\nI have an artifact that can capture energy vortexes in the caldera below, so let's get moving.", objectives = "Harvest 3 Arcane Vortexes in Zangarra.", progress = "This is why I love magic. It's so... refreshing.", completion = "Perfect! We should have plenty of energy now." }
WordHunterWoW_QuestEN[34622] = { title = "Tracking Quest: Saw Ner'zhul Leave", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34624] = { title = "Gas Guzzlers", description = "To complete my master's designs and to stock up the artillery tower we need to use an exotic resource, namely goren gut gas.\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for me? The stuff is concentrated, so only a few are needed. Just kill one and give its body a good prod with this gas extractor.", objectives = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", completion = "Thank you, this is just what I needed.\n\nGoren gas is rather difficult to come by but thankfully we can make this supply go a long way." }
WordHunterWoW_QuestEN[34631] = { title = "An Audience With The Archmage", description = "I'm pleased to report that your Arcane Sanctum is up and running, commander!\n\nEverything is exactly as the blueprint says... except for this note Baros scrawled on the bottom. \"Don't forget to connect the sanctum to the ley line network!\"\n\nCommander, I'm a foreman, not a mage. I... have absolutely no idea how to do that.\n\nWe've found Archmage Khadgar and some other Kirin Tor not far from here. To the east, near the mountains. Perhaps we should ask them for a hand?", objectives = "Speak to Archmage Khadgar in Talador.", completion = "Ah, so you've built an Arcane Sanctum! Splendid!\n\nTroubles connecting to the ley line network, I take it?" }
WordHunterWoW_QuestEN[34632] = { title = "An Audience With The Archmage", description = "Your Arcane Sanctum is coming along nicely, commander.\n\nEverything's built to spec... except for one detail Gazlowe scrawled in at the bottom of the blueprint. \"Don't forget to connect the sanctum to the ley line network!\"\n\nI, uh... I have no idea how to do that.\n\nI'm sorry commander, but magic just isn't my thing. We did spot Archmage Khadgar and some Kirin Tor not far from here. To the east, up near the mountains.\n\nMaybe we should ask them for help?", objectives = "Speak to Archmage Khadgar in Talador.", completion = "Ah, so you've built an Arcane Sanctum! Splendid!\n\nTroubles connecting to the ley line network, I take it?" }
WordHunterWoW_QuestEN[34633] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[34634] = { title = "Creating the Ink", description = "We're going to need a way to create an artificial nexus at your tower.\n\nI know where we can get what we need, but it's heavily protected. We don't have the firepower to just waltz in the front door.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and spore creatures down below are covered in pustules filled with an oily substance. If we gather enough of the oil I can craft a makeshift ink substitute for the scroll.", objectives = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra.", progress = "The giants have many more pustules than the sporebats, but are much tougher.", completion = "These pustules are sizzling with energy. They'll do nicely." }
WordHunterWoW_QuestEN[34635] = { title = "Forming the Scroll", description = "For this plan to work, we'll need infused parchment.\n\nThe latent arcane energy at this nexus quickly froze the ancients in place and settled in their bark.\n\nIf we rip off strips from the few that haven't been destroyed by the fungal creatures, I can form them into parchment.", objectives = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", completion = "Such clean breaks on each piece! Fantastic." }
WordHunterWoW_QuestEN[34636] = { title = "Gathering the Spark", description = "We need to get our hands on arcane energy to complete our scroll. It needs that fiery kick.\n\nI have a device capable of capturing energy in the space below, so let's get moving. The infused creatures shouldn't be an issue for the two of us.", objectives = "Harvest 3 Arcane Vortexes in Zangarra.", progress = "There's so much untapped power... think of the potential!", completion = "Excellent. This ought to be just what we need." }
WordHunterWoW_QuestEN[34637] = { title = "Open the Portal", description = "xxxxxxYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "xxxxxxxxxxxYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34639] = { title = "Aruuna's Desolation", description = "", objectives = "" }
WordHunterWoW_QuestEN[34641] = { title = "Vignette/Treasure: Waterlogged Journal", description = "", objectives = "" }
WordHunterWoW_QuestEN[34642] = { title = "Vignette/Treasure: Lucky Coin", description = "", objectives = "" }
WordHunterWoW_QuestEN[34645] = { title = "Vignette: Warmaster Blugthol", description = "", objectives = "" }
WordHunterWoW_QuestEN[34646] = { title = "Qiana Moonshadow", description = "If we are to win this war we are going to need more than foot soldiers. We need champions.\n\nQiana Moonshadow's performance in Tanaan and Eventide Landing was quite impressive.\n\nPerhaps you should speak with her about taking on a greater role in the battle against the Iron Horde.", objectives = "Speak with Qiana Moonshadow.", completion = "Luuka is a little shaken up, but he is safe, and that's all that really matters.\n\nLook... commander, I owe you my life. All of us do honestly.\n\nI would be honored to serve as your agent here in Draenor. If you have need of me, you need only say the word." }
WordHunterWoW_QuestEN[34647] = { title = "Vignette/Treasure: Snow-Covered Strongbox", description = "", objectives = "" }
WordHunterWoW_QuestEN[34648] = { title = "Vignette/Treasure: Gnawed Bone", description = "", objectives = "" }
WordHunterWoW_QuestEN[34649] = { title = "Vignette/Treasure: Smoldering True Iron Deposit", description = "", objectives = "" }
WordHunterWoW_QuestEN[34650] = { title = "Thunderlord Invasion", description = "Our shadow hunters spotted some of dem Thunderlord gettin' ready to attack us, commanda!\n\nWe should be gettin' ready for an invasion!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "[PH] Defend Against the Thunderlord Invasion (TEMP: Talk to Rokhan)Our shadow hunters spotted some of dem Thunderlord gettin' ready to attack us, commanda!\n\nWe should be gettin' ready for an invasion!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34651] = { title = "Tracking Flag: Dagg Found at Grom'gar", description = "", objectives = "" }
WordHunterWoW_QuestEN[34652] = { title = "Vignette/Treasure: Savage Clam", description = "", objectives = "" }
WordHunterWoW_QuestEN[34653] = { title = "Arakkoa Exodus", description = "I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.", objectives = "Speak with Azik in Spires of Arak.", completion = "<The arakkoa merchant looks you up and down.>\n\nWell-equipped, aren't we? Azik is betting you are someone of importance to your people.\n\nCome closer, friend. Speak with me for just a moment." }
WordHunterWoW_QuestEN[34654] = { title = "Tracking Flag: Dagg Found at Daggermaw Ravine", description = "", objectives = "" }
WordHunterWoW_QuestEN[34655] = { title = "The Shadows of Skettis", description = "My people flee our homeland in droves. I sell trinkets to ease the journey.\n\nBut I see that you are not interested in trinkets... No, what you seek are answers.\n\nSkettis lies just ahead. Once a great city built by Terokk as a refuge for the unwanted. Now a ruined slum.\n\nAn old storyteller lives there - a scrollkeeper named Reshad. Find him and speak these words: \"Shadows gather.\" He will know you are a friend.\n\nNow go. Your presence is bad for business.", objectives = "Speak the password to Reshad in Skettis.", progress = "If you're here for some kind of legendary tome of unthinkable power, I'm sorry to disappoint you. I am merely a keeper of history.\n\nI am also very busy at the moment.", completion = "Azik must have seen something in you. I will trust his judgment, for n-\n\n<Reshad is interrupted as a warm gust of wind surges through the hut.>\n\nOh dear... they've arrived." }
WordHunterWoW_QuestEN[34656] = { title = "Hidden in Plain Sight", description = "<Reshad begins hastily stuffing scrolls into his robes.>\n\nI thought I would have more time to prepare! There are powerful relics hidden out there in Skettis - if I leave without them, I may as well have died.\n\nThe first is a pair of wingblades being held by an effigy near the front gate. You likely walked right past them on your way in.\n\nAnother effigy on the east side of the ruins bears a white mask over its face.\n\nBring those relics to me, and their secrets shall be yours.", objectives = "Retrieve the Weathered Wingblades and Ragged Mask.", progress = "Wingblades forged in the name of a sun god to bring freedom and glory to her children.\n\nA mask worn by a great king who would walk among his people in disguise to know their true nature.", completion = "Who would expect to find these treasures draped over straw dolls, left to bake in the sun? Sometimes the best place to hide precious things is in plain sight." }
WordHunterWoW_QuestEN[34657] = { title = "Adherents of the Sun God", description = "The arakkoa from Skyreach are all ruled by the Adherents of Rukhmar. They revile those of us who bear the Curse of Sethe, and decree that we must be purged in the name of their sun god.\n\nSoon their gaze will turn to lands beyond Arak.\n\nChallenge their warriors. Buy me time to prepare my escape, and help me set into motion their downfall.", objectives = "Slay 8 Adherent Bladewings.", progress = "Skettis will fall today. Neither of us can change that.\n\nWe need only to send them a message: we will not die quietly.", completion = "Azik was right to guide you to me. If you were coming to help Skettis, we needed to meet.\n\nAnd if you were coming to attack us, well, I'd be dead either way, wouldn't I?\n\n<Reshad lets out a cawing laugh and stuffs another scroll into his robes.>\n\nThere, that's nearly everything." }
WordHunterWoW_QuestEN[34658] = { title = "Orders From On High", description = "The Adherents of Rukhmar are the ruling body atop the spires. Their influence is absolute. Their proclamations taken as the will of Rukhmar Herself.\n\nThe herald leading this purge is surely carrying out such orders - likely no more than a list of names and places they plan to erase.\n\nThat list would prove invaluable in the days to come. Acquire it for me, and shut that herald up!", objectives = "Loot the Adherent Proclamation from Sun-Sage Rathyx.", progress = "<Reshad fastens another scroll to Percy, who squawks meekly in protest.>\n\nOh, stop whining.", completion = "Ah yes, there's my name at the top of the list. And a few Talonpriests from the Shadowglade as well.\n\nThey fear the return of Terokk, as they should." }
WordHunterWoW_QuestEN[34659] = { title = "The Crone", description = "Do you remember our greeting, {name}?\n\n\"Shadows gather when the raven swallows the day.\"\n\nIt is more than an old verse - it is a call to action. Followers of the old ways are gathering, and I must join them. You are needed, too, I should think\n\nFollow this road down to Crow's Crook. There you will find the home of an old crone. Greet her as you greeted me, and she will guide the way.\n\nYou will not see me, but I will be close behind.", objectives = "Speak the password to Ornekka at Crow's Crook.", progress = "You would be wise to turn back, traveler.", completion = "I will point you in the right direction, but I cannot guarantee you'll survive the trip.\n\nKah-hah haha!" }
WordHunterWoW_QuestEN[34660] = { title = "Zorkra's Fall", description = "", objectives = "" }
WordHunterWoW_QuestEN[34661] = { title = "The Drudgeboat", description = "[TEMP]<The torn scroll outlines the schedule of several upcoming Frostwolf prisoner arrivals.>\n\n<It appears that they are being shipped in by boat. This could be your method of escape. Khadgar will want to see this.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Drudgeboat Schedule to Khadgar." }
WordHunterWoW_QuestEN[34662] = { title = "Ring of Trials: Crushmaul", description = "So you want to fight in the Ring of Trials do you? It's your funeral, bub!\n\nYour first fight is against an exceptionally large and angry ogre named Crushmaul. That's not all though, you'll have to take out his armored boar companion too; Crushmaul never goes into the ring without him!\n\nI hope your affairs are in order, because the last gladiator that fought Crushmaul went home in a body bag...\n\nI'm counting on you! Get your ass inside the arena and speak with my associate Guzrug to start the fight!", objectives = "Defeat Crushmaul in the Ring of Trials.", progress = "What are you waiting for? Get in the ring and start spilling blood!", completion = "Whoa! I couldn't tell if that was Porkchop squealing in there or if you had Crushmaul crying like a little baby!\n\nYou've got talent, kid!\n\nHere's your cut of the profit, but why stop there? Together we can make a mountain of gold!" }
WordHunterWoW_QuestEN[34663] = { title = "Ring of Trials: Raketalon", description = "You may have defeated Crushmaul, but the party's over now...you've got another fight!\n\nThe Highmaul take gladiatin' seriously; so when they built the Ring of Trials, they searched far and wide for the most brutal creatures they could find!\n\nYou're up against a dread raven the ogres are calling Raketalon! I'm telling you, {name}, something about that bird just ain't right...I think it truly enjoys the act of killing!\n\nRaketalon toyed with the last gladiator for hours before eating him.\n\nTry not to die!", objectives = "Defeat Raketalon in the Ring of Trials.", progress = "What are you waiting for? Get in the arena and start spilling blood!", completion = "You did it, <name>! Raketalon has actually been defeated!\n\nI'd never have believed it if I hadn't seen it with my very own two eyes. You've got a fire in your belly and dollar signs in your eyes, kid!\n\nHere's your cut of the profit, but don't stop now! You're on a roll!" }
WordHunterWoW_QuestEN[34664] = { title = "Ring of Trials: Hol'yelaa", description = "You won your first two fights, but it's only going to get tougher from here!\n\nYour next fight is against Hol'yelaa, a former rangari who is as crazy as they come.\n\nNo, really... Hol'yelaa is bonkers!\n\nYears ago, while on a scouting mission, he single handedly saved his entire rangari unit from a pack of Garn. But something inside of him snapped....\n\nIt wasn't long before Hol'yelaa went completely marbles and turned on his own unit!\n\nAlright, the pep talk is over! Get in there and kick some ass!", objectives = "Defeat Hol'yelaa in the Ring of Trials.", progress = "What are you doing standing around? Get in the arena and spill some blood!", completion = "Watching you fight in the arena is like witnessing an artist create a masterpiece!\n\nWell, a masterpiece of blood and shattered bones... but hey, everyone's got to be good at something right?\n\nHere's your cut of the profit! That fight was so good I actually thought about giving you a bonus!" }
WordHunterWoW_QuestEN[34665] = { title = "Ring of Trials: Captain Boomspark", description = "You've been making a name for yourself in the arena, {name}!\n\nDon't get too excited though...fame has its consequences! You've been challenged by an up-and-coming gladiator who is looking to make a name for himself, sound familiar?\n\nYour next fight is against Captain Boomspark, a mercenary who came here to fight for the Iron Horde.\n\nThe Iron Horde ain't exactly throwing piles of gold around, so now he's here!\n\nHe's got a shredder, so watch out for the blades... and the fire too... especially the fire!", objectives = "Defeat Captain Boomspark in the Ring of Trials.", progress = "What are you doing standing around? Get in the arena and spill some blood!", completion = "I ain't ever seen anybody dismantle a shredder quite like that before!\n\nYou've made me a lot of money, <name>! Only the best gladiators survive this long in the arena; and yet, even with that in mind, there's still something different about you...\n\nIt's your eyes...they look as if they've stared death in the face a thousand times and never even blinked.\n\nTake your cut of the profit and rest up, the biggest fight is still ahead!" }
WordHunterWoW_QuestEN[34666] = { title = "Ring of Trials: Roakk the Zealot", description = "The final match is at hand, {name}! You've decimated all of the best challengers! There's nowhere to go from here but the very top...the reigning champion of the Ring of Trials!\n\nThe current champ is an arakkoa named Roakk the Zealot. Roakk is a lunatic! He says he's on some divine crusade for the sun or something.\n\nCrazy or not, he's one of the most dangerous fighters I've ever seen and has even fought in the Highmaul Coliseum!\n\nI'm not going to lie, you're probably going to die in there...good luck!", objectives = "Defeat Roakk in the Ring of Trials.", progress = "What are you doing standing around? Don't you hear the crowd screaming?\n\nThere's a championship waiting on you!", completion = "Long live the champ! I knew you could do it!\n\nCould you hear the roar of the crowd in there? It shook the arena like thunder!\n\nThis is only the beginning! The Highmaul Coliseum awaits, and as the champion of the Ring of Trials you'll be expected to make an appearance!" }
WordHunterWoW_QuestEN[34667] = { title = "Court of Souls", description = "", objectives = "" }
WordHunterWoW_QuestEN[34668] = { title = "Vignette: Talonpriest Zorkra", description = "", objectives = "" }
WordHunterWoW_QuestEN[34669] = { title = "Gather Lumber", description = "xxxxxx", objectives = "xxxxxxxxxxxx" }
WordHunterWoW_QuestEN[34670] = { title = "Professional Processing", description = "Hey boss! We got ourselves quite a lot of raw materials ripe for some professional processing... if you know what I mean. Time to get us a building that can help put those materials to good, weaponizing use.\n\nI got a few extra plans we might be able to use to get you started, but you gotta' pick which one to make. Once you choose, talk to Rezlak and get construction started on it.", objectives = "Learn a Profession Building Blueprint from Gazlowe and then have Rezlak begin construction of the building." }
WordHunterWoW_QuestEN[34671] = { title = "Vignette: Shirzir", description = "", objectives = "" }
WordHunterWoW_QuestEN[34672] = { title = "The Rise of Aku'mai", description = "We barely escaped the Twilight's Hammer sacrificial altar, but there are others who need help deeper within these caves. If these cultists complete their blood ritual, they will unleash Aku'mai the Devourer onto the world. You cannot let this happen.", objectives = "Kill Aku'mai the Devourer", progress = "Hurry, <name>! Aku'mai must be stopped before he devours our world!", completion = "That was incredible, <name>! The Old Gods will think twice before trying to crawl out of their pit again." }
WordHunterWoW_QuestEN[34673] = { title = "The Rise of Aku'mai", description = "We barely escaped de Twilight's Hammer sacrificial altar, but others be needin' help deeper in. If de blood ritual be complete, they be unleashin' Aku'mai da Devourer. Don let this be happenin', mon.", objectives = "Kill Aku'mai the Devourer", progress = "Move, <name>! Aku'mai be wantin' to devour de world!", completion = "Dat was amazin', <name>! De Old Gods be thinkin' twice before tryin' to take anudder bite outta you, mon." }
WordHunterWoW_QuestEN[34674] = { title = "Taking the Fight to Nagrand", description = "**Eyes Only -- Commander {name}**\n\nWith the fall of the rangari base at Telaar, Vindicator Yrel, recommended we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that a new outpost is nearly complete. He has indicated that they are ready to receive you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, sir.\n\n-- Bodrick Grey, SI:7", objectives = "Speak with Lieutenant Balfor at the caravan in Nagrand.", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>" }
WordHunterWoW_QuestEN[34675] = { title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded... west.\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", objectives = "Speak with Rangari D'kaan at Telaari Station.", completion = "Commander <name>. It's good to see you. We have much to discuss.\n\nThe situation in Nagrand is rapidly deteriorating. We've lost Telaar.\n\nTo make matters worse, Grommash has named Garrosh Hellscream the new warlord of the Warsong clan." }
WordHunterWoW_QuestEN[34676] = { title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", objectives = "Speak to Dungar Longdrink to secure a flight to Talador.", completion = "I won't waste any of your time, sir. Let us discuss strategy." }
WordHunterWoW_QuestEN[34677] = { title = "NOT USED", description = "", objectives = "" }
WordHunterWoW_QuestEN[34678] = { title = "Up and Running", description = "The Warsong struck us hard. We lost Telaar, but we have a rare opportunity to strike at the heart of the Warsong.\n\nWe need your wisdom and leadership to pull it off, {name}.\n\nFirst though, we're going to get our survivors out of Telaar. My rangari are ready to strike. We just need to get you to them.\n\nThaelin has a copter that can get you to them. Unfortunately, his hands are full just trying to keep the infernal thing running.\n\nHelp him get it up and running?", objectives = "Collect the Assorted Engineering Parts, Prop Rotor, and Transmission Flywheel.", progress = "<name>, I can't tell you how great it is to see you.", completion = "For me? Really you shouldn't have.\n\nOkay, this should do it.\n\nI hope." }
WordHunterWoW_QuestEN[34679] = { title = "Alliance Stables Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[34680] = { title = "Alliance Workshop Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[34681] = { title = "It's a Matter of Strategy", description = "Da Iron Horde have proved themselves worthy foes.\n\nThey managed to get their fleet movin' to Talador from Gorgrond without my spies seein' a thing. Talador be a crossroads for the whole continent. We can't let them have it.\n\nDon't worry boss, we got a plan. Foreman Grobash be settin' up an outpost for our forces as we speak. They be ready for you when you arrive, commander.", objectives = "Speak to Bron Skyhorn to secure a flight to Talador.", completion = "Your will be done. I require your advisement, commander." }
WordHunterWoW_QuestEN[34682] = { title = "Operation: Surprise Party", description = "There weren't many survivors of the Warsong attack. The few remaining rangari have gone up to one of the bluffs overlooking Telaar.\n\nThe rangari are waiting for you. They're planning a surprise counter-attack.\n\nMy copter's taken a beating. The auto-pilot's set to take you up there. I think she's got one last trip in her.\n\nMaybe.", objectives = "Use Thaelin's Copter to get up to the Rangari Overlook.", completion = "We've been expecting you, commander.\n\nThe situation is grim, but doable with your help." }
WordHunterWoW_QuestEN[34683] = { title = "One Step Ahead", description = "Boss, Durotan set off with Draka and Gazlowe to track da Iron Horde's movements along da coast.\n\nDey waitin' for ya on the cliffs to da northwest.", objectives = "Speak to Durotan in Talador.", completion = "Ah, <name>. I recognized your scent, friend. We have been waiting for your arrival to begin our task." }
WordHunterWoW_QuestEN[34684] = { title = "One Step Ahead", description = "Commander, Vindicator Maraad took Yrel and Thaelin Darkanvil just up to the road from here to track the Iron Horde's forces in the forest.\n\nThey are already at work formulating a strategy to stop their operations. They await your arrival on the cliffs to the northwest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Vindicator Maraad in Talador.Commander, Vindicator Maraad took Yrel and Thaelin Darkanvil just up to the road from here to track the Iron Horde's forces in the forest.\n\nThey are already at work formulating a strategy to stop their operations. They await your arrival on the cliffs to the northwest.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34685] = { title = "As the Smoke Rises", description = "Aruuna burns.\n\nThe arakkoa swooped down from their spires and are turning everything to ash. Draenei, talbuk, even orc; they care not for allegiances. They merely want to watch the world burn.\n\nI barely escaped with my life, but my best friend, Barum, stayed behind to find his daughter. The others all say you are a great champion. Please, I beg of you, go to Aruuna and find them.", objectives = "Find Crystal-Shaper Barum near Aruuna in Talador.", completion = "Kalaam sent you? By the Light, I knew I could count on him!" }
WordHunterWoW_QuestEN[34688] = { title = "DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[34690] = { title = "Just the Beginning", description = "It... is over.\n\nWe should return to your outpost and discuss our next course of action. There are innocent people in danger across all of Talador that need our help.\n\nI will have Khadgar open a portal for us. Let us save our words for now.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Yrel in Talador.It... is over.\n\nWe should return to your outpost and discuss our next course of action. There are innocent people in danger across all of Talador that need our help.\n\nI will have Khadgar open a portal for us. Let us save our words for now.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34691] = { title = "Just the Beginning", description = "I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right.\n\nWe should return to your outpost and discuss our next course of action. There is nothing left for us here.\n\nI will ask the human to open a portal for us. We shall speak again there.", objectives = "Speak to Durotan in Talador.I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right.\n\nWe should return to your outpost and discuss our next course of action. There is nothing left for us here.\n\nI will ask the human to open a portal for us. We shall speak again there.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34692] = { title = "Delegating on Draenor", description = "There is more work to do on Draenor than we can possibly handle by ourselves. We need to start delegating.\n\nA group of night elves need a champion at Starfall Outpost.\n\nQiana is a perfect fit for this mission.", objectives = "Use the Command Table to send Qiana Moonshadow on a mission.", progress = "You can use the Command Table to assign missions to your followers.", completion = "This is a good start, but we will need more champions to deal with the trials that lay ahead." }
WordHunterWoW_QuestEN[34696] = { title = "The Lady of Light", description = "{name}, yes? You are the one in charge here? I am Knight-Lord Dranarus, at your service.\n\nLady Liadrin has responded to a suspected demon presence near Auchindoun, southwest of here. She has asked specifically for your assistance in ensuring Auchindoun does not fall into Gul'dan's hands.\n\nIf you could set forth at your nearest convenience, I am sure the Lady would be most grateful.", objectives = "Speak to Lady Liadrin at the Burning Front in Talador.", completion = "We'll have to catch up later. We have bigger problems!" }
WordHunterWoW_QuestEN[34697] = { title = "A Rediscovered Legend", description = "If your troops are going to learn to fight people you better get people to fight! And they better be good.\n\nEver hear of Kash'drakor?\n\nHe's a big famous Frostwolf orc warrior type that tried to kill us Skulls. He would have won too, if the ogres hadn't snatched him.\n\nTo the north is the Stonemaul Arena where they took him and a bunch of other big bad mean fighter gladiators.\n\nIf you can find a way to free them, they could be the best trainers you could hope for.", objectives = "Find Kash'drakor near the Stonemaul Arena in Gorgrond.", completion = "The Laughing Skull sent you? If they were any other clan I would find that ironic.\n\nI am Kash'drakor, hero of the Frostwolf clan, and champion of the slave pits of Stonemaul.\n\nAnd yet, despite all these titles, I need your help." }
WordHunterWoW_QuestEN[34698] = { title = "Slave Hunters", description = "Anytime a gladiator escapes Stonemaul, they send their hardened slave hunters after us.\n\nI consider myself a capable warrior, years of surviving in an arena have taught me that.\n\nBut these slave hunters keep pendants magically tethered to the slaves. With these pendants they can track us down anywhere we go, and kill us in our sleep or when our guard is down.\n\nI have no right to ask this, but can you enter Stonemaul and retrieve these pendants?", objectives = "Collect the Pendants of Brol, Krag, and Mol.", progress = "Have you the pendants?", completion = "You have shown more honor in this one act than I have seen in many years.\n\nWhen this is over, I will swear my axe to your forces and pass my knowledge on to your troops." }
WordHunterWoW_QuestEN[34699] = { title = "Getting Gladiators", description = "When we fled Stonemaul, we had to leave others behind.\n\nIf we try to rescue them and are recognized, the ogres will know our purpose, and the first thing they will do is kill our friends.\n\nThe ogres do not know you, which might give you a fighting chance.\n\nEnter Stonemaul, find the other gladiators, and release them from their bonds. Do this and you will have our loyalty.", objectives = "Rescue gladiators Bruto, Y'kish, and Pitfighter Vaandaam.", completion = "Thank you, strange one. Now we are free to split that chieftain Kor'gall wide open!" }
WordHunterWoW_QuestEN[34700] = { title = "Nazgrel", description = "Escaping Stonemaul was the easy part. The ogre filth that rule the pits still have my son.\n\nFor a while they used him as leverage to ensure I would fight in their arenas. But now that I have escaped they will try to train him to replace me.\n\nPlease, rescue my son. If they see me they will kill him instantly.", objectives = "Rescue Nazgrel.", completion = "This deed will never be forgotten as long as I or my son live. You have my gratitude, hero, and my loyalty." }
WordHunterWoW_QuestEN[34701] = { title = "Speaker for the Dead", description = "Oh, praise the Light, you're here! Exarch Maladaar asked for me to find you.\n\nWe need your help. Auchindoun is under attack by demons!\n\nGo to the Burning Front to the southwest as soon as possible! You're one of the few people he trusts to help lead the defense.", objectives = "Speak to Exarch Maladaar at the Burning Front in Talador.", completion = "I will not allow a single demon to step foot inside Auchindoun. You will help me ensure that does not happen." }
WordHunterWoW_QuestEN[34702] = { title = "Krav'ogra", description = "Stonemaul has chieftain, and it has slavemaster. Today, we kill both.\n\nFirst, Slavemaster Ok'mok. Me fight in arenas since me your size. Me know cruelty. Slavemaster Ok'mok is cruelty.\n\nWant to be true gladiator? Go to Stonemaul Arena, bang challenge gong in center of arena, and face beasts of slavemaster.\n\nMaybe you make Ok'mok so mad he jump down himself to kill you. If he do, kill him instead.", objectives = "Slay Slavemaster Ok'mok by using the Challenge Gong in Stonemaul Arena.", completion = "Me watch you from afar. Me like your fighting skills, show much promise." }
WordHunterWoW_QuestEN[34703] = { title = "The Axe of Kor'gall", description = "Time for vengeance! We are going to kill Kor'gall and you are going to take his axe.\n\nShatter this feeble barrier, follow the bridge beyond until you reach the chieftain's throne.\n\nYou freed us, so the honor of first blood is yours. Strike the first blow and we will join you in the cutting.", objectives = "Kill Kor'gall and retrieve his axe, Serathil.", progress = "Kor'gall has ruled uncontested for far too long.", completion = "This blade has caused enough pain and suffering for one lifetime. We shall see to it that it is properly disposed of." }
WordHunterWoW_QuestEN[34704] = { title = "A Rediscovered Legend", description = "This Sparring Arena is a good start, but we will need trainers to help mold your forces into worthy fighters.\n\nThere has been a reported spotting of a draenei to the west who matches the description of Akaani.\n\nThis is interesting, as we all believed her dead. She was one of the finest warriors the draenei have ever fielded and a master of nearly any weapon forged or found.\n\nCommander, you could not ask for a more skilled trainer. I advise seeking her out, if it is really her...", objectives = "Find Gladiator Akaani near Stonemaul Arena in Gorgrond.", completion = "You do not have the look of a Stonemaul bounty hunter.\n\nWe escaped the clutches of their vile arena but at a heavy cost. We were forced to leave too many allies behind and too many ogres breathing.\n\nWe could use a fresh face, one that is unknown to the ogres." }
WordHunterWoW_QuestEN[34705] = { title = "Tracking Quest - Shadowmoon Intro", description = "", objectives = "" }
WordHunterWoW_QuestEN[34706] = { title = "Come Together", description = "Your work is done here, {name}. I will stay here for now and help clean up any remaining demons.\n\nYou should return to your outpost and let Dranarus know of our success. He can relay that information to Azeroth.", objectives = "Speak to Knight-Lord Dranarus at Vol'jin's Pride.", completion = "Lady Liadrin was indeed wise in choosing you. I will let Vol'jin know of your victory immediately." }
WordHunterWoW_QuestEN[34707] = { title = "Come Together", description = "Gul'dan and his cronies would do well to remember this day. We Auchenai are not to be trifled with.\n\nYou should inform Vindicator Icia in your outpost of our success. She can reach out to the scattered refugees and their families.", objectives = "Speak to Vindicator Icia at Fort Wrynn.", completion = "I will gather any remaining survivors so we can rebuild what we have lost.\n\nThank you." }
WordHunterWoW_QuestEN[34708] = { title = "Vignette: Jehil the Climber", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy $1oa Goren Egg Clusters, $2oa Iceforge Ironchewers, and Broodmother Reeg'ak.Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34709] = { title = "Every Bit Counts", description = "The Jorune Mine, west of here, needs your help!\n\nMy good friend Ageilaa sent me to look for help. Exarch Maladaar sent over what vindicators he could spare, but it isn't enough!\n\nWill you go to the mine and help us? We need the crystals from the mine to create more defenses like the crystals you see on the Burning Front.", objectives = "Speak to Ageilaa at the Jorune Mine in Talador.", completion = "Aeun sent you? Help has arrived!" }
WordHunterWoW_QuestEN[34710] = { title = "Every Bit Counts", description = "Manduil Skycaller was sent on a sensitive mission to Jorune Mine, but he hasn't returned for hours.\n\nI suspect he requires assistance. I will let him brief you on the situation when you find him, but he is likely deep within the mine.\n\nYou should report to Ageilaa, a local draenei miner who has agreed to cooperate with us in exchange for helping her regain control of the mine.", objectives = "Speak to Ageilaa at the Jorune Mine in Talador.", completion = "Aeun sent you? Help has arrived!" }
WordHunterWoW_QuestEN[34711] = { title = "Due Cause to Celebrate", description = "Shall we return to your outpost? It would be a much better - and safer - place to celebrate.\n\nI'll teleport us there.", objectives = "Speak to Magister Serena at Fort Wrynn.", completion = "We can finally connect your tower to the ley line network with this crystal.\n\nI also edited your blueprint so you can actually read the thing. Should make building another one much easier." }
WordHunterWoW_QuestEN[34712] = { title = "Due Cause to Celebrate", description = "This isn't exactly my idea of the best place to talk.\n\nShall we return to your outpost? It will be a much better place to celebrate.\n\nI'll teleport us there.", objectives = "Speak to Magister Krelas at Vol'jin's Pride.", completion = "With this crystal, we can connect your tower to the ley line network at last!\n\nI also made some modifications to your blueprint that should make it much easier to build another tower in your garrison." }
WordHunterWoW_QuestEN[34713] = { title = "Treasure: Gronnstalker's Cache", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34714] = { title = "Frostfire Ridge: (RRP) - Treasure - Pale Leather Cache", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34715] = { title = "Tracking Flag: Shamanstone Summons", description = "", objectives = "" }
WordHunterWoW_QuestEN[34716] = { title = "Mo'mor Might Know", description = "We know the Warsong packleader that attacked the caravan is in Telaar. She has the blueprints.\n\nWe don't know where she is down there, but there's one who might.\n\nVindicator Mo'mor was last seen alive, but taken prisoner. If he's still alive, he might know where the blueprints are.", objectives = "Find Vindicator Mo'mor in Telaar.", completion = "Please forgive me. I'm in no condition to stand, commander." }
WordHunterWoW_QuestEN[34717] = { title = "Operation: Just Arrowhead", description = "It goes without saying that we'll help you kill any of the Warsong out in the open down there.\n\nYou just start the fight, and we'll end it with extreme prejudice.", objectives = "Kill 15 Warsong forces at Telaar.", completion = "That bit of justice is sure to have lifted the spirits of my rangari.\n\nLosing Telaar and many of our friends has taken a heavy toll.\n\nThank you, commander." }
WordHunterWoW_QuestEN[34718] = { title = "The Others", description = "There are yet a few survivors. I saw them pile onto Arbiter Khan during the fighting.\n\nMore importantly, I can hear little Isel's sobs. She's nearby. I hope her mother is still alive.\n\nYour dwarf friend, Hansel, came in to try to rescue us. He thought he could take the Warsong on his own. I'm afraid I don't know what happened to him.", objectives = "Rescue Arbiter Khan, Caregiver Felaani & Isel, and Hansel Heavyhands.", completion = "Khan! No!... he just received his promotion. His whole life ahead of him and now, nothing.\n\nThank you for getting the others out. Light be... nevermind." }
WordHunterWoW_QuestEN[34719] = { title = "... and My Hammer", description = "When they captured me, the Warsong took my hammer. Will you help me to recover it?\n\nI ask only because it's a holy relic. It should be taken from these orc dogs for no other reason than to return it to Auchindoun.\n\nPerhaps then, a worthy vindicator of the Light will take it up to smite the enemies of the draenei.", objectives = "Retrieve Mo'mor's Holy Hammer.", progress = "I'm having trouble seeing. I may not have long.", completion = "Thank you for this kindness, <name>. Perhaps I can still salvage some scrap of honor." }
WordHunterWoW_QuestEN[34720] = { title = "Operation: Just Arrowhead", description = "It goes without saying that the Warsong in Telaar need to be dealt with. Rangari Ogir and his forces on the overlook will help you kill any of the orcs that are out in the open.\n\nYou just start the fight, and they'll end it with extreme prejudice.", objectives = "Kill 15 Warsong forces at Telaar.", completion = "That bit of justice is sure to have lifted the spirits of my rangari.\n\nLosing Telaar and many of our friends has taken a heavy toll.\n\nThank you, commander." }
WordHunterWoW_QuestEN[34721] = { title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far southeast of here, and fulfill your destiny.", objectives = "Speak to Seer Malune on Duskfall Island in Talador.", completion = "I am Seer Malune, the great keeper of memories. It is an honor to finally meet you." }
WordHunterWoW_QuestEN[34722] = { title = "Durotan Been Askin' For Ya", description = "Durotan been askin' for ya, mon.", objectives = "Speak with Durotan at your Garrison", completion = "You did well against a coordinated Thunderlord attack, <name>." }
WordHunterWoW_QuestEN[34723] = { title = "Ironfist Harbor", description = "", objectives = "" }
WordHunterWoW_QuestEN[34724] = { title = "The Forgotten Caves", description = "", objectives = "" }
WordHunterWoW_QuestEN[34725] = { title = "Vignette: Sea Hydra", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34726] = { title = "Vignette: Pale Spider Broodmother", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34727] = { title = "Vignette: Sea Lord Torglork", description = "", objectives = "" }
WordHunterWoW_QuestEN[34728] = { title = "The Shimmer Moor", description = "", objectives = "" }
WordHunterWoW_QuestEN[34729] = { title = "Blood Oath of Na'Shra", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?" }
WordHunterWoW_QuestEN[34730] = { title = "Blood Oath of Lokra", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "Commander <name>, Your mastery over the battlefield is astounding. If my people are to survive the coming conflict we will need more of our own people skilled in such warfare.\n\nIf you will have me, I would like to join your forces for a time. I wish to learn from you so that I might teach others in my clan.\n\nWill you accept my axe?" }
WordHunterWoW_QuestEN[34731] = { title = "Oath of Shadow Hunter Rala", description = "", objectives = "My sista have other duties, but I have leave of ol' Vol'jin to extend my services to you.\n\nYa proved your worth, and did a task that needed doing.\n\nI be followin' ya, boss-mon, if ya be willing." }
WordHunterWoW_QuestEN[34732] = { title = "Mulverick's Offer of Service", description = "", objectives = "Well, hero, I owe you both my life and my honor. I ask that you allow me to repay this debt by serving under your command.\n\nYou will find that I am a fearsome hunter. I have also mastered the art of riding the rylaks, which few among the Frostwolves can claim.\n\nWill you accept my service?" }
WordHunterWoW_QuestEN[34733] = { title = "Services of Dagg", description = "", objectives = "Gonna have to ask demself, \"Did Dagg get catched or did Dagg catched dem?\"\n\nBig hero been blowin' Dagg's cover! But you special, Dagg tinks. Dagg is master of dis guys and want to join you.\n\nDagg is unanimous in dis." }
WordHunterWoW_QuestEN[34734] = { title = "The Loyalty of Olin Umberhide", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[34735] = { title = "Thunderlord Invasion!", description = "Sir! Scouts have spotted Thunderlords approaching from the east.\n\nThe men are armed and ready. We'll mount defensive positions as soon as you take the field.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Legionaire Grimjaw in your garrison." }
WordHunterWoW_QuestEN[34736] = { title = "We Be Needin' Supplies", description = "Commander, our forces are not prepared for frost fightin'. I took da liberty and sent some of our shadow hunters north to establish a supply base. \n\nYa might want to be headin' up dere and see what they be up to. Look for a hollow between the Crackling Plains and the Savage Crag.", objectives = "Speak with Shadow Hunter Rala at Darkspear's Edge.", completion = "Eh dere, boss-mon! Watch ya step. Da ground be cracklin' and breakin' everywhere." }
WordHunterWoW_QuestEN[34737] = { title = "Masters of Shadow", description = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding.\n\nAll of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me.\n\n<Luuka takes a deep breath.>\n\nUngra, Gurran, and... umm... oh! Ankova.\n\nWill you protect me from them?", objectives = "Slay Ungra, Taskmaster Gurran, and Ankova the Fallen.", progress = "How goes your mission?", completion = "Well done.\n\nBe ready to move. We may have had the element of surprise within this cave, but our advantage is fleeting." }
WordHunterWoW_QuestEN[34738] = { title = "Nullin' Void", description = "If I'm reading their spells correctly, it seems that these Shadowmoon orcs are opening portals to bring prisoners here to the slave camps. Brilliant magic, really.\n\nUnfortunately, it is easily nullified.\n\n<Khadgar places a small rune in your hand.>\n\nThis rune will deal with their void magic. Activate it near their portals, and they will instantly be nullified.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Close 10 Shadowmoon Portals by using the Rune of Endless Ravening near them." }
WordHunterWoW_QuestEN[34739] = { title = "The Shadowmoon Clan", description = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, {name}.", objectives = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", completion = "You fight exceptionally well, <name>... better than I could ever hope to.\n\nWith those orcs out of the way, Khadgar and Maraad should now be able to safely guide the rest of our group through the cave." }
WordHunterWoW_QuestEN[34740] = { title = "Yrel", description = "Forgive me if I'm a bit flustered - I've never killed anyone before.\n\nMy name is Yrel, and I am a student of Karabor.\n\nYou say you have an ARMY with you? The Light must truly be watching over me today.\n\nI will follow you, then. Lead the way, {name}.", objectives = "Escort Yrel to safety.", completion = "Up there - that is Keli'dan the Breaker. No doubt he's been alerted to our presence, and he's attempting to tell his warlord about our little jailbreak.\n\nWe have to take him out, <name>." }
WordHunterWoW_QuestEN[34741] = { title = "Keli'dan the Breaker", description = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him.\n\nI will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", objectives = "Slay Keli'dan the Breaker.", completion = "Fine job in the cave, but this is no time to rest.\n\nWe have momentum. We must stay in motion." }
WordHunterWoW_QuestEN[34742] = { title = "Upper Blackrock Spire Challenge Mode - Consolation (Nth)", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34743] = { title = "Vignette: The Crystal Blade of Torvath", description = "", objectives = "" }
WordHunterWoW_QuestEN[34746] = { title = "Shields Down!", description = "Did you hear that? They got the shield up. There'll be no getting into Telaar now.\n\nYou must get that shield down. The only way to do it is to destroy the Arkonite crystal.\n\nDon't worry about me. You're going to kill two birds with one stone; Packleader Kargora is the one who stole your blueprints.", objectives = "Destroy the Arkonite Crystal and Collect the Garrison Blueprints from Packleader Kargora.", progress = "Good news?", completion = "Perfect! You retrieved the blueprints.\n\nThere's only one thing left to do." }
WordHunterWoW_QuestEN[34747] = { title = "The Honor of a Blademaster", description = "", objectives = "I am without a clan. The Burning Blade are dead to me. Perhaps someday I will create a clan of my own.\n\nIn the meantime, it would be an honor to fight at your side. You freed me and fought well.\n\nThere is much we could learn from each other. What do you say?" }
WordHunterWoW_QuestEN[34751] = { title = "Clear!", description = "You gotta help me fix this robot. I'm friggin' hungry!\n\nI built the Pleasure-Bot 8000 to locate Draenor truffles, and what does it do? It swims to this stupid island and shorts its power fluctuator.\n\nI got it hooked up to these batteries, but it ain't enough juice to jump it.\n\nBe a doll and get me the zapper sacs from the electric eels in the lake, would ya? They oughta be enough.", objectives = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador.", progress = "You got the stuff, buddy?", completion = "Yeah, that's the stuff! You're a good business partner, considering you're a <class> and all.\n\nNow let's just mash these into this port..." }
WordHunterWoW_QuestEN[34755] = { title = "Vignette: Mining Captain Bashgar", description = "", objectives = "" }
WordHunterWoW_QuestEN[34756] = { title = "A Charming Deception", description = "Reshad is more than he appears; a mottled old crow with his beak in a book, certainly, but we need him.\n\nShadows gather beneath the lonely spire, in Veil Terokk. Reshad must make it there safely.\n\nAlong the path you'll find charms primed with illusion spells. You need only touch them to take on Reshad's image.\n\nAdherent assassins are on the prowl for an old outcast with scrolls on his back. They will fall upon you.\n\nOh, but won't they be surprised when the illusion fades?! Kee-hee-hee!", objectives = "Use 5 Illusion Charms to draw out Adherent Harriers.", completion = "How very noble of you to act as bait on my behalf. I will not forget this." }
WordHunterWoW_QuestEN[34758] = { title = "Looking For Help", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Head southeast and see if you can find anyone on the shoreline.", objectives = "Find a local fisherman that can help our cause.", progress = "You think I am going to help you?", completion = "Time to see what you can do." }
WordHunterWoW_QuestEN[34760] = { title = "Treasure: Warchest of Kull'krosh", description = "", objectives = "" }
WordHunterWoW_QuestEN[34761] = { title = "Clear!", description = "Oh, the gnomanity!\n\nThe Pleasure-Bot 8000 broke before it could bring me a single Draenor truffle. It swam here and shorted its power fluctuator.\n\nAGAIN!\n\nI have power going to it, but it isn't enough to override the fluctuator.\n\nCould you get me the sacs from the electric eels in the lake? I think that would be just the ticket!", objectives = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador.", progress = "Do you have the eel sacs?", completion = "Those look perfect! By all that is mechanical, this had better work.\n\nNow let's just insert these here..." }
WordHunterWoW_QuestEN[34765] = { title = "The Den of Skog", description = "So this gronn infestation ain't gonna solve itself. You're gonna have to show them who's boss, Horde style!\n\nWith this many gronnlings around there is bound to be a full grown, big mama of a gronn. Find him... it... her... or whatever, and take it out, and the rest of those gronnlings might lose interest in our little operation here.", objectives = "Kill Skog.", progress = "You find that big gal... or guy... or gronn? Really, I ain't sure what to call them.", completion = "Little known fact, old gronn grottos make for great farming soil." }
WordHunterWoW_QuestEN[34766] = { title = "Logistical Nightmare", description = "Commander, I am afraid I have... troubling... news.\n\nThese saberon followed our encampment from Gorgrond, and have been stealing our supplies, ransacking our ledgers, and slaughtering our peons!\n\nI hate to ask of your time to deal with the matter, but all of our men are stationed guarding the camp from any further raids. We desperately need those supplies so we may enact your will!", objectives = "Retrieve 5 Sacks of Supplies and 5 Garrison Records.", progress = "Commander! Have you had time to locate our supplies and ledgers?", completion = "I never doubted you for a moment. You are truly a commander of the people.\n\nLok'tar ogar!" }
WordHunterWoW_QuestEN[34769] = { title = "A Choice to Make", description = "We're just about ready to go here. All that's needed now is for you to make your choice.\n\nTake a look at the blueprints on the drafting table.\n\nAre we going to construct a corral or a tankworks?", objectives = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", completion = "This is a momentous occasion, commander. I'll have Thaelin and his people get to work right away.\n\nYou'll see; this decision is going to be critical in our efforts against the Warsong." }
WordHunterWoW_QuestEN[34770] = { title = "The Honor of a Blademaster", description = "", objectives = "I am without a clan. The Burning Blade are dead to me. Perhaps someday I will create a clan of my own.\n\nIn the meantime, it would be an honor to fight at your side. You freed me and fought well.\n\nThere is much we could learn from each other. What do you say?" }
WordHunterWoW_QuestEN[34771] = { title = "Good Stuff", description = "", objectives = "" }
WordHunterWoW_QuestEN[34772] = { title = "Morkeths Cage", description = "", objectives = "" }
WordHunterWoW_QuestEN[34773] = { title = "Why Is The Brew Gone?", description = "Commander, we have a bit of a... uh... problem.\n\nThis group o' saberon followed us from Gorgrond, and they've been stealin' our footmen's swords an' slaughtering our peasants!\n\nI hate to ask fer your time, but all of yer men are guardin' the camp from any further raids. Plus...\n\n<Quartermaster O'Riley lowers her voice to a whisper.>\n\nThey took our beer!", objectives = "Retrieve 5 Footman Longswords and 5 Thunderbrew Kegs.", progress = "Commander! Have ye had a moment to deal with the saberon?", completion = "Oh thank goodness, I knew ye would come through!\n\nAt your service, as always." }
WordHunterWoW_QuestEN[34774] = { title = "Blingtron 5000", description = "", objectives = "You will accept this gift, and you will like it.  To do otherwise will automatically engage my organic incineration weapons.  Thank you.You will receive:" }
WordHunterWoW_QuestEN[34775] = { title = "Mission Probable", description = "Despite his recent captures, Olin Umberhide seems to be a tauren of some skill in combat. He certainly has learned how to get an enemy's attention.\n\nI have a mission available that might prove ideal for his skill sets.\n\nWhen you are ready, simply issue the order via the command table in front of me and we will dispatch him immediately.", objectives = "Use the Command Table to send Olin Umberhide on a mission.", progress = "Commander, I have a mission that might suite your new follower quite well.", completion = "As additional missions come to my attention I will make them available here." }
WordHunterWoW_QuestEN[34776] = { title = "Gatekeepers of Auchindoun", description = "I was taken captive by the Iron Horde when they raided our caravan en route to Auchindoun.\n\nI escaped, but these spirits won't let me through to join my fellow Sunsworn until someone defeats them in combat!\n\nPlease, will you help me defeat them?", objectives = "Defeat Vindicator Dalu and Soulbinder Halaari in combat.", progress = "I appreciate all of your help, hero.", completion = "Thank you, <name>. I am truly in your debt.\n\nWhen I fulfill my duties to Lady Liadrin I will come find you." }
WordHunterWoW_QuestEN[34777] = { title = "Gatekeepers of Auchindoun", description = "Auchindoun is under attack, stranger, and I intend to help defend it.\n\nThe only problem is the only armor I could find was my grandfather's old set, and it isn't nearly enough to defeat the spirits blocking the path toward Auchindoun.\n\nWould you defeat them and let me through the gate with you? I will find a way to repay you!", objectives = "Defeat Vindicator Dalu and Soulbinder Halaari.", progress = "I will defend Auchindoun with my life. We cannot lose anymore in this war!", completion = "You have my eternal gratitude, hero. I will find a way to repay you someday." }
WordHunterWoW_QuestEN[34778] = { title = "Migrant Workers", description = "{name}, more recruits arrive at your garrison every hour. We will soon run out of food.\n\nI have made contact with Exarch Akama in hopes of securing rations from Elodor, the breadbasket of this valley. He has agreed, provided we supply labor for the harvest. Everyone wins.\n\nIf you agree with my plan, speak with Foreman Zipfizzle here in the courtyard - he has gathered together available laborers. Akama and I will escort them and meet you at Elodor, far to the east!", objectives = "Speak with Foreman Zipfizzle in your garrison, then meet with the laborers outside of Elodor.", progress = "Where's the rest of the caravan?", completion = "You made it!\n\nBut... one of our wagons didn't. Have you seen Maraad? He's still out there somewhere." }
WordHunterWoW_QuestEN[34779] = { title = "Circle the Wagon", description = "One of our wagons fell behind, and disappeared somewhere in the woods to the northwest. Vindicator Maraad and several of your workers are stranded out there.\n\nFind them and bring them back!", objectives = "Find Maraad and the lost laborers and escort them back to Elodor Fields.", progress = "Did you find them? Check the woods to the northwest. If I know Maraad, he probably tried to take the shelter of a hill.", completion = "I am keeping the sickles. They remind me of a lesson so many of us draenei forget - that the Light lives in every farmer as much as in any priest.\n\nYou fight well, and I am pleased to call you friend. Your laborers will be safe here in Elodor. If you are not convinced, speak to Exarch Hataaru here. His devices secure all the draenei strongholds." }
WordHunterWoW_QuestEN[34780] = { title = "Invisible Ramparts", description = "Exarch Akama is too cautious, but we shouldn't ignore a threat from the Shadowmoon clan. It is good you are here!\n\nSince we arrived on Draenor I have dedicated myself to recreating the technology we left behind. This large structure here is a defense ward. It should counter a Shadowmoon advance - provided we power it up.\n\nI have prepared resonance crystals at my workshop to the south. Carry one crystal at a time to the three pylons that surround the ward, then activate the control panel nearby!", objectives = "Carry charged resonance crystals to the primary, secondary, and tertiary pylons.", progress = "<The console thrums with energy. You can't interpret anything on the display, but some of the lights are still blinking needily.>", completion = "The console thrums with energy and lights up as you draw near, as though sensing your presence. Simply touching the main panel brings the defense crystal to life outside.\n\nIf this is the kind of technology Hataaru was able to cobble together from spare parts, you can only imagine the splendor of the world he came from." }
WordHunterWoW_QuestEN[34781] = { title = "Defenstrations", description = "No sooner does power rush to the crystal outside than you hear distant war cries and shouts of alarm. Elodor is being attacked!\n\nIf you want your laborers to come home in one piece, you'd best help with the defense of the town. Defeat the invasion and then return to the control console to reset the defenses.", objectives = "Kill 8 Shadowmoon Raiders or Dark Priestesses.", progress = "The sounds of attack still reverberate from outside, which is alarming, given that the console seems awash with angrily blinking warning indicators.", completion = "You saved the town! The controls shut down as you approach, but many of the indicators are still blinking frantically. Something seems wrong.\n\nHataaru yells out to get your attention outside..." }
WordHunterWoW_QuestEN[34782] = { title = "The Exarch Council", description = "Good work at the gates! The Shadowmoon orcs have been seeking prisoners for some reason. Their aggression helps our cause.\n\nCome with me. I would like to introduce you to the Exarch Council, \"The Hand of the Prophet.\" I have been trying to convince the Exarchs to support our cause and go on the offensive against the Iron Horde, but they are - as always - too cautious and slow to act.\n\nCome with me, I will introduce you to Exarch Othaar up the hill. Perhaps meeting an Alliance hero can sway the council.", objectives = "Speak with Exarch Othaar in Elodor.", completion = "<Exarch Othaar is a towering, intimidating figure. His eyes bore into you, determining if you are friend or foe.>\n\nSo, you are <name>, esteemed <class> of this \"Alliance\" that has appeared on our shores. On behalf of the Exarch Council, I welcome you to Elodor." }
WordHunterWoW_QuestEN[34783] = { title = "Naielle, The Rangari", description = "I am calling the Exarch Council to order to hear your petition. None of us doubt that this \"Iron Horde\" is a threat, but few can agree on what we should do about it. It is up to you and Vindicator Maraad to gather the Exarchs together.\n\nExarch Naielle is the leader of the Rangari, the \"Eyes of the Prophet.\" They are our scouts who silently stalk the farthest corners of Draenor. Seek her out in the Rangari Enclave northwest of here.", objectives = "Speak to Exarch Naielle in the Rangari Enclave.", completion = "<name>! You have only just arrived but already your name is the talk of Elodor.\n\nI will gladly support your cause for the Exarch Council - it has always been my opinion that the draenei need to get out and be proactive in our world instead of hiding behind our walls.\n\nBut first, I need your help with something..." }
WordHunterWoW_QuestEN[34784] = { title = "Fun with Fungus", description = "It is our mission as rangari to explore and understand this world. Around you is the Umberfen. Many draenei lost their lives when we first discovered this place. The volatile spores burst whenever anyone approaches.\n\nBut we watched... and we learned.\n\nAround the swamp you'll notice \"Shimmershrooms,\" distinguished by their orange glowcaps. Their dust will make you invisible to the volatile spores. Grab the spores - gently! - and bring them to me.\n\nWe will forge this savage world into a weapon.", objectives = "Use the Shimmershrooms to safely gather 12 Volatile Spores.", progress = "Remember, unless you are covered in shimmershroom dust, the spores will explode as soon as you get near.", completion = "Careful with those... hand them here. Wonderful!\n\nI will have my rangari bury these around the perimeter of Elodor. If the Shadowmoon orcs dare attack us again, they are in for a nasty surprise!\n\nDraenor is a hostile world, but if we take the time to learn and understand it, we can turn it to our advantage.\n\nI will finish up here and meet with the Exarch Council shortly. I will be sure to back your proposal." }
WordHunterWoW_QuestEN[34785] = { title = "Hataaru, the Artificer", description = "I will also need you to call upon Exarch Hataaru. I understand you were helping him with our defenses at the gate.\n\nHataaru is our Chief Artificer - he understands our technology better than any other and has been working tirelessly to recreate the glory of the civilization we left behind.\n\nHe has moved to his workstation outside of the Elodor Dig, our crystal mines located just to the Southeast. Look for him at the mine entrance.", objectives = "Speak with Exarch Hataaru outside of the Elodor Dig.", completion = "Ah, <name>! I suspected I would see you again soon.\n\nI am willing to speak on your behalf at the Exarch Council, but an emergency situation has come up..." }
WordHunterWoW_QuestEN[34786] = { title = "Engorged Goren", description = "You must be the {class} that so impressed Exarch Hataaru. Can you help?\n\nThe Elodor Dig just behind me is overrun by strange stone creatures. These so-called goren actually devour minerals, metabolize them, and grow crystalline structures from their arms and back. Like most of the wildlife on this world, they completely baffle us.\n\nPlease slay as many as you can and gather their crystal scales for me. You'll be protecting our earthworkers and aiding our research at the same time.", objectives = "Collect $1Oa Crystallized Goren Scales from Crystalmaw goren in the Elodor Dig.", progress = "What's the status inside the dig?", completion = "<The artificer withdraws a loop and peers intently at the scales you've brought him.>\n\nUnreal. The crystalline matrix is flawless, as if produced from one of our forges on Argus.\n\nI wish we could hook up these creatures to our machinery... but I suspect the Exarch would take issue with that.\n\nThank you for your help!" }
WordHunterWoW_QuestEN[34787] = { title = "Exarch Maladaar", description = "The council is almost assembled: Othaar, myself, Hataaru and Naielle are ready. Only Exarch Maladaar remains. He has not been himself since he returned from his capture at the hands of the Iron Horde... but Vindicator Maraad was able to track him down.\n\nFind Maladaar at the Fey Landing, just south of the town center.", objectives = "Speak with Exarch Maladaar at the Fey Landing south of Elodor.", completion = "<name>, my Alliance friend from Tanaan! I have not forgotten my debt to you.\n\nI will do everything in my power to convince the council to support you in every way possible. However...\n\n\n\nI have grave concerns about our safety here." }
WordHunterWoW_QuestEN[34788] = { title = "Friend of the Exarchs", description = "Only three members remain of the Exarch Council, but we are all deeply indebted to you. The vote is unanimous: Your Alliance will have our full support on Draenor.\n\nWe are also going to place a draenei representative under your direct command. Three potential candidates are here in the courtyard. Speak to them and choose who you want - we will dispatch him or her immediately to your garrison!", objectives = "Choose a follower (either Andren, Chel, or Onaala) and then speak with Exarch Naielle.", progress = "Who are you going to pick, <name>?", completion = "An excellent choice! We'll send your pick directly to your garrison to help with any missions you encounter.\n\nNow, about those supplies you requested..." }
WordHunterWoW_QuestEN[34789] = { title = "Speaker for the Dead", description = "This was a betrayal from within. There's no other explanation for it. None of the Exarchs trust each other now - especially me. But Othaar and Akama can damn their laws. We've got to rout out the traitor and the only way to do it is to speak to the corpse!\n\nJoin me just outside the Altar of Sha'tar atop the eastern cliffs. Soulbinder Nyami and I will perform an exorcism to save Hataaru's immortal soul... and maybe learn who did this to him.\n\nDo you trust me, {name}?", objectives = "Meet Exarch Maladaar at the cliffs east of the Altar of Sha'tar. Complete the ritual to cleanse and interrogate Hataaru's corpse.", progress = "Exarch Hataaru didn't deserve to die that way. Not like this.", completion = "One of the five Exarchs is dead. Another is a traitor. Dark times.\n\nWe will end this here and now. Can I count on you for one final task?" }
WordHunterWoW_QuestEN[34790] = { title = "The Sting", description = "The exarchs seem to trust you, {class}. Are you venturing into the Umbrafen?\n\nThe Sporebats in this area are usually docile, but something's got them all riled up. When they attack, their stingers wrap around exposed limbs. I've seen them tear through reinforced leather like it was paper. How do they work, I wonder?\n\nCould you bring me a pristine sporebat stinger? I'd love to study it.", objectives = "Acquire a Pristine Sporebat Stinger from a Moonglow Sporebat.", progress = "Most draenei avoid the Umbrafen, but we rangari seem drawn to the most dangerous places - that's where you really learn how the world works.", completion = "Would you look at that - the entire tentacle is barbed. Uggh. No wonder the wounds they inflict tend to get infected. We could learn something from this. I wonder if rangari explorers should start equipping themselves with whips?\n\nThank you, <name>. This Alliance that you come from must be quite the collection of heroes!" }
WordHunterWoW_QuestEN[34791] = { title = "Warning the Exarchs", description = "You set the book ablaze, but not before noting its contents. The demonic tome was dedicated to enchanting weapons with fel energy. It looked as though the goal was to ensnare the victim's soul.\n\nThe Exarchs must be warned that traitors are among them! The Council should be meeting now just up the hill to the east.", objectives = "Talk to Exarch Maladaar at the Altar of Sha'tar in Shadowmoon Valley.", completion = "Dead! Exarch Hataaru is dead! His body was discovered moments ago, stabbed in the back. The weapon that killed him was fel in origin. Tell me everything you know.\n\n<Maladaar nods as you describe what you found.>\n\nYes. The traitors wanted to capture Hataaru's soul. Someone wants something he knows, dead or alive... We must act at once." }
WordHunterWoW_QuestEN[34792] = { title = "The Traitor's True Name", description = "We must give the traitor no place to hide. I have a focusing lens that will illuminate cloaked fel energy. If it were placed on a high point, it could act like a beacon, lighting up anyone in town who reeks of the fel taint.\n\nThere is a prayer circle atop the Exarch's Rise to the north that will serve our purpose. Plant the focusing lens, {name}. If you reveal anything, deal with it. Then meet me below.", objectives = "Plant the Focusing Lens atop the Exarch's Rise in Shadowmoon Valley.", progress = "What happened up there?", completion = "<The Exarch listens to your tale, his face contorting into concern, grief, and finally anger.>\n\nSo Othaar has lost his way. \"Socrethar\" he calls himself now. At last we have our answer. I fear my capture at the hands of the Iron Horde was his doing. There may be other traitors amongst us - I must hurry back to Auchindoun and make sure we are safe.\n\nIn the meantime, I believe the Exarchs owe you a decision..." }
WordHunterWoW_QuestEN[34793] = { title = "Auchenai Defenders Greeting", description = "", objectives = "" }
WordHunterWoW_QuestEN[34794] = { title = "Taking the Fight to Nagrand", description = "Boss-mon, good to see ya.\n\nDurotan recommended dat we be gettin' a foothold in Nagrand, so I taken the liberty of dispatchin' some of da boys.\n\nThrall's already reportin' that the outside be nearly complete. He been askin' me to let ya know they be ready for ya.\n\nA windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, sir.", objectives = "Speak with Stone Guard Brox at the caravan in Nagrand.", completion = "They came at us... from... nowhere.\n\n<The stoneguard nearly passes out.>" }
WordHunterWoW_QuestEN[34795] = { title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded into... the Burning Blade....\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", objectives = "Speak with Thrall at Wor'var.", completion = "Commander <name>. It's good to see you. We have much to discuss.\n\nThe situation in Nagrand is rapidly deteriorating. The Warsong clan is on the move.\n\nTo make matters worse, Grommash has named Garrosh their new warlord." }
WordHunterWoW_QuestEN[34801] = { title = "A Pilgrimage Gone Awry", description = "I am a humble pilgrim, I swear. Please don't hurt me!\n\nMy sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, you have to help me. I'm desperate. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back. I just know it....", objectives = "Gather 6 Prowler Blood, 6 Snapdragon Fronds, and a Riverhopper Eye.", progress = "Tuliaa isn't just my sister. She's my best friend.", completion = "Thank you, stranger." }
WordHunterWoW_QuestEN[34802] = { title = "A Pilgrimage Gone Awry", description = "My sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, I need your help. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back... I just know I can...", objectives = "Gather 6 Prowler Blood, 6 Snapdragon Fronds, and a Riverhopper Eye.", progress = "I don't know what I would do without Tuliaa... she's not just my sister. She's my best friend.", completion = "Thank you, a thousand times thank you." }
WordHunterWoW_QuestEN[34803] = { title = "Send Them Running", description = "Your scouts have located the saberon's alpha male just outside our gates!\n\nCommander, I believe that dispatching this target will send any of these remaining vermin running back to their caves.\n\nI do not wish to ask more of you, but you are the only one capable of this task, sir.", objectives = "Slay Vicegnaw just outside Vol'jin's Pride.", progress = "Is the alpha male dispatched?", completion = "For <name>! For the Horde!" }
WordHunterWoW_QuestEN[34804] = { title = "Not In Your House", description = "Sir, we have located the saberon's alpha male just outside our gates!\n\nWe believe that slaying him will send any remaining saberon running with their tails between their legs, but the beast is positively massive!\n\nI do not wish to call upon you once more, but you are the only one capable of this task.", objectives = "Slay Ripgut just outside Fort Wrynn.", completion = "Victory! For the Alliance!" }
WordHunterWoW_QuestEN[34805] = { title = "Echo Hunters", description = "I am no sorcerer, but I've picked up a few spells in my time - enough for me to pass unseen by the naked eye.\n\nUnfortunately, the vampire bats in these woods don't use their eyes. They will hear my shuffling robes and Percy's incessant clucking a mile away.\n\nClear them away from the path, would you?", objectives = "Slay 10 Echo Hunters.", completion = "Blasted things. Nothing more than flying rats if you ask me!" }
WordHunterWoW_QuestEN[34806] = { title = "Prune the Podlings", description = "The blood soaked body of Ryan is slumped up against the cave wall. Tiny teeth marks cover his body.\n\nThe podlings clearly are a threat to you and your garrison.\n\nIt's time to do a little pruning.", objectives = "Take revenge on the podlings." }
WordHunterWoW_QuestEN[34807] = { title = "Vignette: Goldmane the Skinner", description = "", objectives = "" }
WordHunterWoW_QuestEN[34808] = { title = "More Lazy Peons", description = "We have a rare opportunity to strike at the heart of the Warsong. But, we need your wisdom and leadership.\n\nThe most important decision will be your choice between building a corral or a tankworks. This choice will setup our approach to the fight against the Warsong.\n\nThazz'ril will head up our building efforts. Will you give him a hand?\n\nIt looks like he's having trouble motivating his peons to work.", objectives = "Motivate 8 Lazy Peons.", progress = "If there's one thing the Horde never seems to be short on, it's lazy peons.", completion = "I knew it was a mistake to bring these guys with me from the Valley of Trials." }
WordHunterWoW_QuestEN[34809] = { title = "A Lesson in Mineralogy", description = "<Gazmolf gestures at the large machine nearby.>\n\nI built this machine to break down elementium minerals into base elements. You see, it's not just what's buried within the ground that can be valuable; but also the ground itself!\n\nTake, for example, the earth elementals below us; inside every earth elemental is an earthen core, dense in precious metal!.\n\nThose elementals are going to make us rich! Collect several earthen cores, place them in the Gold-O-Matic 9000, and I'll give you a cut!", objectives = "Collect 4 Earthen Cores.", progress = "<The Gold-O-Matic 9000 buzzes and whirrs with the sounds of heavy machinery.>", completion = "<The Gold-O-Matic 9000 crunches and grinds through the elemental remains.>\n\nchakk-chackk-chak-chak, chak-a-chak-akk-chk-chk-chk." }
WordHunterWoW_QuestEN[34810] = { title = "Gazmolf Futzwangler and the Highmaul Crusade", description = "I'm here in Nagrand recruiting for the Steamwheedle Preservation Society. We're the archaeological branch of the Steamwheedle Cartel.\n\nWe're here to collect all of the artifacts, relics, antiquities and oddities that Nagrand has to offer! Currently, we're hiring surveyors, excavators, adventurers... you name it!\n\nIf you're interested in getting your hands dirty, talk to Gazmolf Futzwangler over at Stonecrag Gorge. He's the goblin in charge of this expedition!", objectives = "Speak with Gazmolf Futzwangler.", completion = "It's good to see that there's still an interest out there in real archaeology!\n\nThere's a lot of misconceptions out there about how archaeology is really done, but have no fear! The great and famous Gazmolf Futzwangler is here to educate you." }
WordHunterWoW_QuestEN[34811] = { title = "Good Help is Hard to Find", description = "The excavation team is on strike!\n\nForeman Thazwix and his cronies think they can squeeze the Steamwheedle Preservation Society for some extra dough by refusing to work.\n\nWhat I need is a scab, a strikebreaker; someone to put some pressure on them by doing the job they refuse to do!\n\nGo down into the gorge, dig up some antiquities for me, and I'll pay you what I would have payed those lazy numbskulls!", objectives = "Collect 8 Nagrand Antiquities.", progress = "Do you have the Nagrand Antiquities?", completion = "Great work, <name>!\n\nThat bunch of good-for-nothing's came crying when they found out someone else was making their money! I don't think Thazwix, or his cronies, will be much trouble from here on out.\n\nAs promised, here's the pay I owe you for a job well done!" }
WordHunterWoW_QuestEN[34812] = { title = "Horde Stables Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[34813] = { title = "Horde Workshop Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[34814] = { title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me!\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nHe's waiting at my tower. Let's leave immediately and introduce you to one another.", objectives = "Follow Archmage Khadgar and speak with Magister Krelas in Zangarra.", progress = "You are <name>, I presume?", completion = "I am Magister Krelas. Pyromaniac.\n\nPleasure." }
WordHunterWoW_QuestEN[34815] = { title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me.\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nShe's waiting at my tower. Let's leave immediately and introduce you to one another.", objectives = "Follow Archmage Khadgar and speak with Magister Serena in Zangarra.", completion = "Nice to meet you.\n\nI am Magister Serena. Frost mage extraordinaire!" }
WordHunterWoW_QuestEN[34817] = { title = "Altar Altercation", description = "Save the prisoners from the Altar.\n\n[NOTE: THIS QUEST WILL GET SIGNIFICANT REVAMP ONCE WE GET THE ALTAR IN]", objectives = "" }
WordHunterWoW_QuestEN[34818] = { title = "They Call Him Lantresor of the Blade", description = "The garrison blueprints were taken to the Burning Blade village when the Warsong sacked your caravan. I can't construct this building without those plans.\n\nThere's been talk of a young blademaster who's been exiled from the clan for many years. They call him Lantresor of the Blade.\n\nOur scouts recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you recover the blueprints?", objectives = "Find Lantresor of the Blade in Hallvalor.", completion = "Who are you?\n\nDon't you know death by sight, <class>?" }
WordHunterWoW_QuestEN[34819] = { title = "Fruitful Ventures", description = "Oh no! They must be vegetarians.\n\nWhat these elekk need is fruit and lots of it. There are cherries all over the place around here under the trees.\n\nYou wouldn't mind grabbing me some, would ya?", objectives = "Collect 15 Nagrand Cherries.", progress = "I heard the worst rumor about how you have to obtain those things.\n\nSomething about talbuk first eating them and then 'processing' them, and then... well, I don't want to talk about it.", completion = "You got them all? I just know this is going to work." }
WordHunterWoW_QuestEN[34820] = { title = "Lost Lumberjacks", description = "Shelly and her crew haven't returned from Gloomshade Grove.\n\nIt's been days... I hope everything is okay.", objectives = "Find out what happened to Shelly and the missing lumberjacks.", completion = "This is one of the pack mules Shelly and her crew took to Gloomshade Grove." }
WordHunterWoW_QuestEN[34821] = { title = "Khadgar Summon", description = "", objectives = "" }
WordHunterWoW_QuestEN[34822] = { title = "What We Need", description = "I heard you guys hijacked and wrecked a ship on your way out of Tanaan.\n\nIt's like my daddy always said: One man's wreck is another goblin's workshop.\n\nYou should head down to the coast west of the garrison and see if you can't find any materials we might salvage. Oh, and uh... should probably watch yourself. I hear there are ogre raiders in the area.", objectives = "Collect 10 Drudgeboat Salvage.", progress = "How's the salvage operation comin'?", completion = "Hey... now that is some nice salvage. Say what you will about the Iron Horde, but they got some serious raw materials to work with." }
WordHunterWoW_QuestEN[34823] = { title = "The Ogron Live?", description = "Commander, our Frostwolf allies reportin' dat the Bladespire ogres have an outpost to our west led by an ogron.\n\nI heard tales of da ogron but never seen one. Dey be brutes, creatures from a time that was best left forgotten. Dey say most were slain during the forming of the original horde. What dey lack in wisdom they make up for in violence, force, and greed.\n\nI counsel dispatchin' dis creature as soon as possible.", objectives = "Slay Groog.", progress = "Where the ogron goes, death and pain are sure to follow.", completion = "Well done, boss-mon. The Bladespire ogres been pullin' back their raiding parties. But ya can bet dey be comin' back, and in larger numbers. The threat from their citadel must be dealt with soon." }
WordHunterWoW_QuestEN[34824] = { title = "What We Got", description = "Every fortress needs three things.\n\nOne: peons! Find Skaggit and have him get our peons back to work.\n\nTwo: building materials. I had the peons set up a cache for you where they will store resources they create while you are away. You should check it out.\n\nAnd three: raw experienced muscle! Constructing buildings in a garrison can take some time but I think we can speed up your first building by hiring Skaggit's recently promoted Senior Peon II. Find him and tell him I sent ya.", objectives = "Have Skaggit get the peons working, investigate your Garrison Cache, and find Senior Peon II.", progress = "If buildin' a stronghold were easy, everybody'd be doin' it.", completion = "Yeah, that's the stuff. Lumber, stone, peons, more peons. It's like we are building you a stronghold or something." }
WordHunterWoW_QuestEN[34825] = { title = "Vignette: Gruuk", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34826] = { title = "The Friend of My Enemy", description = "Hallvalor is the ancestral home of the Burning Blade clan. Since they're such fast friends, the Warsong have allowed the blademasters to remain in Nagrand.\n\nWe are fierce, but we won't win if the Burning Blade attack us. It would be wise to strike first.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", completion = "A great victory over the Burning Blade!\n\nThis new Warlord Azuka Bladefury sounds formidable. We will have to keep an eye on her and her blademasters." }
WordHunterWoW_QuestEN[34827] = { title = "Last of the Talonpriests", description = "Talonpriests live among us in secret, guarding the rites of the Talon King's return.\n\nThe Adherent proclamation you acquired in Skettis revealed two of them living in the Shadowglade to the north. Orcs have moved into the region, and the Adherent's beam weapon left Veil Akraz a smoking crater.\n\nAs you can see, my people are beset by enemies on all sides.\n\nTalonpriest Ishaal survived and is in hiding. Drink this elixir near his hut to peer into the shadows and make contact with him.", objectives = "Drink the Elixir of Shadow at Ishaal's Hut in the Shadowglade.", completion = "Hm, not what I was expecting when I heard that Iskar was sending help.\n\nNo matter. You'll have to do." }
WordHunterWoW_QuestEN[34828] = { title = "Ishaal's Orb", description = "The Adherents came for me, but I was already hiding. I watched from the shadows as they ransacked my hut.\n\nThen I watched the Shattered Hand orcs arrive and butcher them like dinner fowl. Seems everyone is after us these days.\n\nOne of those orc thugs made off with my scrying orb. I will be needing it back if I am to be of any use to Iskar.", objectives = "Retrieve Ishaal's Orb from Camp Thornscar.", progress = "Have you found the orb?", completion = "Hmm... something's not right. She's been tampered with.\n\nSomeone else has used my orb to enter the realm of shadows." }
WordHunterWoW_QuestEN[34829] = { title = "New Neighbors", description = "The Shattered Hand clan is made up of orcs who can call no other clan home. They are sadistic warriors who maim their bodies, perhaps in a show of solidarity or perhaps because they simply enjoy the pain.\n\nIt does not matter. What matters is that they are expanding their territory, butchering anyone in their path.\n\nThey must be dealt with.", objectives = "Slay 15 Shattered Hand orcs in Camp Thornscar.", completion = "Blood for blood, as it should be." }
WordHunterWoW_QuestEN[34830] = { title = "Behind the Veil", description = "Soon after the orcs swept in, Veil Akraz was laid to waste by a beam of light from Skyreach.\n\n<Ishaal's eyes glass over as he peers into his orb.>\n\nIt seems they missed their true target. Zellek is still there, hiding in the realm of shadow.\n\nAnd... someone else as well. The orc assassin who used my orb.\n\nTake this. Drink it in Veil Akraz and find Zellek.\n\nOh, and be careful. It's a little more potent than the last one. You'll see...", objectives = "Drink the Major Elixir of Shadows at Zellek's hut in Veil Akraz.", completion = "Well, you are not stabbing me yet.\n\nThat is a good sign." }
WordHunterWoW_QuestEN[34831] = { title = "Encounter Mushroom", description = "", objectives = "" }
WordHunterWoW_QuestEN[34833] = { title = "Prune Ancient", description = "", objectives = "" }
WordHunterWoW_QuestEN[34834] = { title = "General Commentary", description = "", objectives = "" }
WordHunterWoW_QuestEN[34835] = { title = "Gather Energy", description = "", objectives = "" }
WordHunterWoW_QuestEN[34836] = { title = "Lunarblossom", description = "How I long to hold Kat'la.\n\nNo star or moon can compare to her beauty.\n\nAlas, I am but a simple boar farmer.\n\nIf only I could find time to sneak away from this pathetic excuse for a job and pick some lunarblossoms for Kat'la.\n\nI wouldn't dare confess my love to her without a gift.", objectives = "Pick 5 Lunarblossoms.", progress = "How can I help you, <class>?", completion = "Lunarblossoms! You are too kind! I can't wait to give these to Kat'la." }
WordHunterWoW_QuestEN[34837] = { title = "Going to the Gordunni", description = "We have a good supply of jovite in the arsenal now but there just isn't enough of the material in the mine to keep us in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", objectives = "Travel to Gordal Fortress and meet up with Morketh Bladehowl.", completion = "I crafted a few things before we left that we may need: some bombs, a grappling hook, even was able to get one of the goblins to get a spare rocket pack.\n\nI'm sure we'll find a use for everything." }
WordHunterWoW_QuestEN[34838] = { title = "Ikky's Egg", description = "<Miraculously, this single egg has eluded the ravagers.\n\nA small tag has been lovingly tied around the base of the egg. It reads \"Ikky.\">", objectives = "Help Ikky hatch from the Kaliri Egg in Shadowglade.", completion = "<The hatchling springs immediately to flight, then looks at you expectantly and cheeps.>" }
WordHunterWoW_QuestEN[34839] = { title = "Vignette: Skog", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34840] = { title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our artillery gunners back at the arsenal.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", objectives = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", completion = "Now that we're inside we have much to do." }
WordHunterWoW_QuestEN[34841] = { title = "Treasure: Ice-Covered Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[34842] = { title = "The Den of Skog", description = "Olin Umberhide appears to have discovered the parent of the gronnlings and is outmatched by himself. He will be slain without help.You will learn:", objectives = "Kill Skog." }
WordHunterWoW_QuestEN[34843] = { title = "Vignette: Chillfang", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34844] = { title = "We Require More Resources", description = "So what we got here is a good start, but you are looking for something that can support ARMIES!\n\nTruth is, we ain't building anything without the materials to build it, and our supplies from Azeroth are limited.\n\nI got some ideas on how to get you started but you are going to have to keep your eyes open for more materials when out in the field. Lots of useful stuff out there we can change into usable material.", objectives = "Gather 50 Garrison Resources.So what we got here is a good start, but you are looking for something that can support ARMIES!\n\nTruth is, we ain't building anything without the materials to build it, and our supplies from Azeroth are limited.\n\nI got some ideas on how to get you started but you are going to have to keep your eyes open for more materials when out in the field. Lots of useful stuff out there we can change into usable material.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34845] = { title = "Lurking in the Shadows", description = "There are reports of Shadowmoon clan members lurking around the ruins by the shore.\n\nThis is a popular spot for young lovers to gaze at the stars and confess their affection for each other.\n\nAs you can see we are not a village of warriors.\n\nI will pay you handsomely if you go to the ruins and make sure the Shadowmoon orcs keep their distance.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Shadowmoon Disrupters." }
WordHunterWoW_QuestEN[34846] = { title = "Fish Fight", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Think you are up to the task?", objectives = "Find a local fisherman that can help our cause." }
WordHunterWoW_QuestEN[34847] = { title = "Forbidden Love", description = "My son, Kral'za, is beyond stubborn. \n\nAfter we split from the Shadowmoon Clan he refused to let go of his relationship with a young Shadowmoon orc.\n\nI forbid him to see her anymore. He ran off earlier today and has not returned. \n\nI don't trust Dol'mak. Like the other Shadowmoon orcs she continues to dabble in the void.", objectives = "Find Kral'za.", completion = "Aka'Magosh, <class>. I knew that void witch was no good." }
WordHunterWoW_QuestEN[34848] = { title = "To Even the Odds", description = "[TEMP] The Shattered Hand orcs are using their prisoners as living training dummies. Let's even the odds and give them some weapons.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Shattered Hand weapons and give them to Battered Frostwolf Prisoners or Battered Karabor Prisoners." }
WordHunterWoW_QuestEN[34849] = { title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}. Then, I'll break myself free.", objectives = "Retrieve Lantresor's Blade from Instructor Luhk.", progress = "A blademaster without a blade is no blademaster at all.", completion = "If you can defeat Luhk, then perhaps there's some hope for you after all." }
WordHunterWoW_QuestEN[34850] = { title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", objectives = "Find the Blademaster's Banner in a Burning Blade Locker.", progress = "Do you have my banner?", completion = "I don't expect you to understand the importance of what you've done.\n\nPerhaps one day you will." }
WordHunterWoW_QuestEN[34851] = { title = "Vignette: Gruuk", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Destroy $1oa Goren Egg Clusters, $2oa Iceforge Ironchewers, and Broodmother Reeg'ak.Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34855] = { title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", progress = "We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", completion = "Now with the viziers gone the whole Gordunni enchantment trade with the Iron Horde will come crashing down!\n\nWe can now turn our attention to dealing with Morkurk." }
WordHunterWoW_QuestEN[34856] = { title = "Gok Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[34857] = { title = "Tracking Flag: Orcs Kicked Out of Cave", description = "", objectives = "" }
WordHunterWoW_QuestEN[34858] = { title = "Prized Repossessions", description = "The Gordunni were given copies of my blades as a gift from the Iron Horde. But what do they use them for? Toothpicks!\n\nSure the blades are low grade copies but it's still MY design and I can't stand to think of them in those ogre hands for a moment longer!\n\nSir, While we are in here can you do me a favor and get those blades out of their hands!", objectives = "Collect 6 Gordunni \"Toothpick's\" from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress.", progress = "Were you able to get all of my blades back?", completion = "Thank you, commander. With this another stain on my honor has been removed." }
WordHunterWoW_QuestEN[34859] = { title = "Vignette: No'losh", description = "", objectives = "" }
WordHunterWoW_QuestEN[34860] = { title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", objectives = "Recover 6 Iron Horde Shipments.", progress = "The goblins said that the flares would surely get their attention. I just hope it doesn't come from the hillside being blown apart.", completion = "Alright, that should be the last one we need. \n\nNothing feels as good as knowing you are stronger than your enemy!" }
WordHunterWoW_QuestEN[34861] = { title = "We Need An Army", description = "So the new warchief decided to send you Warmaster Zog to handle local operations. Zog!\n\nI heard that guy was notorious for organizing the Alliance AND the Horde to face off against the silithid at the Gates of Ahn'Qiraj.\n\nHe was a general back then.\n\nAnyway, if you go let him know about the barracks being done I'm sure he'll have some thoughts on how to put it to good use.\n\nYou can find Zog up at the town hall.", objectives = "Speak with Warmaster Zog.", completion = "Commander, it is an honor to serve you." }
WordHunterWoW_QuestEN[34862] = { title = "Vignette: Light the Braziers", description = "", objectives = "" }
WordHunterWoW_QuestEN[34865] = { title = "Vignette: Skog", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34866] = { title = "Meet Me in the Cavern", description = "It's time, {class}. Time for you to get your blueprints.\n\nTime for us to face the masters.", objectives = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", completion = "You made it. Good.\n\nGetting in here was nothing compared to what's to come." }
WordHunterWoW_QuestEN[34867] = { title = "The Secrets of Gorgrond", description = "Commander, I will leave my forces to secure this pass, but I will not sit idle while our enemy prepares for another attack.\n\nI want to take the fight to the heart of the Iron Horde at Blackrock, and to do that we are going to need to go where few orcs dare tread.\n\nGorgrond.\n\nIt is a savage place, filled with giants and monsters of every sort.\n\nWill you dare these wilds with me so that we might strike at the foundries of the Iron Horde?", objectives = "Meet Durotan in Gorgrond.", completion = "Gorgrond is no place for armies, commander. We are now stepping into the domain of legends." }
WordHunterWoW_QuestEN[34868] = { title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your blueprints and your life. Or, you will be dead.", objectives = "Survive the Burning Blade's trial by combat and retrieve the Garrison Blueprints.", progress = "Do you have the garrison blueprints, commander?", completion = "The garrison blueprints. Outstanding.\n\nThere's only one thing left to do." }
WordHunterWoW_QuestEN[34869] = { title = "Tastes Like Chicken", description = "You got a moment, bub? I've got an elekk-sized problem.\n\nSomeone, um, sold me... yeah, sold me these two, but they're sick. I've tried everything, but nothing I do makes any difference!\n\nI think they must be starving. I heard that elekk like raw windroc. Gross if you ask me.\n\nAnyway, while you're out doing your thing, you mind picking me up some bird meat?", objectives = "Collect 10 Raw Windroc from windroc in Nagrand.", progress = "Windrocs? Yeah, Nagrand's filthy with them.\n\nThey seem to like high places and rock outcroppings.\n\nI don't know. What do I look like - a windroc whisperer? You're the <class>.", completion = "It sure doesn't smell like chicken!\n\nOkay, okay, hand it over. I'll feed them and then everyone will be happy and I can turn a tidy - er, um... they'll feel better.\n\nYeah." }
WordHunterWoW_QuestEN[34870] = { title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. He's the one that set up the Iron Horde trade and, even worse, my former boss gave him one of my best maces!\n\nWe got to get my mace back! I mean... we need to kill him to secure the jovite for your arsenal!\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to dodge an attack quickly or something.\n\nAlso, if you happen to find my mace I'd like to get it back.", objectives = "Defeat Witch Lord Morkurk within Gordal Fortress and obtain \"Fury of the Forge\".", progress = "Do you have my mace?", completion = "Fine work commander! Your combat skills are clearly second to none. I am honored to be your armorer!\n\nLet's get back to the outpost so we can take stock of our new inventory. I saved a few flares to call us in a ride back." }
WordHunterWoW_QuestEN[34871] = { title = "Supply Recovery Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34872] = { title = "Prized Repossessions Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34873] = { title = "Punching Through Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34874] = { title = "Next Steps", description = "You are positively on fire!\n\nWe have everything I need to create the scroll. Your arcane sanctum will be brimming with arcane energy in no time.\n\nI will teleport to Vol'jin's Pride to combine the reagents and marshal your forces. Meet me there when you can.", objectives = "Speak to Magister Krelas at Vol'jin's Pride.", completion = "Your forces burn with passion for your cause.\n\nNot easy against such towering foes. Well done." }
WordHunterWoW_QuestEN[34875] = { title = "Next Steps", description = "We did it! We have all of the reagents for the scroll. Your arcane sanctum will be the talk of Draenor before long.\n\nI'll go back to Fort Wrynn to finish it and gather your men. Meet me there.", objectives = "Speak to Magister Serena at Fort Wrynn.", completion = "Now we can tackle getting that artificial nexus for your tower." }
WordHunterWoW_QuestEN[34876] = { title = "Loola's Lost Love", description = "Oh it was horrible.\n\nMy husband and I were fishing in the marsh, I fell asleep and when I woke up he had been turned into a toad!\n\nI'm sure it was one of those Shadowmoon orcs I hear so much about.\n\nHe jumped into the muddy waters before I could catch him.\n\nWill you help me find my lost love, {class}?", objectives = "Search Loose Mud for Old Loola's husband.", completion = "Hmm... I'm sure one of these toads is my husband." }
WordHunterWoW_QuestEN[34877] = { title = "Removing the Reinforcements", description = "My own investigations have uncovered a permanent arcane portal from here to Highmaul itself.\n\nIt is guarded but shouldn't be too hard to disrupt once you've gotten some breathing room.", objectives = "Destroy the Portal to Highmaul.", completion = "Excellent.  I doubt they will rebuild it after we've completed all of our objectives here.\n\nThis place will return to being a failing outpost for the Gorian Empire." }
WordHunterWoW_QuestEN[34878] = { title = "The Foot of the Fortress", description = "We've enkindled your forces and the scroll is ready.\n\nIt's time for phase two - stealing a nexus crystal from a heavily fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills and take what is more or less rightfully yours!", objectives = "Speak to Magister Krelas at the entrance to Gordal Fortress.", completion = "My apologies for teleporting away. It's cheating, I know.\n\nI merely wanted to put a fire under your feet to get here quickly!" }
WordHunterWoW_QuestEN[34879] = { title = "Dropping In", description = "Witch Lord Morkurk is no fool.\n\nHe has catapults set up throughout the foothills leading into their compound.\n\nNo matter, I have a way to handle them.\n\nTake out the ogres guarding the siege weapons and mark them once they're clear. I'm readying a vortex spell that will handle things from there.\n\nWe'll meet just outside their gate afterwards.", objectives = "Help Magister Krelas destroy 3 Gordunni Boulderthrowers.", completion = "Before we take on Morkurk we have some business to attend to in the fortress proper." }
WordHunterWoW_QuestEN[34881] = { title = "Earth, Wind and Fire...and Water", description = "The Elemental Plateau has become unstable, and so the cycle of rebirth must begin.\n\nIt is a natural part of our life cycle that impurities are accumulated in the elemental body over time.\n\nWhen enough contamination has taken place, an elemental will become unstable and in some cases volatile.\n\nA necessary part of rebirth is pure, living essence which can be found atop the Elemental Plateau, as well as in the body of an elemental spirit.\n\nReturn to me with the essence and we shall begin the rebirth.", objectives = "Collect 4 of each living essence from the Elemental Plateau.", progress = "Bring to me the living essences of the elements, that I may plant the seeds of rebirth.", completion = "You have done well.\n\nAlthough the Elemental Plateau is no longer stable, the cycle of rebirth will soon take place and the elements will be born anew." }
WordHunterWoW_QuestEN[34882] = { title = "Blades in the Dark", description = "Those orcs got hold of Ishaal's orb, did they? That would explain the dangerous-looking fellow who crossed into this realm shortly before you.\n\nNot everyone handles the transition as... gracefully as you did. The oaf is still grappling with his own mind, stumbling about and muttering nonsense.\n\nSoon he will be drawn to the orb again, which would presumably lead him to Veil Terokk.\n\nBetter to take him out now while he's still befuddled.", objectives = "Slay Malrok Thornscar in Veil Akraz.", completion = "He was a big boy, wasn't he? The fiends will make quite a feast of him." }
WordHunterWoW_QuestEN[34883] = { title = "A Feast of Shadows", description = "Many arakkoa died in Veil Akraz. From the outside, all seems still. Empty.\n\nBut in this place between worlds, death never goes unnoticed.\n\nStray life essence seeps through from the other side; a feast for the beings who prowl here.\n\nSlay the shadow creatures here, and gather from their corpses the fine dust they produce. I will need much of it to perform the rites of the Talon King.", objectives = "Gather 10 Shadow Dust.", progress = "You know those elixirs you have been so eagerly quaffing?\n\nThey are made of this stuff.", completion = "Good. With this much dust we can delve deep enough to reach the Talon King's refuge." }
WordHunterWoW_QuestEN[34884] = { title = "The Kaliri Whisperer", description = "An important contact lives in the nearby Shadowglade. He is meek, but trains kaliri of monstrous size which are quite dangerous.\n\nHe once claimed they could knock a rylak out of the sky, but I'll believe that when I see it.\n\nSkizzik is holding a valuable treasure for me. Seek him out and get him back to Veil Terokk if you can. At the very least, recover the gavel I entrusted to him.", objectives = "Recover the Old Gavel from Skizzik.", progress = "Any word on Skizzik?", completion = "I see. Well, at least the gavel is safe.\n\nAs you may have guessed, it is another of the Talon King's relics." }
WordHunterWoW_QuestEN[34885] = { title = "Mother of Thorns", description = "<Beneath Skizzik's outstretched hand, letters are scrawled into the dirt:\n\nt h o r n\n\nm o t h e r\n\nRavagers brought in by the Shattered Hand have taken over the aviary and are breeding fast. If left alone, they could be swarming the entire area - including Veil Terokk - in a matter of days.>", objectives = "Slay 5 Shadeback Ravagers and the Shadeback Thornmother.", completion = "Shame about Skizzik's aviary. That's where Percy came from. Skizzik wasn't interested in the \"runts\" after he started breeding the big ones full-time.\n\nTo be honest, I never liked those monstrous things." }
WordHunterWoW_QuestEN[34886] = { title = "Baby Bird", description = "<Ikky cheeps again, then begins gnawing on his foot.\n\nLooking out across the nearby hillside, you spy tiny ravager grubs inching along the grass.>", objectives = "Gather 8 Ravager Grubs in the Shadowglade.", progress = "<Ikky looks up at you, foot clamped in his beak, and lets out a muffled cheep.>", completion = "<You hold the handful of grubs out, steel yourself, and prepare to chew them up as a mama bird would.\n\nThankfully, Ikky snatches them from your hand before you can proceed.\n\nApparently kaliri don't do that.>" }
WordHunterWoW_QuestEN[34887] = { title = "While We're in the Neighborhood", description = "Ah, the hubris of ogres.\n\nIt always backfires.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nWe can disenchant these bracelets into reagents that will no doubt be useful to your arcane sanctum. What do you think about collecting some while we're here?", objectives = "Collect 8 Gordunni Runebeads.", progress = "Most mages discount the use of arcane dust these days, but they're wrong.", completion = "Yes, these will definitely be useful! Trust me." }
WordHunterWoW_QuestEN[34888] = { title = "Vicious Viziers", description = "We're after Witch Lord Morkurk, but we shouldn't charge straight at him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are the only other capable mages left of the Gordunni, and are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out first.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", progress = "I don't take chances.", completion = "Now that they're out of the way, Morkurk is exposed." }
WordHunterWoW_QuestEN[34889] = { title = "Orbs of Power", description = "There's a minor fire we'll need to put out before we can enact my plan.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - awfully detrimental to our scroll of mass teleportation.\n\nThankfully, no ogre would ever consider that a single enemy or two would have the gall to breach their walls.", objectives = "Destroy 5 Astral Wards.", completion = "There's nothing Morkurk can do to stop us now.\n\nWell done indeed!" }
WordHunterWoW_QuestEN[34890] = { title = "The Final Step", description = "It's time to fight fire with fire.\n\nWe have Morkurk cornered. His protections gone. Use the scroll once you engage Morkurk...\n\n...and enjoy the fireworks.", objectives = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress.", progress = "Ogres. It's always ogres.", completion = "That's what we were after.\n\nLet's get out of here!" }
WordHunterWoW_QuestEN[34891] = { title = "Elemental Attunement", description = "Many shaman have sought the favor of the Throne of Elements.\n\nForming an elemental bond with the furies allows a shaman to not only know the will of the elements on Draenor, but also tap into a great font of elemental power.\n\nIf you are to discover the truth behind Gordawg's disappearance, you will need to succeed where others have failed and undertake the Ritual of Binding.\n\nFirst, you must prepare yourself. Seek out the elemental pillars upon the plateau and attune your spirit with the elements.", objectives = "Seek out the four elemental pillars.", completion = "You have done well, <name>.\n\nBy linking with each of the four elemental pillars you have attuned your life energy with each of the elements on Draenor.\n\nYou are now ready to undertake the Ritual of Binding.\n\nSpeak to me when your work upon the Elemental Plateau is finished, and we shall begin." }
WordHunterWoW_QuestEN[34893] = { title = "Guardians of the Plateau", description = "The Elemental Plateau is sanctuary to the elemental spirits of Nagrand.\n\nThe greatest among the elementals on the plateau are the guardians; mighty elemental spirits that stand watch over their domain.\n\nThe guardians are pure and mighty spirits but a disturbance in the natural balance has caused them to grow unstable, corrupting the lesser elementals around them.\n\nIn order to restore balance to the plateau, the guardians must be destroyed. Only then will the cycle of rebirth begin.", objectives = "Destroy the corrupted guardians atop the Elemental Plateau.", completion = "Each of the guardians you put to rest were once mighty and noble elemental spirits.\n\nIn time each shall be reborn anew through the cycle of rebirth, but Gordawg must be found and balance restored lest the plateau become unstable yet again." }
WordHunterWoW_QuestEN[34894] = { title = "A Rare Bloom", description = "Many years ago I had a life-mate, Dahaka. We were only bound a short time before she was taken from me.\n\nI have lived long, but I have never known greater pain than that day. I was young and my grief was great; the earth quaked beneath my rage. I laid her to rest upon this cliff.\n\nIt is here where I too will rest, but first a favor.\n\nA rare bloom grows in a cave within the fiery, molten earth of the plateau. It was her favorite.\n\nI would lay the flower upon her grave one last time before I die.", objectives = "Retrieve the Ember Blossom from the Elemental Plateau.", progress = "Do you have the Ember Blossom?", completion = "This is a fine Ember Blossom that you have brought to me. I know the danger you faced to retrieve it and I thank you." }
WordHunterWoW_QuestEN[34895] = { title = "Dropping Bombs Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34896] = { title = "Tracking Quest - Stealthed Rangari", description = "", objectives = "" }
WordHunterWoW_QuestEN[34897] = { title = "Rangari Roundup", description = "You have a keen eye, {class}.\n\nThere are Rangari like myself hidden throughout the Nightmarsh.\n\nI need reports from each of them to ensure the area is safe.\n\nPerhaps you can help me?", objectives = "Find the 5 Hidden Rangari.", completion = "Thank you for the report, <name>. We must keep a close eye on these southern wilds." }
WordHunterWoW_QuestEN[34898] = { title = "Ikky", description = "", objectives = "<Ikky cheeps at you excitedly.\n\nIt seems you've made a new friend.>" }
WordHunterWoW_QuestEN[34899] = { title = "A Choice to Make", description = "We're ready to start building. All that we need is for you to make a choice.\n\nThe blueprints are on the drafting table. Take a look.\n\nThen, let me know if we're going to construct a corral or a tankworks.", objectives = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", completion = "This is a momentous occasion, commander. Thazz'ril and his peons will get to work right away.\n\nYou'll see; this decision is going to be critical in our efforts against the Warsong." }
WordHunterWoW_QuestEN[34900] = { title = "New Babies", description = "That's better, but there's still something wrong. I'm getting desperate here, {name}.\n\nCan I call ya, {name}? Great.\n\nLook, I think I have it now. I know what's wrong.\n\nThey miss their babies.\n\nYeah! When they first came here, the, uh... the bastard hunters that... abandoned them said they left the babies behind.\n\nIf we're going to save them from a life of misery, if we're going to save those babies, <under his breath> and turn a tidy profit, we've got to get them some new babies!", objectives = "Coax 5 Tenderhoof Meadowstompers.", progress = "Look, I know these things can be stubborn, but it's all going to be worth it in the end.\n\nTrust me.", completion = "You did it, <name>! Mama, papa, and family. It brings a tear to my eye.\n\nHere, take this runty one. Now that I have the whole herd, this one's just an extra mouth to feed and won't fetch anything at market." }
WordHunterWoW_QuestEN[34904] = { title = "Portal Vision", description = "", objectives = "" }
WordHunterWoW_QuestEN[34905] = { title = "Placeholder Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[34906] = { title = "Krelas Summoned", description = "", objectives = "" }
WordHunterWoW_QuestEN[34907] = { title = "Vignette/Treasure: Lagoon Pool/Giant Clam", description = "", objectives = "" }
WordHunterWoW_QuestEN[34908] = { title = "The Foot of the Fortress", description = "Your forces are at the ready and the scroll is prepared.\n\nIt's time for phase two - stealing a nexus crystal from a fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills to head into the fortress proper.", objectives = "Speak to Magister Serena at the entrance to Gordal Fortress.", completion = "Let's not waste any time. Gordal Fortress awaits just up this hill." }
WordHunterWoW_QuestEN[34909] = { title = "While We're in the Neighborhood", description = "Ogres from the empire are known for being cold and calculating.\n\nWe are fortunate that their calculations are rarely spot on.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nSince we're going to have to dispatch them anyways, we might as well get some reagents out of it.", objectives = "Collect 8 Gordunni Runebeads.", progress = "Ah, arcane powder. Reminds me of my days as an apprentice.", completion = "They're not amazing, but I do think these have some worth to us." }
WordHunterWoW_QuestEN[34910] = { title = "Vicious Viziers", description = "We can't just skate in, kill Witch Lord Morkurk, and leave.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all fiercely loyal to Morkurk, and are all respectable mages in their own right.\n\nI suspect that if we attempt to engage the Witch Lord immediately that they will rush to his aid and overwhelm us. We need to take out his lieutenants first.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", completion = "Now that they're out of the way, Morkurk is exposed." }
WordHunterWoW_QuestEN[34911] = { title = "Orbs of Power", description = "Minor issue, I'm afraid.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - not wonderful considering our plan.\n\nThankfully, no ogre would ever consider that a single enemy or two would attack, so we should be able to slip through their fortress relatively easily.", objectives = "Destroy 5 Astral Wards.", completion = "Destroying those wards was key to our success. Well done indeed!" }
WordHunterWoW_QuestEN[34912] = { title = "The Final Step", description = "We have Morkurk cornered. He's all ours now. Use the scroll once you engage Morkurk...\n\n...and enjoy the blizzard of your forces raining down on his head.", objectives = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress.", progress = "It's all come down to this moment.", completion = "Looks like Morkurk was no match for the two of us, huh?" }
WordHunterWoW_QuestEN[34913] = { title = "Dropping In", description = "Witch Lord Morkurk, the leader of the fortress, has catapults set up along the road into their compound.\n\nThat won't be a problem for us.\n\nTake out the ogres around the catapults and mark them for me. This vortex spell I have prepared will handle the rest.\n\nWe'll meet at the gate to the fortress once the catapults are gone.", objectives = "Help Magister Serena destroy 3 Gordunni Boulderthrowers.", progress = "I certainly hope they have more than this to stop us.", completion = "We have the scroll of mass teleportation ready, but we can't use it just yet. We must take proper precautions to ensure our success." }
WordHunterWoW_QuestEN[34914] = { title = "Target of Opportunity: Telaar", description = "We've received reports that the draenei enclave at Telaar has fallen to the Warsong.\n\nI sent a small group of shadow hunters to check on the situation.\n\nKajassa is their leader. Will you meet her there?", objectives = "Speak with Shadow Hunter Kajassa at Telaar.", completion = "Glad dat Aggra send ya, Commanda.\n\nDey situation is grim, an' it's 'bout ta get grimma." }
WordHunterWoW_QuestEN[34915] = { title = "I Help Ya Kill Dem", description = "Warsong come in an' kill de draenei rangers. No lettin' dem have dis place.\n\nYou an' me, Commanda. We gonna kill dem all.\n\nYou be distractin' dem an' I usin' me Loa ta finish dem off. You see.", objectives = "Kill 12 Warsong forces at Telaar.", completion = "Oh, dat was fun. We workin' nicely togetha, you an' me, <name>." }
WordHunterWoW_QuestEN[34916] = { title = "The Blessing of Samedi", description = "Three of mah shadow huntas come here wit' me. De Warsong kill dem.\n\nWe need ta help dey souls move on. Jus' in case ya find dem first, use dis on dere bodies.\n\nIt send dere souls ta Samedi, Loa of de Grave.", objectives = "Use the Fetish of Samedi on the corpses of the dead shadow hunters.", completion = "Dey movin' onta a betta place. Samedi be sendin' dem on all dey missions now.\n\nDank ya, <name>." }
WordHunterWoW_QuestEN[34917] = { title = "Shields Up!", description = "The Warsong packleader is trying to raise Telaar's shield. If Kargora does that, the Warsong will have an impervious base.\n\nSo far, they've only managed to initiate the shield. This has the undesirable side effect of protecting the packleader and her shaman at the main crystal.\n\nActivate the crystals on the perimeter of Telaar. That will force the shield to fully deploy.\n\nOnce you do that, Kargora will be exposed.", objectives = "Activate the four Telaari Crystals.", completion = "Soon de shield gonna cover all of Telaar. Den we all be trapped inside togetha.\n\nDen we go kill de packleader." }
WordHunterWoW_QuestEN[34918] = { title = "Shields Down!", description = "De time has come, commanda. Packleader Kargora an' de Arkonite Shield no longa protected.\n\nWe need ta kill her an' destroy de shield crystal.", objectives = "Kill Packleader Kargora and destroy the Arkonite Shield.", completion = "I'm sorry to hear about Kajassa's shadow hunters, but we couldn't afford to let the Warsong have Telaar.\n\nWith the death of Kargora and her pack, we're one step closer to the invasion of the Warsong's home, Grommashar.\n\nOne step close to justice." }
WordHunterWoW_QuestEN[34920] = { title = "Destroy Ward", description = "", objectives = "" }
WordHunterWoW_QuestEN[34921] = { title = "Cult of the Ravenspeakers", description = "These outcasts are not the only cursed arakkoa holding their ground in Arak.\n\nA curious cult has formed in worship of Ka'alu, my consort and the keeper of my brood. They are considered to be quite... odd.\n\nRegardless, the outcasts will need their help. Without the wings of the ravens, Iskar can never take his fight to the spires.\n\nTake this feather and place it in the offering basket south of here. The so-called \"Ravenspeakers\" will surely take notice.", objectives = "Place the Plume of Anzu in the Offering Basket in Gnarlwood Pass.", completion = "Ah, you come to learn the truth of things.\n\nWe will need to test your dedication first, yes!" }
WordHunterWoW_QuestEN[34922] = { title = "Words of the Raven Mother", description = "We came here to perform the ritual of calling to bring the return of the Raven Mother. We had distributed parts of the scroll to everyone and had just begun when we were attacked by the Bloodmane. Now most of the flock has been killed and fragments lay scattered across our homeland.\n\nThe ritual was a failure but we will not allow these mongrels to break our faith. We must continue our prayers here but we would be grateful if you can recover the scroll fragments for us.", objectives = "Recover 8 Ravenspeaker Scroll Fragments.", progress = "We must have all the sacred texts! We cannot afford to leave even a single one unaccounted for!", completion = "Ah! The copies of the ritual!\n\nPraise the Raven Mother!\n\nHand them to me but only one at a time. We must not risk summoning the light." }
WordHunterWoW_QuestEN[34923] = { title = "The Bloodmane", description = "We had just arrived and begun the service of the headless fowl when the Bloodmane attacked out of nowhere.\n\nClearly, this means that the Raven Mother wishes to test the worthiness of her children. Fear not, we are steadfast and will fervently continue our prayers regardless of what may come!\n\n<Sekara leans in and whispers to you.>\n\nAlthough, if you can get rid of the Bloodmane and their leader that would be a blessing as well.", objectives = "Slay Huntmaster Sorrowfang and 10 Bloodmane Razorclaws.", completion = "Your strength has given us time to rest and continue our rituals.\n\nMay the Raven Mother ever keep you in her shadow." }
WordHunterWoW_QuestEN[34924] = { title = "The Egg Thieves", description = "The Bloodclaw are sadistic creatures. They have attacked the Ravenskar before and have stolen the eggs of the sacred ravens.\n\nWhile you are within the Bloodclaw lands keep an eye out for the eggs.\n\nI'll be waiting for you at the nest with as many baskets for them as I can gather.", objectives = "Collect 8 Dread Raven Eggs.", progress = "Were you able to find the stolen raven eggs?", completion = "These poor ravens have avoided a horrible future in the Bloodclaw lands.\n\nWe will take far better care of them.\n\nThank you!" }
WordHunterWoW_QuestEN[34925] = { title = "Polishing the Iron Throne", description = "These stinking Blackrock cowards think they're humiliating me.\n\nThey're just making me angrier.\n\nOverseer Gotrigg, in the hut over there, carries my shackle key. If I'm going to get out of there, I'm going to need that key. Then... vengeance can begin.", objectives = "Obtain Ga'nar's Shackle Key from Overseer Gotrigg in the nearby building.", progress = "You'll have to pry that key out of his cold, ugly hand.", completion = "<Ga'nar works his neck out of the shackle.>\n\nMuch better." }
WordHunterWoW_QuestEN[34926] = { title = "Get to High Ground!", description = "This dam is about to burst. Hopefully.\n\nFarseer Drek'Thar fights atop the peak to the south of here. You should be safe near him.\n\nDon't worry about me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to Drek'thar in the Blackrock Quarry in Tanaan Jungle.This dam is about to burst. Hopefully.\n\nFarseer Drek'Thar fights atop the peak to the south of here. You should be safe near him.\n\nDon't worry about me.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34929] = { title = "Vignette: Gennadian", description = "", objectives = "" }
WordHunterWoW_QuestEN[34931] = { title = "Treasure: Frostwolf Cache 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[34932] = { title = "Guise of the Deceiver", description = "In a cave not far from here, there lives an old woman named Challe.\n\nI knew Challe many years ago when I was young; though as I have become old and grey, she has kept her youth and beauty.\n\nChalle was jealous of my love for Dahaka and I have long suspected that Challe had a part in her death. However, without evidence I could not bring justice against her.\n\nMeet with Challe and tell her that I am dying. Tell her that I wish to know the truth of Dahaka's fate before I leave this world.", objectives = "Speak with Challe to discover the truth.", progress = "I have not much time left. Please, discover the truth of Dahaka's death before it is too late.", completion = "Challe, that iniquitous wretch!\n\nIf only I had proof of her treachery long ago, I would have ripped the villainous heart from her chest and crushed it beneath my foot!\n\nYou have brought me the truth as I asked, for that you have my thanks." }
WordHunterWoW_QuestEN[34934] = { title = "Initial Defenders", description = "", objectives = "" }
WordHunterWoW_QuestEN[34935] = { title = "After Wall Greeting", description = "", objectives = "" }
WordHunterWoW_QuestEN[34936] = { title = "Treasure: Lady Sena's Extra Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[34937] = { title = "Treasure: Skaggit's Extra Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[34938] = { title = "Ralshiara's Demise", description = "It was said in the Journal of the Rising Sun that eating in the mornings cannot be done without harming a few eggs.\n\nThe Bloodmane matron, Ralshiara, feasts upon sacred raven eggs for her snacks. How dare she! She must die for her sins!\n\nTake the path south over the mountains to reach the accursed home of the Bloodmane.\n\nTake this trinket, it fell to us from the heavens as a sign of the Raven Mother's favor and with it you might have a chance.", objectives = "Kill Ralshiara.", completion = "Let it be known that on this day the stranger has returned victorious from slaying the feared foe of the Flock!\n\nPraise the Raven Mother!" }
WordHunterWoW_QuestEN[34939] = { title = "Declawing The Bloodmane", description = "It is written in the Scroll of Sermons to \"Bite the claw that strikes you.\"\n\nTake the path south from here that leads over the mountain to the Bloodmane valley in the west. There you will find those of their tribe who can use a primitive form of magic. Slay them and remove their paws.\n\nOnce you have obtained a few bring them back to me in the nest so that they may be offered to the Raven Mother!", objectives = "Collect 6 Bloodclaw Shaman Paws.", progress = "It is written in the Scroll of Sermons that the Raven Mother is not patient, and neither am I.\n\nDo you have the paws of the Bloodmane for me?", completion = "Yes, these will do nicely as an offering to the Raven Mother! May she feast upon our enemies!" }
WordHunterWoW_QuestEN[34940] = { title = "Treasure: Spider Dagger", description = "", objectives = "" }
WordHunterWoW_QuestEN[34941] = { title = "The Debt We Share", description = "These mortal shells that we call bodies are not ours to keep. The body is a gift of earth that must one day be returned from whence it came.\n\nThe time has come for this body to return to the elements.\n\nKnow that you have lifted the weight from an old heart, {name}. As I pass on from this realm, I do so without regret. I have fought on behalf of my people and my land, I have served the elements, and I have loved.\n\nIt would honor me if you would stay during these final moments, {class}.", objectives = "Speak with Gar'rok.", progress = "When I face my ancestors in the realm of spirits I will do so without shame or fear, for I have lived an honorable life.", completion = "Gar'rok was a loyal keeper and a true friend. He will be missed, but so is the cycle of life on this world.\n\nIn time we will call a new keeper of the elements, and he will serve us as Gar'rok did before him." }
WordHunterWoW_QuestEN[34942] = { title = "Back from Beyond", description = "We must begin preparations for the Talon King's return.\n\nFrom within this realm, I can travel quickly to Veil Terokk.\n\nYou, however, should be returned to the other side. You are powerful, and will attract unwanted attention.", objectives = "Speak with Shadow Sage Iskar in Veil Terokk.", completion = "Excellent work. Ishaal and Zellek have already begun the rites." }
WordHunterWoW_QuestEN[34943] = { title = "An Old Friend", description = "Since the beginning, a shaman has been called to serve the Throne of Elements as its keeper. It is a lifelong calling and a new keeper is only called after the last has passed on.\n\nGar'rok has been our loyal keeper for many years, cleansing the Elemental Plateau during countless cycles of rebirth.\n\nOur keeper is dying, and soon another will be called in his place. When he passes, he should not be alone. Go to him, {name}.\n\nEase his pain.", objectives = "Speak with Gar'rok.", completion = "Kalandrios sent you to me? I am honored.\n\nThe furies are wise, they know the burdens of my heart.\n\nYou may not know, but you have been sent to grant a last request to a dying shaman.\n\nFor this, I am grateful." }
WordHunterWoW_QuestEN[34944] = { title = "A Flock of Fledglings", description = "[PH] asdfYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "[PH] asdf" }
WordHunterWoW_QuestEN[34945] = { title = "Tracking Flag - Underseer Bloodmane Vignette", description = "", objectives = "" }
WordHunterWoW_QuestEN[34946] = { title = "Morkurk Greeting", description = "", objectives = "" }
WordHunterWoW_QuestEN[34947] = { title = "Shredder Manual", description = "Hey! I hear there's a curious object nearby. Scouts say it's some kind of shredder manual.\n\nGo check it out for me, will ya? I wonder if it has to do with this new prototype I've been hearin' about...", objectives = "Find the Iron Shredder Decommission Orders.", completion = "These orders appear to have come from Orgrim Doomhammer." }
WordHunterWoW_QuestEN[34948] = { title = "Shredder Manual", description = "I've been hearing rumors of this new prototype shredder the Iron Horde's engineers have been working on.\n\nI think we ought to investigate. A shadow hunter spotted some sort of shredder manual, and it might have something to do with that prototype.", objectives = "Find the Iron Shredder Decommission Orders.", completion = "These orders appear to have come from Orgrim Doomhammer." }
WordHunterWoW_QuestEN[34949] = { title = "Joining the Ranks", description = "", objectives = "We've had quite the journey in getting your tower burning bright. If it's agreeable to you, I'd like to join your campaign." }
WordHunterWoW_QuestEN[34950] = { title = "Dreadpiston", description = "Nearby, a group of Iron Horde took over a key strategic position with surprising alacrity.\n\nThey used a machine they call Dreadpiston to terrible effect in the siege, and I believe we need to destroy that machine before moving against the Iron Horde in Tuurem.", objectives = "Defeat Dreadpiston.", completion = "An infernal machine." }
WordHunterWoW_QuestEN[34951] = { title = "They Call Him Lantresor of the Blade", description = "The Burning Blade clan at Hallvalor is supplying the Warsong with weapons and warriors. We cannot let this continue.\n\nThere's a young blademaster who's been exiled from the Burning Blade for many years. They call him Lantresor of the Blade.\n\nMy rangari recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you deal with the Burning Blade.", objectives = "Find Lantresor of the Blade in Hallvalor.", completion = "Who are you?\n\nDon't you know death by sight, <class>?" }
WordHunterWoW_QuestEN[34952] = { title = "The Friend o' My Enemy", description = "Hallvalor is the ancestral home o' the Burning Blade clan. Since they be such fast friends, the Warsong allow the blademasters an' their shaman to remain in Nagrand when all o' the other clans are forced out.\n\nBlah, blah, blah.\n\nI say, if they're the friend o' my enemy, then they're my enemy, and that's all I need to know!", objectives = "Kill 15 Burning Blade forces at Hallvalor.", completion = "You done us a solid with them Burning Blade, lad, and we're not the forgettin' kind.\n\nLet's celebrate o'er a pint in an hour. Drinks are on me." }
WordHunterWoW_QuestEN[34953] = { title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", completion = "You done us a solid with them Burning Blade, lad, and we're not the forgettin' kind.\n\nLet's celebrate o'er a pint in an hour. Drinks are on me." }
WordHunterWoW_QuestEN[34954] = { title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}.", objectives = "Retrieve Lantresor's Blade from Instructor Luhk.", progress = "A blademaster without a blade is no blademaster at all.", completion = "If you can defeat Luhk, then perhaps there's some hope for you after all." }
WordHunterWoW_QuestEN[34955] = { title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", objectives = "Find the Blademaster's Banner in a Burning Blade Locker.", progress = "Do you have my banner?", completion = "I don't expect you to understand the importance of what you've done.\n\nPerhaps one day you will." }
WordHunterWoW_QuestEN[34956] = { title = "Meet Me in the Cavern", description = "It's time, {class}. Time to face the masters.", objectives = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", completion = "You made it. Good.\n\nGetting in here was nothing compared to what's to come." }
WordHunterWoW_QuestEN[34957] = { title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your life. Or, you will be dead.", objectives = "Survive the Burning Blade's trial by combat.", completion = "A great victory over the Burning Blade!\n\nThis new Warlord Azuka Bladefury sounds formidable. We'll have to keep an eye on her and her blademasters." }
WordHunterWoW_QuestEN[34958] = { title = "The Shadow of the Worldbreaker", description = "Looks like we'll soon have another obstacle in our way: that ridiculously large tank that they have pointed at the Dark Portal. The Iron Worldbreaker, I think they call it.\n\nIf I had some documentation on how it might work, then I might be able to figure out how to shut it down. Maybe some o' those machinists and laborers have some documentation on how it works?", objectives = "Obtain the Worldbreaker Schematics from Blackrock Orcs in the Blackrock Quarry.", progress = "Any luck?", completion = "Mmm... yes... simple enough.\n\n<The dwarf flips through the pages and no longer seems to notice your presence.>" }
WordHunterWoW_QuestEN[34959] = { title = "Dreadpiston", description = "The Iron Horde overtook a peaceful draenei outpost without mercy.\n\nThey used a machine they call Dreadpiston to level the town in minutes.\n\nDestroy it.", objectives = "Defeat Dreadpiston.", completion = "They will not use that machine to kill any more draenei. Thank you, <name>." }
WordHunterWoW_QuestEN[34960] = { title = "The Land Provides", description = "The icevines of the Shivering Trench have developed a powerful resistance to cold temperatures. Integrating them into the construction materials of the garrison should prove useful.", objectives = "Collect 30 Frozen Plant Matter.", progress = "Look at you, bein' all resourceful.", completion = "Now this is some handy stuff. This weather has been cutting through our supplies of rope so quick we need something we can use to provide an alternative. Looks like you scored the jackpot." }
WordHunterWoW_QuestEN[34962] = { title = "Khadgar's Plan", description = "We have the Iron Horde backed into a corner now, thanks to you.\n\nIt is almost time to enter the city of Shattrath and repel them.\n\nFirst, we must meet Khadgar and some new allies.", objectives = "Speak with Khadgar near the gates of Shattrath.", completion = "You have done great work with Durotan, Draka, and Gazlowe." }
WordHunterWoW_QuestEN[34963] = { title = "Khadgar's Plan", description = "Shattrath must not fall into the hands of the Iron Horde. It is time again for me to get my hands bloody.\n\nWe will tell Khadgar we are ready to enter the city and take back what is rightfully ours.", objectives = "Speak with Khadgar near the gates of Shattrath.", completion = "You have done great work with Maraad, Yrel, and Thaelin." }
WordHunterWoW_QuestEN[34964] = { title = "The Farseer Awaits", description = "Your presence has been requested at the Throne of Elements, {name}.\n\nFarseer Drek'Thar heard the call of the furies upon the wind and made the journey to commune with the elements.\n\nThe Farseer has sent word that you are to join him at the Throne of Elements.\n\nGo and see what the elements would have of you.", objectives = "Find Farseer Drek'Thar at the Throne of Elements.", completion = "Throm-Ka, <name>. All is not right in Nagrand, it is good that you are here." }
WordHunterWoW_QuestEN[34965] = { title = "Called to the Throne", description = "It was not long after I arrived in Nagrand that the voice of Kalandrios called out to me upon the wind.\n\nIt is a great honor to be called to the Throne of Elements, but my heart was heavy sensing the purpose.\n\nThere is dark malaise in the air, it can be felt all around us. It surrounds all life here...enveloping...smothering...\n\nCome, it is time we commune with the furies and lend them our aid. An invisible shadow has been cast upon this valley and it may be up to us to remove it.", objectives = "Commune with the furies at the Throne of Elements.", progress = "It is time that we communed with the furies regarding the sickness here.", completion = "I fear that this disturbance is more dire than I had anticipated.\n\nWhatever it is...it threatens to unravel the elemental bonds that hold this world together." }
WordHunterWoW_QuestEN[34966] = { title = "Doug Test - Daily Repeatable", description = "", objectives = "" }
WordHunterWoW_QuestEN[34967] = { title = "Treasure: Raided Loot", description = "", objectives = "" }
WordHunterWoW_QuestEN[34968] = { title = "Treasure: Ice-Covered Supplies", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[34969] = { title = "Serena Summoned", description = "", objectives = "" }
WordHunterWoW_QuestEN[34970] = { title = "Darkmoon Iron Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.You will receive:", objectives = "Return the Iron Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[34971] = { title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to evac.\n\nI'm glad that wasn't needed but we could still use the ride back to the arsenal.\n\nAre you ready, sir?", objectives = "Speak to Morketh Bladehowl in Vol'jin's Pride.", completion = "The outpost is now fully up and running and we have enough material to outfit an army - your army!" }
WordHunterWoW_QuestEN[34972] = { title = "Armor Up", description = "", objectives = "It took a lot of hard work but we have made a beautiful arsenal here.\n\nSir, I've been able to outfit your soldiers here with new equipment but I'd like to do more.\n\nI'd be deeply honored if you would let me work for you in your main garrison." }
WordHunterWoW_QuestEN[34973] = { title = "Darkmoon Moon Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.You will receive:", objectives = "Return the Moon Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[34974] = { title = "Darkmoon Visions Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.You will receive:", objectives = "Return the Visions Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[34975] = { title = "Darkmoon War Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.You will receive:", objectives = "Return the War Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[34976] = { title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our gunners back at the artillery tower.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", objectives = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", completion = "Now that we're inside we have much to do." }
WordHunterWoW_QuestEN[34977] = { title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use in our artillery tower! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", objectives = "Recover 6 Iron Horde Shipments.", completion = "Alright, that should be the last one we need. \n\nIt isn't the same as retaking Shattrath, but knowing the Iron Horde won't be getting these supplies gives me a bit of satisfaction." }
WordHunterWoW_QuestEN[34978] = { title = "Prized Repossessions", description = "The Gordunni have plagued the people of Shattrath ever since the city was founded. Over time they amassed quite a hoard of weapons they captured from our defenders in raids.\n\nGetting these weapons in the hands of our soldiers would be practical and I personally would like to get them out of the hands of the ogres.\n\nWhile we are in here can you do me a favor and gather up any of those weapons you come across.", objectives = "Collect 6 Shattrath Guardian Maces from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress.", progress = "Were you able to find any weapons?", completion = "Thank you, commander. With this a great dishonor on the legacy of Shattrath has been removed." }
WordHunterWoW_QuestEN[34979] = { title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", progress = "We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", completion = "Now with the viziers gone the whole Gordunni enchantment trade with the Iron Horde will come crashing down!\n\nWe can now turn our attention to dealing with Morkurk." }
WordHunterWoW_QuestEN[34980] = { title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. We need to kill him to secure the jovite for use in our artillery tower.\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to avoid any of his deadly magic.\n\nArchenon poros!", objectives = "Defeat Witch Lord Morkurk within Gordal Fortress.", completion = "Fine work commander! Your combat skills are clearly second to none. I am honored to be your armorer!\n\nLet's get back to the outpost so we can take stock of our new inventory. I saved a few flares to call us in a ride back." }
WordHunterWoW_QuestEN[34981] = { title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to quickly escape.\n\nI'm glad that wasn't needed but we could still use the ride back to the artillery tower.\n\nAre you ready sir?", objectives = "Speak to Miall in Fort Wrynn.", completion = "The outpost is now fully up and running and we have enough material to outfit an army - your army!" }
WordHunterWoW_QuestEN[34982] = { title = "Armor Up", description = "", objectives = "It took a lot of hard work but we have made a beautiful artillery tower here.\n\nSir, I've been able to outfit your soldiers here with new equipment but I'd like to do more.\n\nI'd be deeply honored if you would let me work for you in your main garrison." }
WordHunterWoW_QuestEN[34983] = { title = "Dropping Bombs Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34984] = { title = "Supply Recovery Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34985] = { title = "Prized Repossessions Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34986] = { title = "Punching Through Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[34987] = { title = "The Gunpowder Plot", description = "Ey, pal! We got an issue, here.\n\nMe ol' pal Thaelin's rigged together this here plunger out of spare Blackrock parts - engineerin' whiz that he is - but we're gonna need some gunpowder if we really want ta' do any damage.", objectives = "Find a Blackrock Powder Keg and return it to Hansel Heavyhands.", progress = "Don't go doin' anything inappropriate with that gunpowder, now.", completion = "Woo hoo hoo haaaaa!" }
WordHunterWoW_QuestEN[34991] = { title = "To the... Rescue?", description = "The Parchment of Dust reads: \"Put the featherless against one another so that our claws remain unsullied!\" How wise the high Ravenspeaker is to foresee this day.\n\nThere is a great beast on the hillside to the west by the name of Stonescale. It has abducted one of the flock and despite our many attempts we have been unable to defeat it. \n\nGo, prove yourself by slaying the beast and rescuing Tillik! Fulfill your destiny in the name of the Raven Mother!", objectives = "Rescue \"Tillik\" from the beast Stonescale in Gnarlwood Pass.", progress = "Tillik's disappearance caused great sadness to the Flock.", completion = "Tillik! Dear friend I'm so glad you have returned! All of the acolytes missed your witty banter after the evening chants.\n\n<Iktis looks back towards you.>\n\nYes, now your great test is done. You have fulfilled the requirements of The Parchment of Dust!" }
WordHunterWoW_QuestEN[34992] = { title = "Lumber Mill", description = "", objectives = "" }
WordHunterWoW_QuestEN[34993] = { title = "Joining the Ranks", description = "", objectives = "We've had quite the journey in getting your tower up to speed. If it's agreeable to you, I'd like to join your campaign here." }
WordHunterWoW_QuestEN[34994] = { title = "Forever Young", description = "All this sitting around is horrible for business.\n\nI have to find a way to recoup some of my lost profits.\n\nThose Draenei females are obsessed with the way their horns look.\n\nI overheard one of them talking about a root that grows in Blademoon Bloom that supposedly reduces horn shedding or something.\n\nI bet I could sell that root to them for a pretty nice profit.\n\nI'll give you a cut if you help me get a supply going.", objectives = "Pick Youngroot for Beezil.", progress = "Did you find any Youngroot?", completion = "Hmm... How am I going to package this?\n\nI have an idea!\n\n<Beezil writes Youngroot on a label and slaps it onto a bottle of adder oil.>\n\n< He throws the Youngroot in the bushes behind him.>\n\nPerfect!" }
WordHunterWoW_QuestEN[34995] = { title = "Botani Beatdown", description = "Gidwin is doing much better. Thank you, {name}.\n\nI can't believe the draenei have lived alongside those horrible monsters for so long.\n\nMaybe we should show these beasts what happens when you mess with an Azerothian.", objectives = "Kill 5 Botani.", completion = "That's what I'm talking about! Great work out there, <name>." }
WordHunterWoW_QuestEN[34996] = { title = "Rotting Riverbeasts", description = "The botani are infecting the local riverbeasts with some kind of strange flesh-eating plant.\n\nI fear this infection could spread to our people.\n\nIf you see any infested riverbeasts, kill the blooming plants that inhabit their bodies... before they kill you.", objectives = "Kill 5 Blooming Mandroga.", progress = "We need to stop this infestation.", completion = "This new is disturbing to say the least. I'm shocked the infestation has spread so quickly." }
WordHunterWoW_QuestEN[34997] = { title = "Slumberbloom", description = "Huh?... Oh my, I appear to have fallen asleep again.\n\nThese slumberblooms are nothing but trouble. One second I'm fighting botani and the next I'm dreaming I'm an elekk dancing with riverbeasts.\n\n*Yawn* We really should do something about all these slumberbloo *Yawn* ... ZZZZzzzzzzzz\n\n<You gather a small handful of pebbles laying by the sleeping draenei.>", objectives = "Use the Gathered Pebbles to pop the Slumberblooms." }
WordHunterWoW_QuestEN[34998] = { title = "Talon Watch", description = "By now you must be wondering about all of this curse business. What could distort a majestic arakkoa into... well, into this?\n\n<Reshad drags a crooked hand through the mottled feathers about his face.>\n\nA raven is prepped and waiting to fly you to Talon Watch. There shall your eyes be opened to the origin of this curse.\n\nPresent the Eye of Anzu to Talon Guard Kurekk. He will guide you from there.", objectives = "Bring the Eye of Anzu to Talon Guard Kurekk in Talon Watch. Speak with Skytalon Meshaal for a flight.", progress = "Reshad sent an outsider here? You must be very important... or very dangerous.", completion = "<Kurekk gazes at the orb.>\n\nIs that... what I think it is?\n\nWe must get this to the Talon Altar." }
WordHunterWoW_QuestEN[34999] = { title = "Hatred Undying", description = "The blood of the dead god, Sethe, lingers in the pools here. And with it, his hatred of Rukhmar and Anzu.\n\nSo strong was this hate that it animates the blood even now, eons after he was slain by his fellow gods.\n\nI need the congealed blood that holds those spiteful creatures together.\n\nThere is nothing the Adherents fear more than the power of this curse - what if we could brandish it against them?", objectives = "Gather 15 Congealed Blood of Sethe from Sethekk Holllow.", progress = "My attempts to bottle the pooled blood have failed. It breaks down and dissipates when it is taken away from Sethe's bones.\n\nBut I have high hopes for this congealed form!", completion = "Excellent, excellent. Go ahead and drop those directly into the cauldron." }
WordHunterWoW_QuestEN[35000] = { title = "Banished From the Sky", description = "The Adherents have been casting their enemies into the hollow for generations.\n\nThe pools carry Sethe's dying curse, crippling arakkoa with visions of darkness and intense pain. The mind reels, the body writhes, and the wings wither.\n\nMost arakkoa die or go insane. Only the strongest can resist - seek them out and use the Eye of Anzu to help them to their senses.\n\nBeware, for the worshippers of Sethe also prey on these survivors to fill their ranks.", objectives = "Use the Eye of Anzu on 8 Cursed Arakkoa.", completion = "They have suffered a fate worse than death, but at least they are free." }
WordHunterWoW_QuestEN[35001] = { title = "Gaze of the Raven God", description = "The Sethekk are breeding vile wind serpents from Sethe's blood and bones. With these creatures, they will tear apart the sky.\n\nThe nests are protected by powerful magic, but Anzu's gaze should penetrate them with ease.\n\nLet us visit the nests and destroy them!", objectives = "Use the Eye of Anzu at 4 Wind Serpent Nests.", completion = "<As the orb meets the altar, the nearby candles flare up.>" }
WordHunterWoW_QuestEN[35002] = { title = "Sons of Sethe", description = "Many years have passed since anyone has been in contact with Anzu. He faded away, as Terokk did, to take refuge in the shadows.\n\nIf we are to coax him back, we should make an offering.\n\nSethe took the sky from us all - it seems fitting to take the wings of his children.", objectives = "Collect 6 Wind Serpent Wings.", progress = "<A large bowl awaits an offering for the raven god.>", completion = "<Heaping the wings into the bowl, you hear a faint rustling of feathers from somewhere overhead.>" }
WordHunterWoW_QuestEN[35003] = { title = "Ritual Severance", description = "I could not defeat this curse, and long ago resigned myself to rest in darkness.\n\nBut the Sethekk are performing dark rituals to draw me back, slowly binding me to Sethe's will. Should they succeed, Sethe would have me draw a dark cloak across the horizon, and bathe the world in his blood.\n\nDisrupt their rituals, so that I may return with my own free will. Then, together, we shall bring an end to Sethe's return.", objectives = "Stomp out the three Sethekk Ritual Circles by running over them.", completion = "Ah... I feel their grasp slipping.\n\nThank you, mortal." }
WordHunterWoW_QuestEN[35004] = { title = "Servants of a Dead God", description = "Even in death, Sethe exerts influence. The Sethekk cult was born of this influence: led by a false king in service of the dead god.\n\nSilence their prophets, for they seek a future of black seas and blighted skies.\n\nDefeat their chosen champions, for they have pledged themselves to a lie.", objectives = "Slay 6 Sethekk Prophets and 6 Sethekk Chosen in Sethekk Hollow.", completion = "Weapons and zealotry do not make one strong.\n\nThey turned to Sethe because they were too weak to face death." }
WordHunterWoW_QuestEN[35005] = { title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", objectives = "Obtain 30 Blackrock Weapons.", progress = "These prisoners are no less brave than you or I, <name>. Give them a weapon and an ounce of hope and they will fight like the storm.", completion = "Great work, <name>.\n\nDon't put away your weapon yet - now's when the REAL work begins." }
WordHunterWoW_QuestEN[35006] = { title = "Poison Paralysis", description = "There are others from the caravan that have gone missing.\n\nMy guess is they have been taken into Blademoon Bloom by the botani.\n\nYou have to rescue them, {name}. You are our only hope.\n\nHere, take some of this elixir I just made, chances are you will need it.", objectives = "Rescue the missing travelers.", completion = "I can never repay you for all you have done here today, <name>.\n\nI am truly in your debt." }
WordHunterWoW_QuestEN[35007] = { title = "Rendezvous with the Ritualists", description = "Our dear brother Sekara went to the Ravenskar with some of the flock to enact the great ritual of purification.\n\nNo one has been sent back to the nest for supplies in the past day; caught up in prayers I suppose.\n\nI would go check on him but I need to make sure the scribe didn't mess up her transcription of my latest sermon. Could you do it? I'll be there in... well, who knows...", objectives = "Speak to Ravenspeaker Sekara in the Ravenskar.", completion = "At last, our prayers to the Raven Mother have been answered!" }
WordHunterWoW_QuestEN[35008] = { title = "UNUSED", description = "[PH] Now that we're somewhat safer and the texts are returned go report back to the High Ravencaller. We will continue our prayers here.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "[PH] asdf[PH] Now that we're somewhat safer and the texts are returned go report back to the High Ravencaller. We will continue our prayers here.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[35009] = { title = "Call of the Raven Mother", description = "All is now in its place to begin the ritual of calling that will bring the Raven Mother back to the nest.\n\nYou have fulfilled all of the tests we have put before you so it is only fitting that you join with us and participate in the ritual.\n\nSoon the Raven Mother herself will appear before us! Oh my feathers are tingling in excitement!\n\nSpeak to me again when you are ready.", objectives = "Help High Ravenspeaker Krikka with the ritual of calling.", completion = "You have done much to help my little nest of forgotten ones. The poor creatures are not quite sane but with their own kin hunting them I pity their plight.\n\nTheir flying kin, the Adherents you call them, would see the forgotten ones destroyed and my children made into slaves.\n\nThis I must not allow!" }
WordHunterWoW_QuestEN[35010] = { title = "The High Ravenspeaker", description = "Yes, I knew you were worthy!\n\nThe Writ of Faith says that great doubt will come in time of crisis but one must put their trust in the Raven Mother and all will be as it should!\n\nCome, come, we must go to the High Ravenspeaker!", objectives = "Locate High Ravenspeaker Krikka", completion = "In the whispers of the Raven Mother, blessed she be, it was foretold in the Scroll of Order that upon calling for a sign that we would receive one within thirty minutes or less.\n\nThis is most fortunate, for we have already begun our preparations for her arrival and we have need of your assistance." }
WordHunterWoW_QuestEN[35011] = { title = "The False Talon King", description = "Ikiss was once a respected sage among the Adherents, but his search for the truth of Terokk's fall led to his own banishment.\n\nIkiss became obsessed with Terokk, even claiming to be the old hero reborn. He commands the Sethekk, promising untold power in a new age of darkness.\n\nKnow this: Ikiss is no Talon King. Slay the delusional fool, and search him for anything useful. He is known to collect powerful trinkets.", objectives = "Retrieve the Scuffed Bangle from Talon King Ikiss.", progress = "Have you silenced the false king?", completion = "A bracelet? Interesting... rather plain looking..." }
WordHunterWoW_QuestEN[35012] = { title = "Sethe, the Dead God", description = "The time has come to put an end to Sethe. I killed him before, and with your help I shall do it again.\n\nReady yourself for a fight - the cultists will not stand idly by while we stamp out their god.", objectives = "Help Anzu defeat Sethe in the Broken Spire.", completion = "Sethe has died twice, but his curse lives on. It seems we will never be rid of it." }
WordHunterWoW_QuestEN[35013] = { title = "Lithic's Gift", description = "<Kurekk squints at the bangle, rotating it slowly in his claws.>\n\nThere is an inscription on the inside.\n\n\"To my father, may Rukhmar illuminate your path. With love, Lithic.\"\n\nIt cannot be... This is Terokk's bangle! It was a gift from his daughter, he wore it for years until...\n\nWell, we had better return it.\n\nTerokk built a memorial to Lithic not far from Talon Watch. It should rest there.", objectives = "Bring the Scuffed Bangle to Lithic's Rest.", progress = "Who... are you? Why have you stirred me?", completion = "That bracelet... I made it for father long ago.\n\nBefore the fall..." }
WordHunterWoW_QuestEN[35014] = { title = "Blademoon Bloom", description = "We are out of options.\n\nI'm going into the bloom to find out what's going on. I'll meet you inside.\n\nGoodluck, {class}.", objectives = "Meet Rangari Arepheon inside Blademoon Bloom.", completion = "Good, you made it. I need your help." }
WordHunterWoW_QuestEN[35015] = { title = "Gestating Genesaur", description = "This is bad. A genesaur is starting to sprout right here in the bloom.\n\nThis is the first reported case of a genesaur being born in draenor in over three hundred years.\n\nNo wonder the botani have been acting so crazy. They are bringing back bodies to fertilize that monstrosity.\n\nWe have to kill it before it gets any larger. Once fully grown there is no stopping that beast.", objectives = "Kill the genesaur.", progress = "I never thought I would see a genesaur in my lifetime.", completion = "That was close.\n\nIf that genesaur would have grown any larger we would have needed an army to destroy it.\n\nThank you for all your help." }
WordHunterWoW_QuestEN[35016] = { title = "Basic Skulltaking", description = "My hunters are all dead, you will be my hunting pack now.\n\nFind their bodies and take their skulls.  I will choose which to honor and which to cast aside.  It is our way.\n\nI will go further and see what other skulls may be found here.", objectives = "Take the skulls from 5 dead Skulltakers.", progress = "Afraid to get your hands dirty?  They are just bodies now, no need to be scared.", completion = "This red slime covers everything, even the skulls of my hunters!  I'll make a Skulltaker of you yet though, great work!" }
WordHunterWoW_QuestEN[35017] = { title = "Skulltaker's Revenge", description = "The others... gone or wandered into the haze.  It called to me as well but I am too strong.  I chose to kill until they crushed my body.  I haven't killed enough of them yet {name}, not enough!  Go.  Kill more of them and tell my hunt leader that I don't go alone into the dark.", objectives = "Kill 7 Fungal Lurchers.", completion = "Hah!  If he was that strong he'd still be alive.  Still it is good you did him honor.  Did you take his skull by any chance?" }
WordHunterWoW_QuestEN[35018] = { title = "Vignette: Felbark", description = "", objectives = "" }
WordHunterWoW_QuestEN[35019] = { title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", objectives = "Obtain 30 Blackrock Weapons.", progress = "These prisoners are no less brave than you or I, <name>. Give them a weapon and an ounce of hope and they will fight like the storm.", completion = "Great work, <name>.\n\nDon't put away your weapon yet - now's when the REAL work begins." }
WordHunterWoW_QuestEN[35020] = { title = "Jared's Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[35021] = { title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.  Grulkor might know more about this.", objectives = "Bring the Glowing Red Pod to Grulkor at Crimson Fen.\n\nProvided item:", completion = "What's this?  Let me check if it has a skull..." }
WordHunterWoW_QuestEN[35022] = { title = "Lighting The Darkness", description = "The spirits of my ancestors have always been drawn to the mountain of Oshu'gun. Now, I too feel this pull deep within my soul...but something is not right.\n\nThe presence that beckons us has grown dark and ominous. It consumes the souls of the dead, the souls of my ancestors, {name}.\n\nSomething must be done.\n\nTake hold of the spirit torch and light the ceremonial pyres in the Ancestral Grounds.\n\nThe flame of the spirit torch upon the pyres will calm the restless spirits being drawn into the void.", objectives = "Use the Spirit Torch to light the Ceremonial Pyres within the Ancestral Grounds.", completion = "Now that the flame of the spirit torch is upon the pyres, the spirits of my ancestors have been insulated from the call of the void within Oshu'gun.\n\nHowever, more must still be done if the spirits here are to rest peacefully." }
WordHunterWoW_QuestEN[35023] = { title = "Echoes of the Past", description = "When a spirit is consumed by the void, an echo of the soul is all that is left behind.\n\nNeither in the physical or spiritual sense of the word would these echoes be considered 'alive.' The echo is merely a twisted reverberation of the anguish left behind by the soul as it is consumed.\n\nIf left unchecked, the echoes will lash out against the living and stir the spirits of the dead from their graves.\n\nIn order to restore peace to the Ancestral Grounds, these echoes must be put to rest.", objectives = "Slay 8 Tormented Echoes.", completion = "Do not mourn the twisted echoes of the dead, they are merely the distorted reflections of once noble spirits.\n\nInstead, mourn the loss of those souls consumed by the dark void that grows within Oshu'gun." }
WordHunterWoW_QuestEN[35024] = { title = "Golmash Hellscream", description = "Those who die in brutal combat often enter the spirit world in unrest. So it was with Golmash, father of Grommash Hellscream.\n\nCrushed within the jaws of a hulking gronn, Golmash still found the strength to bury his axe Gorehowl deep into the eye of the monster. When they fell, it was the gronn who died first.\n\nSuch is the heroic death that every Warsong dreams of, yet few attain. But Golmash's mighty spirit lingers restlessly, stirring the other spirits into unrest.\n\nPut his mighty soul to rest, {name}.", objectives = "Defeat the spirit of Golmash Hellscream.", progress = "Have you brought peace to the spirit of Golmash Hellscream?", completion = "Golmash was a mighty warrior in life.\n\nFew orcs have been as honored by their clans and feared by their enemies as the great Giantslayer... the father of the Hellscream name. With the mighty spirit of Golmash Hellscream finally put to rest, the ancestral grounds may once again be a place of peace and reverence.\n\nYou have our thanks, <name>." }
WordHunterWoW_QuestEN[35025] = { title = "We Have Company", description = "Outsider, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf you do not deal with their presence, they will surely be a threat to your camp.", objectives = "Investigate the Iron Horde camp in Sulfur Basin.", completion = "Thank you, friend. I am in your debt.\n\nThis arrogant Iron Horde has made a dangerous enemy today." }
WordHunterWoW_QuestEN[35026] = { title = "On the Mend", description = "Nisha will heal.\n\nThis ordeal has taken a toll on her. She needs water and rest.\n\nI will bring her to my camp and make her comfortable.\n\nWill you meet us there with some fresh water?", objectives = "Recover 100 Quenching Waters from Steamfury elementals.", progress = "<Nisha raises her head.>", completion = "<Nisha laps up the water.>" }
WordHunterWoW_QuestEN[35027] = { title = "Clearing the Way", description = "The dead ones were the strong ones it seems. The weak ones wander about killing invaders to this marsh.\n\nIt feels... wrong... to kill them, but they are worthless and get in our way. Kill these shambling fools so we can move further into the marsh easily.", objectives = "Kill 6 Fungus Covered Shamblers.", progress = "Have you taken care of those walking corpses?", completion = "You take too long. Something calls to us deeper in there. Whatever it is, I will have its skull or die trying." }
WordHunterWoW_QuestEN[35028] = { title = "Krikka and Vakora Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[35029] = { title = "The Secret of the Fungus", description = "It smells here and there are whispers.\n\nI feel there is a connection between the plants and beasts here. Special mushrooms seem to focus the beasts' attention.\n\nGo and get some of these for me. I... need... them.", objectives = "Collect 5 Glowing Mushrooms.", progress = "Where are my mushrooms?!", completion = "Yes, they smell... wonderful. These will help me find the power of this marsh and take it for my own." }
WordHunterWoW_QuestEN[35030] = { title = "A Grim Harvest", description = "The larger monsters are the key to my destiny, I can feel it. The pods growing on them are even bigger than the one you brought me earlier.  Get me a few of these, they will be... helpful... soon.", objectives = "Bring Grulkor 3 Spore Pods from the Fungal Stompers.", progress = "I need more of those pods!  Many more!", completion = "These will aid me greatly.  I must consume them and take their power.  We are close to the end <name>, I can feel it." }
